export const BOOTSTRAP_SQL = "-- =============================================================================\n-- SÓLO DESARROLLO LOCAL / PRUEBAS. En Supabase estos roles y esquemas ya existen.\n-- Reproduce los roles de Supabase para que RLS se comporte igual que en producción.\n-- =============================================================================\ndo $$\nbegin\n  if not exists (select 1 from pg_roles where rolname = 'anon') then\n    create role anon nologin noinherit;\n  end if;\n  if not exists (select 1 from pg_roles where rolname = 'authenticated') then\n    create role authenticated nologin noinherit;\n  end if;\n  if not exists (select 1 from pg_roles where rolname = 'service_role') then\n    create role service_role nologin noinherit bypassrls;\n  end if;\n  if not exists (select 1 from pg_roles where rolname = 'supabase_auth_admin') then\n    create role supabase_auth_admin login noinherit createrole password 'auth_dev_only';\n  end if;\n  if not exists (select 1 from pg_roles where rolname = 'dasilva_app') then\n    -- Rol con el que se conecta el servidor Next.js en local. No es superusuario\n    -- ni BYPASSRLS: para operar como usuario hace SET LOCAL ROLE authenticated.\n    create role dasilva_app login password 'dasilva_app_dev_only';\n  end if;\nend $$;\n\ngrant anon, authenticated, service_role to dasilva_app;\n\ncreate schema if not exists auth authorization supabase_auth_admin;\nalter role supabase_auth_admin set search_path = auth;\ngrant usage on schema auth to anon, authenticated, service_role, dasilva_app;\ngrant create on database current_database_placeholder to supabase_auth_admin;\n";
export const AUTH_SHIM_SQL = "-- =============================================================================\n-- SÓLO PRUEBAS: sustituto mínimo del esquema auth de Supabase cuando no se\n-- ejecuta Supabase Auth (GoTrue). Reproduce auth.users y auth.uid() con la\n-- misma lectura de claims JWT que usa Supabase.\n-- =============================================================================\ncreate table if not exists auth.users (\n  id          uuid primary key,\n  email       text unique,\n  created_at  timestamptz not null default now()\n);\n\ncreate or replace function auth.uid()\nreturns uuid\nlanguage sql stable\nas $$\n  select coalesce(\n    nullif(current_setting('request.jwt.claim.sub', true), ''),\n    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')\n  )::uuid\n$$;\n\ngrant select on auth.users to service_role;\ngrant execute on function auth.uid() to anon, authenticated, service_role;\n";
export const MIGRATIONS: ReadonlyArray<{ name: string; sql: string }> = [{"name":"20261022000100_foundation.sql","sql":"-- =============================================================================\n-- Da Silva OS — Fundación: organizaciones, usuarios, roles, permisos, auditoría\n-- =============================================================================\n-- Convenciones:\n--   * Importes: numeric(18,2) + código de moneda explícito (ISO 4217).\n--     PYG no admite decimales; USD admite 2 (ver app.currency_decimals).\n--   * Estados: text + CHECK (más fácil de evolucionar que los ENUM nativos).\n--   * Toda tabla de negocio lleva org_id y RLS habilitado.\n--   * Las operaciones críticas se ejecutan mediante funciones transaccionales\n--     (ver *_rpc.sql); las tablas financieras son append-only.\n-- =============================================================================\n\ncreate extension if not exists pgcrypto;\ncreate extension if not exists btree_gist;\n\ncreate schema if not exists app;\ncomment on schema app is 'Funciones internas de Da Silva OS (no expuestas por la API de datos).';\n\n-- Nadie fuera de los propietarios puede crear objetos en public.\nrevoke create on schema public from public;\n\n-- -----------------------------------------------------------------------------\n-- Monedas\n-- -----------------------------------------------------------------------------\ncreate table public.currencies (\n  code      char(3) primary key,\n  name      text not null,\n  decimals  smallint not null check (decimals between 0 and 4),\n  symbol    text not null\n);\n\ninsert into public.currencies (code, name, decimals, symbol) values\n  ('PYG', 'Guaraní paraguayo', 0, '₲'),\n  ('USD', 'Dólar estadounidense', 2, 'US$');\n\n-- Inmutable para poder usarse en CHECK. Agregar una moneda requiere migración.\ncreate or replace function app.currency_decimals(p_currency text)\nreturns smallint language sql immutable parallel safe as $$\n  select case p_currency when 'PYG' then 0::smallint when 'USD' then 2::smallint else null end\n$$;\n\ncreate or replace function app.money_ok(p_amount numeric, p_currency text)\nreturns boolean language sql immutable parallel safe as $$\n  select p_amount is null\n      or (app.currency_decimals(p_currency) is not null\n          and p_amount = round(p_amount, app.currency_decimals(p_currency)))\n$$;\n\ncreate or replace function app.round_money(p_amount numeric, p_currency text)\nreturns numeric language sql immutable parallel safe as $$\n  select round(p_amount, app.currency_decimals(p_currency))\n$$;\n\n-- Importe formateado para mensajes al usuario: \"Gs. 1.500.000\" / \"US$ 45.000,50\".\ncreate or replace function app.fmt_money(p_amount numeric, p_currency text)\nreturns text language sql immutable parallel safe as $$\n  select case p_currency\n    when 'PYG' then 'Gs. ' || translate(to_char(round(p_amount, 0), 'FM999,999,999,999,990'), ',', '.')\n    when 'USD' then 'US$ ' || translate(to_char(p_amount, 'FM999,999,999,990.00'), ',.', '.,')\n    else coalesce(p_amount::text, '') || ' ' || coalesce(p_currency, '')\n  end\n$$;\n\n-- -----------------------------------------------------------------------------\n-- Organizaciones y sucursales\n-- -----------------------------------------------------------------------------\ncreate table public.organizations (\n  id              uuid primary key default gen_random_uuid(),\n  name            text not null,\n  legal_name      text,\n  tax_id          text,                       -- RUC\n  base_currency   char(3) not null default 'PYG' references public.currencies(code),\n  timezone        text not null default 'America/Asuncion',\n  is_demo         boolean not null default false,\n  created_at      timestamptz not null default now()\n);\ncomment on column public.organizations.is_demo is\n  'Organización de demostración. Sus datos están aislados de las organizaciones reales y la interfaz lo indica.';\n\ncreate table public.branches (\n  id          uuid primary key default gen_random_uuid(),\n  org_id      uuid not null references public.organizations(id) on delete cascade,\n  name        text not null,\n  address     text,\n  city        text,\n  is_active   boolean not null default true,\n  created_at  timestamptz not null default now(),\n  unique (org_id, name),\n  unique (id, org_id)\n);\n\n-- -----------------------------------------------------------------------------\n-- Usuarios\n-- -----------------------------------------------------------------------------\ncreate table public.user_profiles (\n  id          uuid primary key references auth.users(id) on delete cascade,\n  full_name   text not null,\n  phone       text,\n  is_active   boolean not null default true,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now()\n);\n\ncreate table public.roles (\n  key          text primary key,\n  name         text not null,\n  description  text not null,\n  sort_order   smallint not null\n);\n\ninsert into public.roles (key, name, description, sort_order) values\n  ('director',           'Director',              'Propietario o dirección general. Acceso total y aprobaciones.', 1),\n  ('administracion',     'Administración',        'Contratos, documentación, pagos y proveedores.', 2),\n  ('gerencia_comercial', 'Gerencia comercial',    'Equipo de ventas, precios, descuentos y tasaciones.', 3),\n  ('vendedor',           'Vendedor',              'Clientes propios, oportunidades, propuestas y reservas.', 4),\n  ('cobranzas',          'Cobranzas',             'Cartera, mora, gestiones y registro de cobros.', 5),\n  ('inventario',         'Inventario',            'Altas de unidades, costes, preparación y documentación.', 6),\n  ('finanzas',           'Finanzas',              'Caja, conciliación, cuentas por pagar y reportes.', 7),\n  ('auditor',            'Auditor',               'Lectura completa y auditoría. Sin permisos de escritura.', 8),\n  ('admin_tecnico',      'Administrador técnico', 'Usuarios, configuración y auditoría técnica. Sin datos financieros.', 9);\n\ncreate table public.permissions (\n  key          text primary key,\n  module       text not null,\n  description  text not null\n);\n\ninsert into public.permissions (key, module, description) values\n  ('dashboard.view',              'direccion',   'Ver el tablero de dirección con indicadores financieros'),\n  ('inventory.view',              'inventario',  'Ver unidades, precios de lista y disponibilidad'),\n  ('inventory.create',            'inventario',  'Dar de alta unidades'),\n  ('inventory.edit',              'inventario',  'Editar ficha técnica, ubicación y estados físicos'),\n  ('inventory.pricing.edit',      'inventario',  'Modificar precio de lista y precio mínimo'),\n  ('inventory.costs.view',        'inventario',  'Ver costes, coste total y márgenes'),\n  ('inventory.costs.create',      'inventario',  'Registrar costes atribuibles a una unidad'),\n  ('inventory.costs.edit_history','inventario',  'Corregir costes ya registrados (queda auditado)'),\n  ('customers.view',              'clientes',    'Ver clientes asignados o creados por el usuario'),\n  ('customers.view_all',          'clientes',    'Ver todos los clientes'),\n  ('customers.create',            'clientes',    'Crear clientes'),\n  ('customers.edit',              'clientes',    'Editar clientes'),\n  ('crm.manage',                  'clientes',    'Gestionar oportunidades, interacciones y etapas'),\n  ('deals.view',                  'ventas',      'Ver operaciones propias'),\n  ('deals.view_all',              'ventas',      'Ver todas las operaciones'),\n  ('deals.create',                'ventas',      'Crear y editar operaciones en borrador'),\n  ('deals.approve',               'ventas',      'Aprobar descuentos y precios bajo el mínimo'),\n  ('deals.formalize',             'ventas',      'Formalizar ventas (contrato y plan de pagos)'),\n  ('deals.deliver',               'ventas',      'Registrar entrega física'),\n  ('deals.cancel',                'ventas',      'Anular operaciones'),\n  ('reservations.manage',         'ventas',      'Crear y anular reservas'),\n  ('contracts.view',              'financiacion','Ver contratos, planes y cuotas'),\n  ('contracts.adjust',            'financiacion','Solicitar recargos, notas de crédito, ajustes y refinanciaciones'),\n  ('contracts.approve',           'financiacion','Aprobar recargos, notas de crédito, ajustes y refinanciaciones'),\n  ('payments.view',               'cobranzas',   'Ver pagos de clientes'),\n  ('payments.register',           'cobranzas',   'Registrar pagos recibidos (pendientes de confirmación)'),\n  ('payments.confirm',            'cobranzas',   'Confirmar pagos y aplicarlos a cuotas'),\n  ('payments.reverse',            'cobranzas',   'Revertir pagos confirmados'),\n  ('collections.view',            'cobranzas',   'Ver cartera, mora y gestiones'),\n  ('collections.manage',          'cobranzas',   'Registrar gestiones y compromisos de pago'),\n  ('collections.assign',          'cobranzas',   'Asignar responsables de cobranza'),\n  ('tradein.view',                'tradein',     'Ver tasaciones'),\n  ('tradein.create',              'tradein',     'Registrar tasaciones e inspecciones'),\n  ('tradein.approve',             'tradein',     'Aprobar o rechazar tasaciones'),\n  ('tradein.acquire',             'tradein',     'Formalizar la adquisición e ingresar al inventario'),\n  ('suppliers.view',              'compras',     'Ver proveedores'),\n  ('suppliers.manage',            'compras',     'Crear y editar proveedores'),\n  ('payables.view',               'compras',     'Ver facturas y cuentas por pagar'),\n  ('payables.create',             'compras',     'Registrar facturas de proveedores'),\n  ('payables.approve',            'compras',     'Aprobar facturas de proveedores'),\n  ('payables.pay',                'compras',     'Registrar y confirmar pagos a proveedores'),\n  ('expenses.view',               'gastos',      'Ver gastos'),\n  ('expenses.create',             'gastos',      'Registrar gastos'),\n  ('expenses.approve',            'gastos',      'Aprobar gastos'),\n  ('cash.view',                   'caja',        'Ver cuentas y movimientos registrados'),\n  ('cash.register',               'caja',        'Registrar movimientos manuales'),\n  ('cash.reverse',                'caja',        'Revertir movimientos'),\n  ('cash.reconcile',              'caja',        'Conciliar cuentas'),\n  ('reports.view',                'reportes',    'Ver reportes de dirección'),\n  ('reports.export',              'reportes',    'Exportar reportes'),\n  ('audit.view',                  'auditoria',   'Consultar la auditoría'),\n  ('documents.view_restricted',   'documentos',  'Ver documentos marcados como restringidos'),\n  ('settings.manage',             'configuracion','Modificar configuración de la organización'),\n  ('users.manage',                'configuracion','Gestionar usuarios y roles');\n\ncreate table public.role_permissions (\n  role        text not null references public.roles(key) on delete cascade,\n  permission  text not null references public.permissions(key) on delete cascade,\n  primary key (role, permission)\n);\n\n-- Matriz inicial. Fuente de verdad única; src/domain/permissions la refleja y\n-- una prueba verifica que ambas coincidan.\ninsert into public.role_permissions (role, permission)\nselect 'director', key from public.permissions;\n\ninsert into public.role_permissions (role, permission)\nselect 'auditor', key from public.permissions\nwhere key like '%.view' or key like '%.view_all' or key in ('reports.export', 'documents.view_restricted');\n\ninsert into public.role_permissions (role, permission) select 'administracion', unnest(array[\n  'dashboard.view','inventory.view','inventory.costs.view','inventory.costs.create',\n  'customers.view','customers.view_all','customers.create','customers.edit',\n  'deals.view','deals.view_all','deals.formalize','deals.deliver',\n  'contracts.view','contracts.adjust','payments.view','payments.register','payments.confirm',\n  'collections.view','tradein.view','suppliers.view','suppliers.manage',\n  'payables.view','payables.create','expenses.view','expenses.create',\n  'cash.view','cash.register','reports.view','documents.view_restricted']);\n\ninsert into public.role_permissions (role, permission) select 'gerencia_comercial', unnest(array[\n  'dashboard.view','inventory.view','inventory.pricing.edit','inventory.costs.view',\n  'customers.view','customers.view_all','customers.create','customers.edit','crm.manage',\n  'deals.view','deals.view_all','deals.create','deals.approve','deals.formalize','deals.deliver','deals.cancel',\n  'reservations.manage','contracts.view','payments.view','collections.view',\n  'tradein.view','tradein.create','tradein.approve','reports.view']);\n\ninsert into public.role_permissions (role, permission) select 'vendedor', unnest(array[\n  'inventory.view','customers.view','customers.create','customers.edit','crm.manage',\n  'deals.view','deals.create','reservations.manage','tradein.view','tradein.create']);\n\ninsert into public.role_permissions (role, permission) select 'cobranzas', unnest(array[\n  'customers.view','customers.view_all','contracts.view','payments.view','payments.register',\n  'collections.view','collections.manage','collections.assign']);\n\ninsert into public.role_permissions (role, permission) select 'inventario', unnest(array[\n  'inventory.view','inventory.create','inventory.edit','inventory.costs.view','inventory.costs.create',\n  'tradein.view','tradein.acquire','suppliers.view','payables.view','payables.create','expenses.view']);\n\ninsert into public.role_permissions (role, permission) select 'finanzas', unnest(array[\n  'dashboard.view','inventory.view','inventory.costs.view','inventory.costs.edit_history',\n  'customers.view','customers.view_all','deals.view','deals.view_all',\n  'contracts.view','contracts.adjust','contracts.approve',\n  'payments.view','payments.register','payments.confirm','payments.reverse',\n  'collections.view','collections.assign','tradein.view','tradein.acquire',\n  'suppliers.view','suppliers.manage','payables.view','payables.create','payables.approve','payables.pay',\n  'expenses.view','expenses.create','expenses.approve',\n  'cash.view','cash.register','cash.reverse','cash.reconcile',\n  'reports.view','reports.export','documents.view_restricted']);\n\ninsert into public.role_permissions (role, permission) select 'admin_tecnico', unnest(array[\n  'audit.view','settings.manage','users.manage']);\n\ncreate table public.memberships (\n  id          uuid primary key default gen_random_uuid(),\n  org_id      uuid not null references public.organizations(id) on delete cascade,\n  user_id     uuid not null references public.user_profiles(id) on delete cascade,\n  role        text not null references public.roles(key),\n  branch_id   uuid,\n  is_active   boolean not null default true,\n  created_at  timestamptz not null default now(),\n  unique (org_id, user_id),\n  foreign key (branch_id, org_id) references public.branches(id, org_id)\n);\ncreate index memberships_user_idx on public.memberships(user_id) where is_active;\n\n-- -----------------------------------------------------------------------------\n-- Helpers de seguridad\n-- -----------------------------------------------------------------------------\ncreate or replace function app.uid()\nreturns uuid language sql stable as $$ select auth.uid() $$;\n\n-- ¿La sentencia se ejecuta dentro de una función transaccional del sistema?\n-- Dentro de una función SECURITY DEFINER, current_user es su propietario; en\n-- DML directo de un usuario es \"authenticated\" (o \"anon\"). No es falsificable\n-- desde la sesión del usuario, a diferencia de una variable de configuración.\n-- No debe declararse SECURITY DEFINER.\ncreate or replace function app.is_trusted()\nreturns boolean language sql stable as $$\n  select current_user not in ('authenticated', 'anon')\n$$;\n\n-- ¿El usuario actual tiene el permiso en la organización?\ncreate or replace function app.has_perm(p_org uuid, p_perm text)\nreturns boolean\nlanguage sql stable security definer\nset search_path = public, pg_temp\nas $$\n  select exists (\n    select 1\n    from public.memberships m\n    join public.user_profiles u on u.id = m.user_id and u.is_active\n    join public.role_permissions rp on rp.role = m.role\n    where m.org_id = p_org\n      and m.user_id = auth.uid()\n      and m.is_active\n      and rp.permission = p_perm\n  )\n$$;\n\ncreate or replace function app.is_member(p_org uuid)\nreturns boolean\nlanguage sql stable security definer\nset search_path = public, pg_temp\nas $$\n  select exists (\n    select 1 from public.memberships m\n    join public.user_profiles u on u.id = m.user_id and u.is_active\n    where m.org_id = p_org and m.user_id = auth.uid() and m.is_active\n  )\n$$;\n\ncreate or replace function app.user_role(p_org uuid)\nreturns text\nlanguage sql stable security definer\nset search_path = public, pg_temp\nas $$\n  select m.role from public.memberships m\n  where m.org_id = p_org and m.user_id = auth.uid() and m.is_active\n$$;\n\n-- Lanza una excepción legible si falta el permiso. Usado por las RPC.\ncreate or replace function app.require_perm(p_org uuid, p_perm text)\nreturns void\nlanguage plpgsql stable\nas $$\nbegin\n  if auth.uid() is null then\n    raise exception 'Sesión no válida' using errcode = '28000';\n  end if;\n  if not app.has_perm(p_org, p_perm) then\n    raise exception 'No tiene permiso para esta operación (%)', p_perm using errcode = '42501';\n  end if;\nend $$;\n\ncreate or replace function app.org_today(p_org uuid)\nreturns date\nlanguage sql stable\nset search_path = public, pg_temp\nas $$\n  select (now() at time zone coalesce((select timezone from public.organizations where id = p_org), 'America/Asuncion'))::date\n$$;\n\n-- -----------------------------------------------------------------------------\n-- Auditoría (append-only)\n-- -----------------------------------------------------------------------------\ncreate table public.audit_events (\n  id           bigint generated always as identity primary key,\n  org_id       uuid references public.organizations(id) on delete cascade,\n  actor_id     uuid,\n  action       text not null,                 -- insert | update | delete | <acción de negocio>\n  entity_type  text not null,\n  entity_id    text,\n  summary      text,\n  before_data  jsonb,\n  after_data   jsonb,\n  occurred_at  timestamptz not null default now()\n);\ncreate index audit_events_org_time_idx on public.audit_events(org_id, occurred_at desc);\ncreate index audit_events_entity_idx on public.audit_events(entity_type, entity_id);\n\ncreate or replace function app.audit(p_org uuid, p_action text, p_entity_type text, p_entity_id text,\n                                     p_summary text, p_before jsonb default null, p_after jsonb default null)\nreturns void\nlanguage sql\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  insert into public.audit_events (org_id, actor_id, action, entity_type, entity_id, summary, before_data, after_data)\n  values (p_org, auth.uid(), p_action, p_entity_type, p_entity_id, p_summary, p_before, p_after)\n$$;\n\n-- Trigger genérico para tablas sensibles. Registra el diff completo.\ncreate or replace function app.audit_row()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_org uuid;\n  v_id  text;\nbegin\n  if tg_op = 'DELETE' then\n    v_org := (to_jsonb(old) ->> 'org_id')::uuid;\n    v_id  := to_jsonb(old) ->> 'id';\n  else\n    v_org := (to_jsonb(new) ->> 'org_id')::uuid;\n    v_id  := to_jsonb(new) ->> 'id';\n  end if;\n  if tg_op = 'UPDATE' and to_jsonb(old) = to_jsonb(new) then\n    return new;\n  end if;\n  insert into public.audit_events (org_id, actor_id, action, entity_type, entity_id, before_data, after_data)\n  values (v_org, auth.uid(), lower(tg_op), tg_table_name, v_id,\n          case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,\n          case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end);\n  return coalesce(new, old);\nend $$;\n\n-- Impide UPDATE/DELETE en tablas append-only.\ncreate or replace function app.forbid_mutation()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  raise exception 'Los registros de % no se pueden modificar ni borrar. Utilice una reversión auditable.', tg_table_name\n    using errcode = '55000';\nend $$;\n\ncreate trigger audit_events_immutable\n  before update or delete on public.audit_events\n  for each row execute function app.forbid_mutation();\n\n-- updated_at automático\ncreate or replace function app.touch_updated_at()\nreturns trigger language plpgsql as $$\nbegin\n  new.updated_at := now();\n  return new;\nend $$;\n\ncreate trigger user_profiles_touch before update on public.user_profiles\n  for each row execute function app.touch_updated_at();\n\ncreate trigger memberships_audit after insert or update or delete on public.memberships\n  for each row execute function app.audit_row();\n\n-- -----------------------------------------------------------------------------\n-- Numeración de documentos (sin huecos dentro de una transacción confirmada)\n-- -----------------------------------------------------------------------------\ncreate table public.document_sequences (\n  org_id      uuid not null references public.organizations(id) on delete cascade,\n  kind        text not null,\n  year        integer not null,\n  last_value  integer not null default 0,\n  primary key (org_id, kind, year)\n);\n\ncreate or replace function app.next_number(p_org uuid, p_kind text, p_prefix text)\nreturns text\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_year integer := extract(year from app.org_today(p_org))::integer;\n  v_val  integer;\nbegin\n  insert into public.document_sequences (org_id, kind, year, last_value)\n  values (p_org, p_kind, v_year, 1)\n  on conflict (org_id, kind, year) do update set last_value = public.document_sequences.last_value + 1\n  returning last_value into v_val;\n  return p_prefix || '-' || v_year || '-' || lpad(v_val::text, 5, '0');\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Tipos de cambio (carga manual; sin integración externa)\n-- -----------------------------------------------------------------------------\ncreate table public.exchange_rates (\n  id             uuid primary key default gen_random_uuid(),\n  org_id         uuid not null references public.organizations(id) on delete cascade,\n  rate_date      date not null,\n  from_currency  char(3) not null references public.currencies(code),\n  to_currency    char(3) not null references public.currencies(code),\n  rate           numeric(18,6) not null check (rate > 0),\n  source         text not null default 'manual',\n  created_by     uuid references public.user_profiles(id),\n  created_at     timestamptz not null default now(),\n  check (from_currency <> to_currency),\n  unique (org_id, rate_date, from_currency, to_currency)\n);\ncomment on table public.exchange_rates is\n  'Tipos de cambio registrados manualmente por la organización. No provienen de una integración bancaria ni del BCP.';\n\n-- Tipo de cambio vigente (último registrado hasta la fecha). Null si no hay.\ncreate or replace function app.fx_rate(p_org uuid, p_from text, p_to text, p_date date)\nreturns numeric\nlanguage sql stable\nset search_path = public, pg_temp\nas $$\n  select case\n    when p_from = p_to then 1::numeric\n    else coalesce(\n      (select rate from public.exchange_rates\n        where org_id = p_org and from_currency = p_from and to_currency = p_to and rate_date <= p_date\n        order by rate_date desc limit 1),\n      (select 1 / rate from public.exchange_rates\n        where org_id = p_org and from_currency = p_to and to_currency = p_from and rate_date <= p_date\n        order by rate_date desc limit 1))\n  end\n$$;\n\n-- -----------------------------------------------------------------------------\n-- Configuración de la organización\n-- -----------------------------------------------------------------------------\ncreate table public.org_settings (\n  org_id                         uuid primary key references public.organizations(id) on delete cascade,\n  max_discount_pct_without_approval numeric(5,2) not null default 3.00 check (max_discount_pct_without_approval between 0 and 100),\n  reservation_default_days       integer not null default 7 check (reservation_default_days between 1 and 90),\n  aging_alert_days               integer not null default 90 check (aging_alert_days > 0),\n  proposal_validity_days         integer not null default 7 check (proposal_validity_days between 1 and 60),\n  payables_due_soon_days         integer not null default 7 check (payables_due_soon_days between 1 and 60),\n  default_rate_convention        text not null default 'nominal_annual'\n                                 check (default_rate_convention in ('nominal_annual','effective_annual','monthly')),\n  updated_at                     timestamptz not null default now()\n);\n\ncreate table public.aging_buckets (\n  id         uuid primary key default gen_random_uuid(),\n  org_id     uuid not null references public.organizations(id) on delete cascade,\n  label      text not null,\n  min_days   integer not null check (min_days >= 0),\n  max_days   integer check (max_days is null or max_days >= min_days),\n  sort_order smallint not null,\n  unique (org_id, sort_order)\n);\ncomment on table public.aging_buckets is 'Tramos de mora configurables. min_days=0 representa \"al día\".';\n\n-- Crea configuración y tramos por defecto al crear una organización.\ncreate or replace function app.init_org_defaults()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  insert into public.org_settings (org_id) values (new.id);\n  insert into public.aging_buckets (org_id, label, min_days, max_days, sort_order) values\n    (new.id, 'Al día',        0,  0,   1),\n    (new.id, '1–30 días',     1,  30,  2),\n    (new.id, '31–60 días',    31, 60,  3),\n    (new.id, '61–90 días',    61, 90,  4),\n    (new.id, 'Más de 90 días',91, null,5);\n  return new;\nend $$;\n\ncreate trigger organizations_defaults after insert on public.organizations\n  for each row execute function app.init_org_defaults();\n\ncreate trigger org_settings_audit after update on public.org_settings\n  for each row execute function app.audit_row();\n"},{"name":"20261022000200_inventory.sql","sql":"-- =============================================================================\n-- Da Silva OS — Inventario, proveedores y documentos\n-- =============================================================================\n\ncreate table public.brands (\n  id          uuid primary key default gen_random_uuid(),\n  org_id      uuid not null references public.organizations(id) on delete cascade,\n  name        text not null,\n  is_active   boolean not null default true,\n  sort_order  smallint not null default 0,\n  unique (org_id, name),\n  unique (id, org_id)\n);\n\ncreate table public.vehicle_categories (\n  id       uuid primary key default gen_random_uuid(),\n  org_id   uuid not null references public.organizations(id) on delete cascade,\n  name     text not null,\n  unique (org_id, name),\n  unique (id, org_id)\n);\n\ncreate table public.suppliers (\n  id          uuid primary key default gen_random_uuid(),\n  org_id      uuid not null references public.organizations(id) on delete cascade,\n  name        text not null,\n  tax_id      text,\n  kind        text not null default 'general'\n              check (kind in ('vehiculos','transporte','reparacion','documentacion','general')),\n  phone       text,\n  email       text,\n  address     text,\n  notes       text,\n  is_active   boolean not null default true,\n  created_by  uuid references public.user_profiles(id),\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  unique (id, org_id)\n);\ncreate unique index suppliers_tax_id_uq on public.suppliers(org_id, tax_id) where tax_id is not null;\n\n-- -----------------------------------------------------------------------------\n-- Vehículos\n-- -----------------------------------------------------------------------------\n-- \"Range Rover\" + \"Range Rover Sport\" → \"Range Rover Sport\"; \"Ford\" + \"Ranger\" → \"Ford Ranger\".\ncreate or replace function app.vehicle_name(p_brand text, p_model text)\nreturns text language sql immutable parallel safe as $$\n  select case when lower(p_model) like lower(p_brand) || '%' then p_model else p_brand || ' ' || p_model end\n$$;\ncreate table public.vehicles (\n  id                 uuid primary key default gen_random_uuid(),\n  org_id             uuid not null references public.organizations(id) on delete cascade,\n  branch_id          uuid,\n  stock_code         text not null,\n  brand_id           uuid not null,\n  category_id        uuid,\n  model              text not null,\n  version            text,\n  year_manufacture   smallint not null check (year_manufacture between 1950 and 2100),\n  year_model         smallint not null check (year_model between 1950 and 2101),\n  vin                text,\n  engine_number      text,\n  plate              text,\n  mileage_km         integer not null default 0 check (mileage_km >= 0),\n  fuel               text not null check (fuel in ('nafta','diesel','hibrido','hibrido_enchufable','electrico','gnc','otro')),\n  transmission       text not null check (transmission in ('manual','automatica','cvt','dct','otra')),\n  color              text,\n  condition          text not null check (condition in ('nuevo','usado')),\n  origin             text not null default 'compra_local'\n                     check (origin in ('importacion','compra_local','trade_in','consignacion')),\n  location           text,\n  acquisition_date   date,\n  supplier_id        uuid,\n  responsible_id     uuid references public.user_profiles(id),\n  -- Comercial\n  price_currency     char(3) not null default 'PYG' references public.currencies(code),\n  list_price         numeric(18,2) check (list_price is null or list_price >= 0),\n  min_price          numeric(18,2) check (min_price is null or min_price >= 0),\n  -- Estados independientes\n  physical_status    text not null default 'recibido'\n                     check (physical_status in ('en_transito','recibido','en_preparacion','en_reparacion','listo')),\n  commercial_status  text not null default 'disponible'\n                     check (commercial_status in ('disponible','reservado','vendido_pendiente_entrega','entregado','retirado')),\n  contract_status    text not null default 'sin_contrato'\n                     check (contract_status in ('sin_contrato','reservado','contrato_firmado','cancelado')),\n  prep_status        text not null default 'pendiente'\n                     check (prep_status in ('pendiente','en_proceso','completa','no_aplica')),\n  doc_status         text not null default 'incompleta'\n                     check (doc_status in ('incompleta','en_tramite','completa')),\n  description        text,\n  is_published       boolean not null default true,\n  created_by         uuid references public.user_profiles(id),\n  created_at         timestamptz not null default now(),\n  updated_at         timestamptz not null default now(),\n  row_version        integer not null default 1,\n  unique (org_id, stock_code),\n  unique (id, org_id),\n  foreign key (branch_id, org_id)   references public.branches(id, org_id),\n  foreign key (brand_id, org_id)    references public.brands(id, org_id),\n  foreign key (category_id, org_id) references public.vehicle_categories(id, org_id),\n  foreign key (supplier_id, org_id) references public.suppliers(id, org_id),\n  check (app.money_ok(list_price, price_currency)),\n  check (app.money_ok(min_price, price_currency)),\n  check (min_price is null or list_price is null or min_price <= list_price),\n  check (year_model between year_manufacture and year_manufacture + 1)\n);\ncreate unique index vehicles_vin_uq on public.vehicles(org_id, upper(vin)) where vin is not null and vin <> '';\ncreate index vehicles_status_idx on public.vehicles(org_id, commercial_status);\ncreate index vehicles_brand_idx on public.vehicles(org_id, brand_id);\n\ncomment on column public.vehicles.commercial_status is\n  'Disponibilidad comercial. Sólo la modifican las funciones transaccionales de reservas y ventas, salvo \"retirado\".';\ncomment on column public.vehicles.contract_status is\n  'Situación contractual derivada de reservas y contratos. No se edita manualmente.';\n\ncreate trigger vehicles_touch before update on public.vehicles\n  for each row execute function app.touch_updated_at();\n\n-- Las transiciones de disponibilidad y situación contractual son exclusivas\n-- de las funciones transaccionales (SECURITY DEFINER; ver app.is_trusted).\ncreate or replace function app.vehicles_guard()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if not app.is_trusted() then\n    if new.contract_status is distinct from old.contract_status then\n      raise exception 'La situación contractual sólo cambia mediante reservas y contratos' using errcode = '42501';\n    end if;\n    if new.commercial_status is distinct from old.commercial_status\n       and not (old.commercial_status = 'disponible' and new.commercial_status = 'retirado')\n       and not (old.commercial_status = 'retirado' and new.commercial_status = 'disponible') then\n      raise exception 'La disponibilidad comercial sólo cambia mediante reservas, ventas y entregas (salvo retirar/reincorporar)'\n        using errcode = '42501';\n    end if;\n    if new.list_price is distinct from old.list_price or new.min_price is distinct from old.min_price\n       or new.price_currency is distinct from old.price_currency then\n      if not app.has_perm(new.org_id, 'inventory.pricing.edit') then\n        raise exception 'No tiene permiso para modificar precios' using errcode = '42501';\n      end if;\n    end if;\n  end if;\n  if tg_op = 'UPDATE' then\n    new.row_version := old.row_version + 1;\n  end if;\n  return new;\nend $$;\n\ncreate trigger vehicles_guard before update on public.vehicles\n  for each row execute function app.vehicles_guard();\n\n-- Historial de estados (todas las dimensiones)\ncreate table public.vehicle_status_events (\n  id           bigint generated always as identity primary key,\n  org_id       uuid not null,\n  vehicle_id   uuid not null,\n  dimension    text not null check (dimension in ('physical','commercial','contract','prep','doc')),\n  from_status  text,\n  to_status    text not null,\n  note         text,\n  actor_id     uuid,\n  occurred_at  timestamptz not null default now(),\n  foreign key (vehicle_id, org_id) references public.vehicles(id, org_id) on delete cascade\n);\ncreate index vehicle_status_events_vehicle_idx on public.vehicle_status_events(vehicle_id, occurred_at desc);\n\ncreate trigger vehicle_status_events_immutable before update or delete on public.vehicle_status_events\n  for each row execute function app.forbid_mutation();\n\ncreate or replace function app.vehicles_status_log()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_note text := nullif(current_setting('app.status_note', true), '');\nbegin\n  if tg_op = 'INSERT' then\n    insert into public.vehicle_status_events (org_id, vehicle_id, dimension, from_status, to_status, note, actor_id) values\n      (new.org_id, new.id, 'physical',   null, new.physical_status,   'Alta de unidad', auth.uid()),\n      (new.org_id, new.id, 'commercial', null, new.commercial_status, 'Alta de unidad', auth.uid());\n    return new;\n  end if;\n  if new.physical_status is distinct from old.physical_status then\n    insert into public.vehicle_status_events (org_id, vehicle_id, dimension, from_status, to_status, note, actor_id)\n    values (new.org_id, new.id, 'physical', old.physical_status, new.physical_status, v_note, auth.uid());\n  end if;\n  if new.commercial_status is distinct from old.commercial_status then\n    insert into public.vehicle_status_events (org_id, vehicle_id, dimension, from_status, to_status, note, actor_id)\n    values (new.org_id, new.id, 'commercial', old.commercial_status, new.commercial_status, v_note, auth.uid());\n  end if;\n  if new.contract_status is distinct from old.contract_status then\n    insert into public.vehicle_status_events (org_id, vehicle_id, dimension, from_status, to_status, note, actor_id)\n    values (new.org_id, new.id, 'contract', old.contract_status, new.contract_status, v_note, auth.uid());\n  end if;\n  if new.prep_status is distinct from old.prep_status then\n    insert into public.vehicle_status_events (org_id, vehicle_id, dimension, from_status, to_status, note, actor_id)\n    values (new.org_id, new.id, 'prep', old.prep_status, new.prep_status, v_note, auth.uid());\n  end if;\n  if new.doc_status is distinct from old.doc_status then\n    insert into public.vehicle_status_events (org_id, vehicle_id, dimension, from_status, to_status, note, actor_id)\n    values (new.org_id, new.id, 'doc', old.doc_status, new.doc_status, v_note, auth.uid());\n  end if;\n  return new;\nend $$;\n\ncreate trigger vehicles_status_log after insert or update on public.vehicles\n  for each row execute function app.vehicles_status_log();\n\ncreate trigger vehicles_audit after insert or update or delete on public.vehicles\n  for each row execute function app.audit_row();\n\n-- -----------------------------------------------------------------------------\n-- Costes atribuibles por unidad\n-- -----------------------------------------------------------------------------\ncreate table public.vehicle_costs (\n  id                  uuid primary key default gen_random_uuid(),\n  org_id              uuid not null,\n  vehicle_id          uuid not null,\n  kind                text not null check (kind in ('adquisicion','transporte','importacion','reparacion',\n                                                     'preparacion','documentacion','comision','otro')),\n  description         text not null,\n  amount              numeric(18,2) not null check (amount >= 0),\n  currency            char(3) not null references public.currencies(code),\n  fx_rate_to_base     numeric(18,6) not null default 1 check (fx_rate_to_base > 0),\n  amount_base         numeric(18,2) not null,\n  is_estimate         boolean not null default false,\n  incurred_on         date not null,\n  supplier_id         uuid,\n  supplier_invoice_id uuid,\n  created_by          uuid references public.user_profiles(id),\n  created_at          timestamptz not null default now(),\n  updated_at          timestamptz not null default now(),\n  unique (id, org_id),\n  foreign key (vehicle_id, org_id)  references public.vehicles(id, org_id) on delete cascade,\n  foreign key (supplier_id, org_id) references public.suppliers(id, org_id),\n  check (app.money_ok(amount, currency))\n);\ncreate index vehicle_costs_vehicle_idx on public.vehicle_costs(vehicle_id);\ncomment on column public.vehicle_costs.is_estimate is\n  'true = coste presupuestado aún no facturado (gasto pendiente). Se distingue en márgenes y alertas.';\ncomment on column public.vehicle_costs.amount_base is\n  'Importe convertido a la moneda base de la organización con fx_rate_to_base.';\n\ncreate or replace function app.vehicle_costs_compute()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_base char(3);\nbegin\n  select base_currency into v_base from public.organizations where id = new.org_id;\n  if new.currency = v_base then\n    new.fx_rate_to_base := 1;\n  end if;\n  new.amount_base := app.round_money(new.amount * new.fx_rate_to_base, v_base);\n  if tg_op = 'UPDATE' then\n    new.updated_at := now();\n    if not app.is_trusted()\n       and not app.has_perm(new.org_id, 'inventory.costs.edit_history') then\n      raise exception 'Corregir un coste registrado requiere autorización (inventory.costs.edit_history)'\n        using errcode = '42501';\n    end if;\n  end if;\n  return new;\nend $$;\n\ncreate trigger vehicle_costs_compute before insert or update on public.vehicle_costs\n  for each row execute function app.vehicle_costs_compute();\ncreate trigger vehicle_costs_audit after insert or update or delete on public.vehicle_costs\n  for each row execute function app.audit_row();\n\n-- -----------------------------------------------------------------------------\n-- Documentos (Supabase Storage privado) y fotografías\n-- -----------------------------------------------------------------------------\ncreate table public.document_types (\n  id          uuid primary key default gen_random_uuid(),\n  org_id      uuid not null references public.organizations(id) on delete cascade,\n  entity_type text not null check (entity_type in ('vehicle','customer','deal','contract','payment',\n                                                    'supplier_invoice','trade_in','expense','cash_movement')),\n  name        text not null,\n  is_required boolean not null default false,\n  applies_to_condition text check (applies_to_condition in ('nuevo','usado')),\n  unique (org_id, entity_type, name)\n);\ncomment on table public.document_types is\n  'Tipos de documento configurables por entidad. is_required alimenta la alerta de documentación incompleta.';\n\ncreate table public.documents (\n  id            uuid primary key default gen_random_uuid(),\n  org_id        uuid not null references public.organizations(id) on delete cascade,\n  entity_type   text not null check (entity_type in ('vehicle','customer','deal','contract','payment',\n                                                      'supplier_invoice','trade_in','expense','cash_movement')),\n  entity_id     uuid not null,\n  document_type_id uuid references public.document_types(id),\n  title         text not null,\n  storage_bucket text not null default 'documents',\n  storage_path  text not null,\n  mime_type     text not null,\n  size_bytes    bigint not null check (size_bytes >= 0 and size_bytes <= 26214400),\n  is_restricted boolean not null default false,\n  uploaded_by   uuid references public.user_profiles(id),\n  uploaded_at   timestamptz not null default now(),\n  unique (storage_bucket, storage_path)\n);\ncreate index documents_entity_idx on public.documents(entity_type, entity_id);\n\ncreate trigger documents_audit after insert or update or delete on public.documents\n  for each row execute function app.audit_row();\n\n-- Documentos de vehículos con su estado de verificación\ncreate table public.vehicle_documents (\n  id               uuid primary key default gen_random_uuid(),\n  org_id           uuid not null,\n  vehicle_id       uuid not null,\n  document_type_id uuid not null references public.document_types(id),\n  document_id      uuid references public.documents(id) on delete set null,\n  status           text not null default 'pendiente' check (status in ('pendiente','recibido','verificado','observado')),\n  notes            text,\n  updated_by       uuid references public.user_profiles(id),\n  updated_at       timestamptz not null default now(),\n  foreign key (vehicle_id, org_id) references public.vehicles(id, org_id) on delete cascade,\n  unique (vehicle_id, document_type_id)\n);\n\ncreate table public.vehicle_photos (\n  id            uuid primary key default gen_random_uuid(),\n  org_id        uuid not null,\n  vehicle_id    uuid not null,\n  storage_path  text not null,\n  sort_order    smallint not null default 0,\n  is_cover      boolean not null default false,\n  uploaded_by   uuid references public.user_profiles(id),\n  uploaded_at   timestamptz not null default now(),\n  foreign key (vehicle_id, org_id) references public.vehicles(id, org_id) on delete cascade\n);\ncreate unique index vehicle_photos_cover_uq on public.vehicle_photos(vehicle_id) where is_cover;\n"},{"name":"20261022000300_crm_sales.sql","sql":"-- =============================================================================\n-- Da Silva OS — Clientes, CRM, tasaciones, aprobaciones, ventas y reservas\n-- =============================================================================\n\ncreate or replace function app.normalize_doc(p text)\nreturns text language sql immutable parallel safe as $$\n  select nullif(upper(regexp_replace(coalesce(p, ''), '[^0-9A-Za-z]', '', 'g')), '')\n$$;\n\n-- Teléfonos paraguayos: se guardan sólo dígitos; 09xx… y 5959xx… se unifican.\ncreate or replace function app.normalize_phone(p text)\nreturns text language sql immutable parallel safe as $$\n  select nullif(\n    regexp_replace(\n      regexp_replace(regexp_replace(coalesce(p, ''), '[^0-9]', '', 'g'), '^00', ''),\n      '^0(9[0-9]{8})$', '595\\1'),\n  '')\n$$;\n\n-- -----------------------------------------------------------------------------\n-- Clientes\n-- -----------------------------------------------------------------------------\ncreate table public.customers (\n  id                 uuid primary key default gen_random_uuid(),\n  org_id             uuid not null references public.organizations(id) on delete cascade,\n  kind               text not null check (kind in ('persona','empresa')),\n  full_name          text not null,\n  doc_type           text not null check (doc_type in ('ci','ruc','pasaporte','otro')),\n  doc_number         text not null,\n  doc_normalized     text generated always as (app.normalize_doc(doc_number)) stored,\n  phone              text,\n  phone_normalized   text generated always as (app.normalize_phone(phone)) stored,\n  email              text,\n  email_normalized   text generated always as (nullif(lower(trim(email)), '')) stored,\n  address            text,\n  city               text,\n  customer_type      text not null default 'particular'\n                     check (customer_type in ('particular','empresa','flota','revendedor','otro')),\n  source             text,\n  assigned_seller_id uuid references public.user_profiles(id),\n  collector_id       uuid references public.user_profiles(id),\n  notes              text,\n  created_by         uuid references public.user_profiles(id),\n  created_at         timestamptz not null default now(),\n  updated_at         timestamptz not null default now(),\n  unique (id, org_id),\n  check (email is null or email ~* '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$')\n);\ncreate unique index customers_doc_uq on public.customers(org_id, doc_type, doc_normalized);\ncreate index customers_phone_idx on public.customers(org_id, phone_normalized);\ncreate index customers_email_idx on public.customers(org_id, email_normalized);\ncreate index customers_seller_idx on public.customers(org_id, assigned_seller_id);\ncreate index customers_name_idx on public.customers(org_id, lower(full_name));\n\ncreate trigger customers_touch before update on public.customers\n  for each row execute function app.touch_updated_at();\ncreate trigger customers_audit after insert or update or delete on public.customers\n  for each row execute function app.audit_row();\n\n-- ¿Puede el usuario ver al cliente? (propio o permiso global)\ncreate or replace function app.can_see_customer(p_org uuid, p_seller uuid, p_created_by uuid)\nreturns boolean\nlanguage sql stable\nas $$\n  select app.has_perm(p_org, 'customers.view_all')\n      or (app.has_perm(p_org, 'customers.view')\n          and (p_seller = auth.uid() or p_created_by = auth.uid() or p_seller is null))\n$$;\n\ncreate table public.customer_interactions (\n  id              uuid primary key default gen_random_uuid(),\n  org_id          uuid not null,\n  customer_id     uuid not null,\n  channel         text not null check (channel in ('llamada','whatsapp','visita','email','nota','otro')),\n  summary         text not null,\n  occurred_at     timestamptz not null default now(),\n  next_action     text,\n  next_action_at  date,\n  user_id         uuid not null references public.user_profiles(id),\n  created_at      timestamptz not null default now(),\n  foreign key (customer_id, org_id) references public.customers(id, org_id) on delete cascade\n);\ncreate index customer_interactions_customer_idx on public.customer_interactions(customer_id, occurred_at desc);\n\n-- Contactos aún no calificados como clientes.\ncreate table public.leads (\n  id              uuid primary key default gen_random_uuid(),\n  org_id          uuid not null references public.organizations(id) on delete cascade,\n  full_name       text not null,\n  phone           text,\n  email           text,\n  source          text,\n  interest        text,\n  assigned_to     uuid references public.user_profiles(id),\n  status          text not null default 'nuevo' check (status in ('nuevo','contactado','convertido','descartado')),\n  customer_id     uuid,\n  created_by      uuid references public.user_profiles(id),\n  created_at      timestamptz not null default now(),\n  foreign key (customer_id, org_id) references public.customers(id, org_id)\n);\n\ncreate table public.pipeline_stages (\n  id          uuid primary key default gen_random_uuid(),\n  org_id      uuid not null references public.organizations(id) on delete cascade,\n  key         text not null,\n  name        text not null,\n  sort_order  smallint not null,\n  is_won      boolean not null default false,\n  is_lost     boolean not null default false,\n  unique (org_id, key),\n  unique (id, org_id)\n);\n\ncreate table public.opportunities (\n  id              uuid primary key default gen_random_uuid(),\n  org_id          uuid not null,\n  customer_id     uuid not null,\n  vehicle_id      uuid,\n  stage_id        uuid not null,\n  seller_id       uuid references public.user_profiles(id),\n  title           text not null,\n  expected_value  numeric(18,2),\n  currency        char(3) not null default 'PYG' references public.currencies(code),\n  status          text not null default 'abierta' check (status in ('abierta','ganada','perdida')),\n  lost_reason     text,\n  next_action     text,\n  next_action_at  date,\n  created_by      uuid references public.user_profiles(id),\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  unique (id, org_id),\n  foreign key (customer_id, org_id) references public.customers(id, org_id) on delete cascade,\n  foreign key (vehicle_id, org_id)  references public.vehicles(id, org_id),\n  foreign key (stage_id, org_id)    references public.pipeline_stages(id, org_id),\n  check (app.money_ok(expected_value, currency))\n);\ncreate index opportunities_stage_idx on public.opportunities(org_id, stage_id) where status = 'abierta';\n\ncreate trigger opportunities_touch before update on public.opportunities\n  for each row execute function app.touch_updated_at();\n\ncreate table public.opportunity_stage_events (\n  id              bigint generated always as identity primary key,\n  org_id          uuid not null,\n  opportunity_id  uuid not null,\n  from_stage_id   uuid,\n  to_stage_id     uuid not null,\n  actor_id        uuid,\n  note            text,\n  occurred_at     timestamptz not null default now(),\n  foreign key (opportunity_id, org_id) references public.opportunities(id, org_id) on delete cascade\n);\n\ncreate or replace function app.opportunity_stage_log()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  if tg_op = 'INSERT' or new.stage_id is distinct from old.stage_id then\n    insert into public.opportunity_stage_events (org_id, opportunity_id, from_stage_id, to_stage_id, actor_id)\n    values (new.org_id, new.id, case when tg_op = 'UPDATE' then old.stage_id end, new.stage_id, auth.uid());\n  end if;\n  return new;\nend $$;\n\ncreate trigger opportunities_stage_log after insert or update on public.opportunities\n  for each row execute function app.opportunity_stage_log();\n\n-- Etapas por defecto del embudo comercial\ncreate or replace function app.init_pipeline_defaults()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  insert into public.pipeline_stages (org_id, key, name, sort_order, is_won, is_lost) values\n    (new.id, 'nuevo',       'Nuevo contacto',      1, false, false),\n    (new.id, 'contactado',  'Contactado',          2, false, false),\n    (new.id, 'interesado',  'Interesado',          3, false, false),\n    (new.id, 'propuesta',   'Propuesta enviada',   4, false, false),\n    (new.id, 'negociacion', 'Negociación',         5, false, false),\n    (new.id, 'reserva',     'Reserva',             6, false, false),\n    (new.id, 'venta',       'Venta formalizada',   7, true,  false),\n    (new.id, 'entrega',     'Entrega',             8, true,  false),\n    (new.id, 'posventa',    'Seguimiento posventa',9, true,  false),\n    (new.id, 'perdida',     'Perdida',            10, false, true);\n  return new;\nend $$;\n\ncreate trigger organizations_pipeline_defaults after insert on public.organizations\n  for each row execute function app.init_pipeline_defaults();\n\n-- -----------------------------------------------------------------------------\n-- Aprobaciones\n-- -----------------------------------------------------------------------------\ncreate table public.approvals (\n  id             uuid primary key default gen_random_uuid(),\n  org_id         uuid not null references public.organizations(id) on delete cascade,\n  kind           text not null check (kind in ('descuento','precio_bajo_minimo','recargo','nota_credito','ajuste',\n                                               'refinanciacion','tasacion','factura_proveedor','gasto')),\n  entity_type    text not null,\n  entity_id      uuid not null,\n  title          text not null,\n  reason         text,\n  amount         numeric(18,2),\n  currency       char(3) references public.currencies(code),\n  payload        jsonb not null default '{}'::jsonb,\n  status         text not null default 'pendiente' check (status in ('pendiente','aprobada','rechazada','anulada')),\n  requested_by   uuid references public.user_profiles(id),\n  requested_at   timestamptz not null default now(),\n  decided_by     uuid references public.user_profiles(id),\n  decided_at     timestamptz,\n  decision_note  text,\n  check ((status = 'pendiente') = (decided_at is null))\n);\ncreate unique index approvals_pending_uq on public.approvals(entity_id, kind) where status = 'pendiente';\ncreate index approvals_org_pending_idx on public.approvals(org_id, requested_at) where status = 'pendiente';\n\ncreate trigger approvals_audit after insert or update on public.approvals\n  for each row execute function app.audit_row();\n\n-- Permiso necesario para decidir cada tipo de aprobación.\ncreate or replace function app.approval_permission(p_kind text)\nreturns text language sql immutable as $$\n  select case p_kind\n    when 'descuento'          then 'deals.approve'\n    when 'precio_bajo_minimo' then 'deals.approve'\n    when 'recargo'            then 'contracts.approve'\n    when 'nota_credito'       then 'contracts.approve'\n    when 'ajuste'             then 'contracts.approve'\n    when 'refinanciacion'     then 'contracts.approve'\n    when 'tasacion'           then 'tradein.approve'\n    when 'factura_proveedor'  then 'payables.approve'\n    when 'gasto'              then 'expenses.approve'\n  end\n$$;\n\n-- -----------------------------------------------------------------------------\n-- Tasaciones (trade-in)\n-- -----------------------------------------------------------------------------\ncreate table public.trade_in_appraisals (\n  id                      uuid primary key default gen_random_uuid(),\n  org_id                  uuid not null references public.organizations(id) on delete cascade,\n  number                  text not null,\n  customer_id             uuid not null,\n  brand_name              text not null,\n  model                   text not null,\n  version                 text,\n  year_model              smallint not null check (year_model between 1950 and 2101),\n  mileage_km              integer not null check (mileage_km >= 0),\n  vin                     text,\n  plate                   text,\n  color                   text,\n  fuel                    text check (fuel in ('nafta','diesel','hibrido','hibrido_enchufable','electrico','gnc','otro')),\n  transmission            text check (transmission in ('manual','automatica','cvt','dct','otra')),\n  doc_status              text not null default 'sin_revisar'\n                          check (doc_status in ('sin_revisar','completa','observada','con_gravamen')),\n  doc_notes               text,\n  currency                char(3) not null default 'PYG' references public.currencies(code),\n  market_value_estimate   numeric(18,2),\n  market_value_source     text,\n  market_value_date       date,\n  offered_value           numeric(18,2),\n  accepted_value          numeric(18,2),\n  expected_resale_price   numeric(18,2),\n  estimated_repair_costs  numeric(18,2) not null default 0,\n  appraiser_notes         text,\n  status                  text not null default 'borrador'\n                          check (status in ('borrador','en_revision','aprobada','rechazada','aceptada_cliente','adquirida','anulada')),\n  appraiser_id            uuid references public.user_profiles(id),\n  approval_id             uuid references public.approvals(id),\n  vehicle_id              uuid,\n  created_by              uuid references public.user_profiles(id),\n  created_at              timestamptz not null default now(),\n  updated_at              timestamptz not null default now(),\n  unique (org_id, number),\n  unique (id, org_id),\n  foreign key (customer_id, org_id) references public.customers(id, org_id),\n  foreign key (vehicle_id, org_id)  references public.vehicles(id, org_id),\n  check (app.money_ok(market_value_estimate, currency) and app.money_ok(offered_value, currency)\n         and app.money_ok(accepted_value, currency) and app.money_ok(expected_resale_price, currency)\n         and app.money_ok(estimated_repair_costs, currency)),\n  check (market_value_estimate is null or (market_value_source is not null and market_value_date is not null))\n);\ncomment on column public.trade_in_appraisals.market_value_estimate is\n  'Valor de mercado ESTIMADO por el tasador. Requiere fuente y fecha. No es una tasación profesional verificada.';\n\ncreate trigger trade_in_touch before update on public.trade_in_appraisals\n  for each row execute function app.touch_updated_at();\ncreate trigger trade_in_audit after insert or update on public.trade_in_appraisals\n  for each row execute function app.audit_row();\n\ncreate table public.appraisal_inspections (\n  id              uuid primary key default gen_random_uuid(),\n  org_id          uuid not null,\n  appraisal_id    uuid not null,\n  area            text not null check (area in ('mecanica','carroceria','neumaticos','interior','electronica','documentacion','otro')),\n  rating          text not null check (rating in ('bueno','regular','malo','no_evaluado')),\n  notes           text,\n  repair_estimate numeric(18,2) not null default 0 check (repair_estimate >= 0),\n  inspected_by    uuid references public.user_profiles(id),\n  inspected_at    timestamptz not null default now(),\n  foreign key (appraisal_id, org_id) references public.trade_in_appraisals(id, org_id) on delete cascade,\n  unique (appraisal_id, area)\n);\n\n-- -----------------------------------------------------------------------------\n-- Operaciones de venta\n-- -----------------------------------------------------------------------------\ncreate table public.deals (\n  id                    uuid primary key default gen_random_uuid(),\n  org_id                uuid not null references public.organizations(id) on delete cascade,\n  number                text not null,\n  customer_id           uuid not null,\n  vehicle_id            uuid not null,\n  seller_id             uuid not null references public.user_profiles(id),\n  opportunity_id        uuid,\n  currency              char(3) not null references public.currencies(code),\n  list_price            numeric(18,2) not null check (list_price >= 0),\n  discount_amount       numeric(18,2) not null default 0 check (discount_amount >= 0),\n  sale_price            numeric(18,2) generated always as (list_price - discount_amount) stored,\n  trade_in_appraisal_id uuid,\n  trade_in_value        numeric(18,2) not null default 0 check (trade_in_value >= 0),\n  down_payment          numeric(18,2) not null default 0 check (down_payment >= 0),\n  payment_type          text not null check (payment_type in ('contado','financiado')),\n  -- Propuesta: {method, ratePercent, rateConvention, termMonths, firstDueDate, balloons[]}. Null en contado.\n  -- Al formalizar, el motor genera el cronograma definitivo con estas condiciones y la fecha de firma.\n  financing_terms       jsonb,\n  status                text not null default 'borrador'\n                        check (status in ('borrador','pendiente_aprobacion','aprobada','formalizada','entregada','anulada')),\n  requires_approval     boolean not null default false,\n  approval_reason       text,\n  fx_rate_to_base       numeric(18,6),\n  delivery_scheduled_on date,\n  formalized_at         timestamptz,\n  delivered_at          timestamptz,\n  cancelled_at          timestamptz,\n  cancel_reason         text,\n  notes                 text,\n  created_by            uuid references public.user_profiles(id),\n  created_at            timestamptz not null default now(),\n  updated_at            timestamptz not null default now(),\n  unique (org_id, number),\n  unique (id, org_id),\n  foreign key (customer_id, org_id)           references public.customers(id, org_id),\n  foreign key (vehicle_id, org_id)            references public.vehicles(id, org_id),\n  foreign key (opportunity_id, org_id)        references public.opportunities(id, org_id),\n  foreign key (trade_in_appraisal_id, org_id) references public.trade_in_appraisals(id, org_id),\n  check (discount_amount <= list_price),\n  check (trade_in_value + down_payment <= list_price - discount_amount),\n  check (app.money_ok(list_price, currency) and app.money_ok(discount_amount, currency)\n         and app.money_ok(trade_in_value, currency) and app.money_ok(down_payment, currency)),\n  check (payment_type = 'financiado' or trade_in_value + down_payment = list_price - discount_amount\n         or status in ('borrador','pendiente_aprobacion','aprobada','anulada')),\n  check (payment_type = 'contado' or status in ('borrador','anulada') or financing_terms is not null)\n);\n-- Una unidad sólo puede tener una venta formalizada o entregada.\ncreate unique index deals_vehicle_sold_uq on public.deals(vehicle_id) where status in ('formalizada','entregada');\ncreate index deals_status_idx on public.deals(org_id, status);\ncreate index deals_seller_idx on public.deals(org_id, seller_id);\n\ncomment on column public.deals.sale_price is 'Precio de venta = precio de lista − descuento.';\ncomment on column public.deals.trade_in_value is 'Valor de aceptación del vehículo usado aplicado como parte de pago.';\n\ncreate or replace function app.can_see_deal(p_org uuid, p_seller uuid)\nreturns boolean language sql stable as $$\n  select app.has_perm(p_org, 'deals.view_all')\n      or (app.has_perm(p_org, 'deals.view') and p_seller = auth.uid())\n$$;\n\ncreate trigger deals_touch before update on public.deals\n  for each row execute function app.touch_updated_at();\ncreate trigger deals_audit after insert or update on public.deals\n  for each row execute function app.audit_row();\n\n-- Historial de precio y condiciones (cada cambio relevante de la operación)\ncreate table public.deal_events (\n  id           bigint generated always as identity primary key,\n  org_id       uuid not null,\n  deal_id      uuid not null,\n  event        text not null,\n  details      jsonb not null default '{}'::jsonb,\n  actor_id     uuid,\n  occurred_at  timestamptz not null default now(),\n  foreign key (deal_id, org_id) references public.deals(id, org_id) on delete cascade\n);\ncreate index deal_events_deal_idx on public.deal_events(deal_id, occurred_at);\ncreate trigger deal_events_immutable before update or delete on public.deal_events\n  for each row execute function app.forbid_mutation();\n\ncreate or replace function app.deal_event_log()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  if tg_op = 'INSERT' then\n    insert into public.deal_events (org_id, deal_id, event, details, actor_id)\n    values (new.org_id, new.id, 'creada', jsonb_build_object(\n      'list_price', new.list_price, 'discount_amount', new.discount_amount, 'trade_in_value', new.trade_in_value,\n      'down_payment', new.down_payment, 'payment_type', new.payment_type, 'currency', new.currency), auth.uid());\n    return new;\n  end if;\n  if (new.list_price, new.discount_amount, new.trade_in_value, new.down_payment, new.payment_type, new.currency)\n     is distinct from (old.list_price, old.discount_amount, old.trade_in_value, old.down_payment, old.payment_type, old.currency) then\n    insert into public.deal_events (org_id, deal_id, event, details, actor_id)\n    values (new.org_id, new.id, 'condiciones_modificadas', jsonb_build_object(\n      'antes', jsonb_build_object('list_price', old.list_price, 'discount_amount', old.discount_amount,\n                                  'trade_in_value', old.trade_in_value, 'down_payment', old.down_payment,\n                                  'payment_type', old.payment_type, 'currency', old.currency),\n      'despues', jsonb_build_object('list_price', new.list_price, 'discount_amount', new.discount_amount,\n                                    'trade_in_value', new.trade_in_value, 'down_payment', new.down_payment,\n                                    'payment_type', new.payment_type, 'currency', new.currency)), auth.uid());\n  end if;\n  if new.financing_terms is distinct from old.financing_terms then\n    insert into public.deal_events (org_id, deal_id, event, details, actor_id)\n    values (new.org_id, new.id, 'financiacion_modificada',\n            jsonb_build_object('antes', old.financing_terms, 'despues', new.financing_terms), auth.uid());\n  end if;\n  if new.status is distinct from old.status then\n    insert into public.deal_events (org_id, deal_id, event, details, actor_id)\n    values (new.org_id, new.id, 'estado', jsonb_build_object('de', old.status, 'a', new.status), auth.uid());\n  end if;\n  return new;\nend $$;\n\ncreate trigger deals_event_log after insert or update on public.deals\n  for each row execute function app.deal_event_log();\n\n-- Bloquea cambios de condiciones fuera de borrador y transiciones de estado\n-- que no provengan de las funciones transaccionales.\ncreate or replace function app.deals_guard()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if app.is_trusted() then\n    return new;\n  end if;\n  if new.status is distinct from old.status then\n    raise exception 'El estado de la operación sólo cambia mediante las acciones de venta' using errcode = '42501';\n  end if;\n  if old.status not in ('borrador') and\n     (new.list_price, new.discount_amount, new.trade_in_value, new.down_payment, new.payment_type, new.currency,\n      new.vehicle_id, new.customer_id, new.trade_in_appraisal_id, new.financing_terms)\n     is distinct from\n     (old.list_price, old.discount_amount, old.trade_in_value, old.down_payment, old.payment_type, old.currency,\n      old.vehicle_id, old.customer_id, old.trade_in_appraisal_id, old.financing_terms) then\n    raise exception 'Las condiciones sólo se modifican en borrador' using errcode = '42501';\n  end if;\n  return new;\nend $$;\n\ncreate trigger deals_guard before update on public.deals\n  for each row execute function app.deals_guard();\n\n-- -----------------------------------------------------------------------------\n-- Reservas\n-- -----------------------------------------------------------------------------\ncreate table public.reservations (\n  id            uuid primary key default gen_random_uuid(),\n  org_id        uuid not null references public.organizations(id) on delete cascade,\n  number        text not null,\n  vehicle_id    uuid not null,\n  customer_id   uuid not null,\n  deal_id       uuid,\n  deposit_amount numeric(18,2) not null default 0 check (deposit_amount >= 0),\n  currency      char(3) not null references public.currencies(code),\n  expires_at    timestamptz not null,\n  status        text not null default 'activa' check (status in ('activa','convertida','vencida','anulada')),\n  notes         text,\n  created_by    uuid references public.user_profiles(id),\n  created_at    timestamptz not null default now(),\n  closed_at     timestamptz,\n  close_reason  text,\n  unique (org_id, number),\n  unique (id, org_id),\n  foreign key (vehicle_id, org_id)  references public.vehicles(id, org_id),\n  foreign key (customer_id, org_id) references public.customers(id, org_id),\n  foreign key (deal_id, org_id)     references public.deals(id, org_id),\n  check (app.money_ok(deposit_amount, currency))\n);\n-- Una sola reserva activa por unidad (refuerza el bloqueo transaccional).\ncreate unique index reservations_active_vehicle_uq on public.reservations(vehicle_id) where status = 'activa';\n\ncreate trigger reservations_audit after insert or update on public.reservations\n  for each row execute function app.audit_row();\n\n-- -----------------------------------------------------------------------------\n-- Propuestas comerciales (cotizaciones). No crean contrato ni afectan inventario.\n-- -----------------------------------------------------------------------------\ncreate table public.proposals (\n  id            uuid primary key default gen_random_uuid(),\n  org_id        uuid not null references public.organizations(id) on delete cascade,\n  number        text not null,\n  customer_id   uuid not null,\n  vehicle_id    uuid not null,\n  deal_id       uuid,\n  currency      char(3) not null references public.currencies(code),\n  terms         jsonb not null,\n  valid_until   date not null,\n  created_by    uuid references public.user_profiles(id),\n  created_at    timestamptz not null default now(),\n  unique (org_id, number),\n  foreign key (customer_id, org_id) references public.customers(id, org_id),\n  foreign key (vehicle_id, org_id)  references public.vehicles(id, org_id),\n  foreign key (deal_id, org_id)     references public.deals(id, org_id)\n);\ncomment on table public.proposals is\n  'Instantánea inmutable de una cotización (precio, financiación y tabla de pagos). No equivale a aprobación crediticia.';\ncreate trigger proposals_immutable before update or delete on public.proposals\n  for each row execute function app.forbid_mutation();\n"},{"name":"20261022000400_finance.sql","sql":"-- =============================================================================\n-- Da Silva OS — Contratos, financiación, cobros, cobranzas, caja y proveedores\n-- =============================================================================\n\n-- -----------------------------------------------------------------------------\n-- Cuentas de caja / bancos (saldo REGISTRADO; sin integración bancaria)\n-- -----------------------------------------------------------------------------\ncreate table public.cash_accounts (\n  id               uuid primary key default gen_random_uuid(),\n  org_id           uuid not null references public.organizations(id) on delete cascade,\n  name             text not null,\n  kind             text not null check (kind in ('caja','banco','billetera')),\n  currency         char(3) not null references public.currencies(code),\n  bank_name        text,\n  account_ref      text,\n  is_active        boolean not null default true,\n  created_at       timestamptz not null default now(),\n  unique (org_id, name),\n  unique (id, org_id),\n  unique (id, currency)\n);\ncomment on table public.cash_accounts is\n  'Cuentas registradas por la empresa. Sus saldos son registros internos y requieren conciliación manual contra extractos.';\n\ncreate table public.reconciliations (\n  id                 uuid primary key default gen_random_uuid(),\n  org_id             uuid not null,\n  account_id         uuid not null,\n  period_end         date not null,\n  statement_balance  numeric(18,2) not null,\n  system_balance     numeric(18,2) not null,\n  difference         numeric(18,2) generated always as (statement_balance - system_balance) stored,\n  status             text not null default 'abierta' check (status in ('abierta','cerrada')),\n  notes              text,\n  created_by         uuid references public.user_profiles(id),\n  created_at         timestamptz not null default now(),\n  closed_by          uuid references public.user_profiles(id),\n  closed_at          timestamptz,\n  unique (id, org_id),\n  foreign key (account_id, org_id) references public.cash_accounts(id, org_id)\n);\n\ncreate table public.cash_movements (\n  id                   uuid primary key default gen_random_uuid(),\n  org_id               uuid not null,\n  account_id           uuid not null,\n  occurred_on          date not null,\n  direction            text not null check (direction in ('ingreso','egreso')),\n  kind                 text not null check (kind in ('cobro_cliente','pago_proveedor','gasto','transferencia',\n                                                     'ajuste','apertura','reversion','otro')),\n  amount               numeric(18,2) not null check (amount > 0),\n  currency             char(3) not null,\n  description          text not null,\n  reference            text,\n  counterparty         text,\n  customer_payment_id  uuid,\n  supplier_payment_id  uuid,\n  expense_id           uuid,\n  reverses_id          uuid unique references public.cash_movements(id),\n  status               text not null default 'registrado' check (status in ('registrado','conciliado')),\n  reconciliation_id    uuid references public.reconciliations(id),\n  created_by           uuid references public.user_profiles(id),\n  created_at           timestamptz not null default now(),\n  unique (id, org_id),\n  foreign key (account_id, org_id)   references public.cash_accounts(id, org_id),\n  foreign key (account_id, currency) references public.cash_accounts(id, currency),\n  check (app.money_ok(amount, currency))\n);\ncreate index cash_movements_account_idx on public.cash_movements(account_id, occurred_on);\ncreate index cash_movements_dup_idx on public.cash_movements(account_id, amount, occurred_on);\n\n-- Los movimientos no se borran ni se modifican; sólo pueden pasar a conciliado.\ncreate or replace function app.cash_movements_guard()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if tg_op = 'DELETE' then\n    raise exception 'Los movimientos de caja no se borran. Registre una reversión.' using errcode = '55000';\n  end if;\n  if (to_jsonb(new) - 'status' - 'reconciliation_id') <> (to_jsonb(old) - 'status' - 'reconciliation_id') then\n    raise exception 'Los movimientos de caja no se modifican. Registre una reversión.' using errcode = '55000';\n  end if;\n  if not app.is_trusted() then\n    raise exception 'La conciliación se registra mediante el proceso de conciliación' using errcode = '42501';\n  end if;\n  return new;\nend $$;\n\ncreate trigger cash_movements_guard before update or delete on public.cash_movements\n  for each row execute function app.cash_movements_guard();\ncreate trigger cash_movements_audit after insert or update on public.cash_movements\n  for each row execute function app.audit_row();\n\n-- -----------------------------------------------------------------------------\n-- Contratos y versiones\n-- -----------------------------------------------------------------------------\ncreate table public.contracts (\n  id               uuid primary key default gen_random_uuid(),\n  org_id           uuid not null references public.organizations(id) on delete cascade,\n  number           text not null,\n  deal_id          uuid not null unique,\n  customer_id      uuid not null,\n  vehicle_id       uuid not null,\n  currency         char(3) not null references public.currencies(code),\n  sale_price       numeric(18,2) not null check (sale_price >= 0),\n  trade_in_value   numeric(18,2) not null default 0,\n  down_payment     numeric(18,2) not null default 0,\n  financed_amount  numeric(18,2) not null default 0 check (financed_amount >= 0),\n  status           text not null default 'vigente' check (status in ('vigente','saldado','anulado')),\n  signed_on        date not null,\n  current_version  integer not null default 1,\n  collector_id     uuid references public.user_profiles(id),\n  created_by       uuid references public.user_profiles(id),\n  created_at       timestamptz not null default now(),\n  unique (org_id, number),\n  unique (id, org_id),\n  foreign key (deal_id, org_id)     references public.deals(id, org_id),\n  foreign key (customer_id, org_id) references public.customers(id, org_id),\n  foreign key (vehicle_id, org_id)  references public.vehicles(id, org_id),\n  check (sale_price = trade_in_value + down_payment + financed_amount),\n  check (app.money_ok(sale_price, currency) and app.money_ok(financed_amount, currency))\n);\ncreate index contracts_customer_idx on public.contracts(customer_id);\ncreate index contracts_collector_idx on public.contracts(org_id, collector_id);\n\ncreate trigger contracts_audit after insert or update on public.contracts\n  for each row execute function app.audit_row();\n\ncreate table public.financing_plans (\n  id               uuid primary key default gen_random_uuid(),\n  org_id           uuid not null,\n  contract_id      uuid not null,\n  version_no       integer not null,\n  method           text not null check (method in ('frances','aleman','sin_financiacion')),\n  principal        numeric(18,2) not null check (principal >= 0),\n  rate_input       numeric(12,6) not null default 0 check (rate_input >= 0),\n  rate_convention  text not null check (rate_convention in ('nominal_annual','effective_annual','monthly')),\n  monthly_rate     numeric(20,12) not null check (monthly_rate >= 0),\n  term_months      integer not null check (term_months >= 0 and term_months <= 120),\n  first_due_date   date,\n  balloons         jsonb not null default '[]'::jsonb,\n  total_interest   numeric(18,2) not null default 0,\n  total_payable    numeric(18,2) not null default 0,\n  created_by       uuid references public.user_profiles(id),\n  created_at       timestamptz not null default now(),\n  unique (id, org_id),\n  unique (contract_id, version_no),\n  foreign key (contract_id, org_id) references public.contracts(id, org_id)\n);\ncomment on column public.financing_plans.rate_input is 'Tasa ingresada en porcentaje (p. ej. 18 = 18%), interpretada según rate_convention.';\ncomment on column public.financing_plans.monthly_rate is 'Tasa mensual efectiva derivada (fracción, p. ej. 0.015).';\n\ncreate table public.contract_versions (\n  id               uuid primary key default gen_random_uuid(),\n  org_id           uuid not null,\n  contract_id      uuid not null,\n  version_no       integer not null,\n  reason           text not null,\n  terms            jsonb not null,\n  financing_plan_id uuid references public.financing_plans(id),\n  approval_id      uuid references public.approvals(id),\n  created_by       uuid references public.user_profiles(id),\n  created_at       timestamptz not null default now(),\n  unique (contract_id, version_no),\n  foreign key (contract_id, org_id) references public.contracts(id, org_id)\n);\ncreate trigger contract_versions_immutable before update or delete on public.contract_versions\n  for each row execute function app.forbid_mutation();\n\ncreate table public.installments (\n  id                uuid primary key default gen_random_uuid(),\n  org_id            uuid not null,\n  contract_id       uuid not null,\n  plan_id           uuid,\n  seq               integer not null check (seq >= 0),\n  kind              text not null check (kind in ('entrega_usado','entrega_inicial','cuota','refuerzo','recargo')),\n  description       text,\n  due_date          date not null,\n  currency          char(3) not null,\n  principal         numeric(18,2) not null default 0 check (principal >= 0),\n  interest          numeric(18,2) not null default 0 check (interest >= 0),\n  fee               numeric(18,2) not null default 0 check (fee >= 0),\n  amount            numeric(18,2) generated always as (principal + interest + fee) stored,\n  amount_cancelled  numeric(18,2) not null default 0 check (amount_cancelled >= 0),\n  status            text not null default 'vigente' check (status in ('vigente','reemplazada')),\n  approval_id       uuid references public.approvals(id),\n  created_at        timestamptz not null default now(),\n  unique (id, org_id),\n  unique (contract_id, seq),\n  foreign key (contract_id, org_id) references public.contracts(id, org_id),\n  foreign key (plan_id, org_id)     references public.financing_plans(id, org_id),\n  check (app.money_ok(principal, currency) and app.money_ok(interest, currency) and app.money_ok(fee, currency)),\n  check (amount_cancelled <= principal + interest + fee),\n  check (principal + interest + fee > 0)\n);\ncreate index installments_due_idx on public.installments(org_id, due_date) where status = 'vigente';\ncreate index installments_contract_idx on public.installments(contract_id, seq);\n\n-- Las cuotas sólo se generan/modifican mediante funciones transaccionales.\ncreate or replace function app.installments_guard()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if not app.is_trusted() then\n    raise exception 'Las cuotas sólo se generan o modifican mediante el motor de financiación' using errcode = '42501';\n  end if;\n  if tg_op = 'UPDATE' and\n     (new.principal, new.interest, new.fee, new.due_date, new.contract_id, new.seq)\n     is distinct from (old.principal, old.interest, old.fee, old.due_date, old.contract_id, old.seq) then\n    raise exception 'El importe y vencimiento de una cuota no se modifican; utilice refinanciación' using errcode = '55000';\n  end if;\n  if tg_op = 'DELETE' then\n    raise exception 'Las cuotas no se borran' using errcode = '55000';\n  end if;\n  return coalesce(new, old);\nend $$;\n\ncreate trigger installments_guard before insert or update or delete on public.installments\n  for each row execute function app.installments_guard();\n\n-- -----------------------------------------------------------------------------\n-- Pagos de clientes, aplicaciones y reversiones\n-- -----------------------------------------------------------------------------\ncreate table public.customer_payments (\n  id                    uuid primary key default gen_random_uuid(),\n  org_id                uuid not null references public.organizations(id) on delete cascade,\n  number                text not null,\n  customer_id           uuid not null,\n  contract_id           uuid,\n  reservation_id        uuid,\n  received_on           date not null,\n  method                text not null check (method in ('efectivo','transferencia','deposito','cheque','tarjeta',\n                                                         'trade_in','nota_credito')),\n  cash_account_id       uuid,\n  currency              char(3) not null references public.currencies(code),\n  amount                numeric(18,2) not null check (amount > 0),\n  contract_currency     char(3) references public.currencies(code),\n  fx_rate_to_contract   numeric(18,6) check (fx_rate_to_contract > 0),\n  amount_contract       numeric(18,2) check (amount_contract > 0),\n  reference             text,\n  notes                 text,\n  status                text not null default 'registrado'\n                        check (status in ('registrado','confirmado','revertido','anulado')),\n  evidence_document_id  uuid references public.documents(id),\n  approval_id           uuid references public.approvals(id),\n  registered_by         uuid references public.user_profiles(id),\n  registered_at         timestamptz not null default now(),\n  confirmed_by          uuid references public.user_profiles(id),\n  confirmed_at          timestamptz,\n  unique (org_id, number),\n  unique (id, org_id),\n  foreign key (customer_id, org_id)    references public.customers(id, org_id),\n  foreign key (contract_id, org_id)    references public.contracts(id, org_id),\n  foreign key (reservation_id, org_id) references public.reservations(id, org_id),\n  foreign key (cash_account_id, currency) references public.cash_accounts(id, currency),\n  check (app.money_ok(amount, currency)),\n  check (contract_currency is null or app.money_ok(amount_contract, contract_currency)),\n  check (method in ('trade_in','nota_credito') or cash_account_id is not null),\n  check (method not in ('trade_in','nota_credito') or cash_account_id is null),\n  check (contract_id is not null or reservation_id is not null),\n  check ((status in ('confirmado','revertido')) = (confirmed_at is not null))\n);\ncreate index customer_payments_contract_idx on public.customer_payments(contract_id);\ncreate index customer_payments_status_idx on public.customer_payments(org_id, status, received_on);\ncreate index customer_payments_dup_idx on public.customer_payments(org_id, amount, received_on);\n\ncomment on column public.customer_payments.status is\n  'registrado = informado, aún no cuenta como cobro; confirmado = cobro efectivo aplicado a cuotas; revertido = anulado mediante reversión auditada.';\n\ncreate or replace function app.customer_payments_guard()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if tg_op = 'DELETE' then\n    raise exception 'Los pagos no se borran' using errcode = '55000';\n  end if;\n  if not app.is_trusted() then\n    raise exception 'Los pagos se modifican sólo mediante las acciones de cobro' using errcode = '42501';\n  end if;\n  if old.status in ('confirmado','revertido') and\n     (new.amount, new.currency, new.customer_id, new.received_on, new.method, new.cash_account_id)\n     is distinct from (old.amount, old.currency, old.customer_id, old.received_on, old.method, old.cash_account_id) then\n    raise exception 'Un pago confirmado no se modifica; utilice una reversión' using errcode = '55000';\n  end if;\n  return new;\nend $$;\n\ncreate trigger customer_payments_guard before update or delete on public.customer_payments\n  for each row execute function app.customer_payments_guard();\ncreate trigger customer_payments_audit after insert or update on public.customer_payments\n  for each row execute function app.audit_row();\n\ncreate table public.payment_reversals (\n  id                uuid primary key default gen_random_uuid(),\n  org_id            uuid not null,\n  payment_id        uuid not null unique,\n  reason            text not null check (length(trim(reason)) >= 5),\n  cash_movement_id  uuid references public.cash_movements(id),\n  reversed_by       uuid references public.user_profiles(id),\n  reversed_at       timestamptz not null default now(),\n  unique (id, org_id),\n  foreign key (payment_id, org_id) references public.customer_payments(id, org_id)\n);\ncreate trigger payment_reversals_immutable before update or delete on public.payment_reversals\n  for each row execute function app.forbid_mutation();\n\n-- Un pago puede cubrir varias cuotas y una cuota recibir varios pagos.\n-- Importe en moneda del contrato. Las reversiones insertan filas negativas.\ncreate table public.payment_allocations (\n  id              uuid primary key default gen_random_uuid(),\n  org_id          uuid not null,\n  payment_id      uuid not null,\n  installment_id  uuid not null,\n  amount          numeric(18,2) not null check (amount <> 0),\n  reversal_id     uuid,\n  created_by      uuid references public.user_profiles(id),\n  created_at      timestamptz not null default now(),\n  foreign key (payment_id, org_id)     references public.customer_payments(id, org_id),\n  foreign key (installment_id, org_id) references public.installments(id, org_id),\n  foreign key (reversal_id, org_id)    references public.payment_reversals(id, org_id),\n  check ((amount < 0) = (reversal_id is not null))\n);\ncreate index payment_allocations_installment_idx on public.payment_allocations(installment_id);\ncreate index payment_allocations_payment_idx on public.payment_allocations(payment_id);\n\ncreate trigger payment_allocations_immutable before update or delete on public.payment_allocations\n  for each row execute function app.forbid_mutation();\n\n-- Verificación diferida: ninguna cuota queda sobre-aplicada ni con saldo\n-- negativo, y ningún pago aplica más que su importe.\ncreate or replace function app.check_allocation_bounds()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_inst_amount numeric; v_inst_cancel numeric; v_inst_alloc numeric;\n  v_pay_amount numeric; v_pay_alloc numeric;\nbegin\n  select i.amount, i.amount_cancelled into v_inst_amount, v_inst_cancel\n  from public.installments i where i.id = new.installment_id;\n  select coalesce(sum(a.amount), 0) into v_inst_alloc\n  from public.payment_allocations a where a.installment_id = new.installment_id;\n  if v_inst_alloc < 0 or v_inst_alloc > v_inst_amount - v_inst_cancel then\n    raise exception 'Aplicación inválida: la cuota % quedaría con % aplicado sobre % exigible',\n      new.installment_id, v_inst_alloc, v_inst_amount - v_inst_cancel using errcode = '23514';\n  end if;\n  select p.amount_contract into v_pay_amount from public.customer_payments p where p.id = new.payment_id;\n  select coalesce(sum(a.amount), 0) into v_pay_alloc\n  from public.payment_allocations a where a.payment_id = new.payment_id;\n  if v_pay_alloc < 0 or v_pay_alloc > coalesce(v_pay_amount, 0) then\n    raise exception 'Aplicación inválida: el pago % aplicaría % sobre un importe de %',\n      new.payment_id, v_pay_alloc, v_pay_amount using errcode = '23514';\n  end if;\n  return null;\nend $$;\n\ncreate constraint trigger payment_allocations_bounds\n  after insert on public.payment_allocations\n  deferrable initially deferred\n  for each row execute function app.check_allocation_bounds();\n\n-- -----------------------------------------------------------------------------\n-- Cuenta corriente del contrato (libro append-only)\n-- -----------------------------------------------------------------------------\ncreate table public.contract_ledger_entries (\n  id              bigint generated always as identity primary key,\n  org_id          uuid not null,\n  contract_id     uuid not null,\n  entry_date      date not null,\n  kind            text not null check (kind in ('cuota_generada','recargo','pago','nota_credito',\n                                                 'reversion_pago','baja_refinanciacion')),\n  description     text not null,\n  debit           numeric(18,2) not null default 0 check (debit >= 0),\n  credit          numeric(18,2) not null default 0 check (credit >= 0),\n  installment_id  uuid references public.installments(id),\n  payment_id      uuid references public.customer_payments(id),\n  approval_id     uuid references public.approvals(id),\n  created_by      uuid,\n  created_at      timestamptz not null default now(),\n  foreign key (contract_id, org_id) references public.contracts(id, org_id),\n  check ((debit > 0) <> (credit > 0))\n);\ncreate index contract_ledger_contract_idx on public.contract_ledger_entries(contract_id, entry_date, id);\n\ncreate trigger contract_ledger_immutable before update or delete on public.contract_ledger_entries\n  for each row execute function app.forbid_mutation();\n\n-- -----------------------------------------------------------------------------\n-- Gestión de cobranza\n-- -----------------------------------------------------------------------------\ncreate table public.collection_actions (\n  id               uuid primary key default gen_random_uuid(),\n  org_id           uuid not null,\n  customer_id      uuid not null,\n  contract_id      uuid,\n  channel          text not null check (channel in ('llamada','whatsapp','visita','email','sms','otro')),\n  result           text not null check (result in ('contactado','sin_respuesta','numero_erroneo','promesa_pago',\n                                                   'pago_informado','negativa','otro')),\n  notes            text,\n  promise_amount   numeric(18,2) check (promise_amount > 0),\n  promise_currency char(3) references public.currencies(code),\n  promise_date     date,\n  next_action      text,\n  next_action_at   date,\n  user_id          uuid not null references public.user_profiles(id),\n  occurred_at      timestamptz not null default now(),\n  foreign key (customer_id, org_id) references public.customers(id, org_id),\n  foreign key (contract_id, org_id) references public.contracts(id, org_id),\n  check ((result = 'promesa_pago') = (promise_amount is not null and promise_date is not null and promise_currency is not null)),\n  check (app.money_ok(promise_amount, promise_currency))\n);\ncreate index collection_actions_contract_idx on public.collection_actions(contract_id, occurred_at desc);\ncreate index collection_actions_next_idx on public.collection_actions(org_id, next_action_at);\ncomment on column public.collection_actions.promise_amount is\n  'Compromiso de pago. NO es dinero recibido; sólo los pagos confirmados cuentan como cobro.';\n\ncreate trigger collection_actions_immutable before update or delete on public.collection_actions\n  for each row execute function app.forbid_mutation();\n\n-- -----------------------------------------------------------------------------\n-- Proveedores: facturas y pagos\n-- -----------------------------------------------------------------------------\ncreate table public.supplier_invoices (\n  id              uuid primary key default gen_random_uuid(),\n  org_id          uuid not null references public.organizations(id) on delete cascade,\n  supplier_id     uuid not null,\n  invoice_number  text not null,\n  timbrado        text,\n  issue_date      date not null,\n  due_date        date not null,\n  currency        char(3) not null references public.currencies(code),\n  amount          numeric(18,2) not null check (amount > 0),\n  tax_amount      numeric(18,2) not null default 0 check (tax_amount >= 0),\n  concept         text not null,\n  category        text not null check (category in ('vehiculo','transporte','reparacion','documentacion','general')),\n  vehicle_id      uuid,\n  status          text not null default 'pendiente_aprobacion'\n                  check (status in ('pendiente_aprobacion','aprobada','rechazada','anulada')),\n  approval_id     uuid references public.approvals(id),\n  document_id     uuid references public.documents(id),\n  created_by      uuid references public.user_profiles(id),\n  created_at      timestamptz not null default now(),\n  unique (org_id, supplier_id, invoice_number),\n  unique (id, org_id),\n  foreign key (supplier_id, org_id) references public.suppliers(id, org_id),\n  foreign key (vehicle_id, org_id)  references public.vehicles(id, org_id),\n  check (due_date >= issue_date),\n  check (tax_amount <= amount),\n  check (app.money_ok(amount, currency) and app.money_ok(tax_amount, currency))\n);\ncreate index supplier_invoices_due_idx on public.supplier_invoices(org_id, due_date) where status = 'aprobada';\n\ncreate trigger supplier_invoices_audit after insert or update on public.supplier_invoices\n  for each row execute function app.audit_row();\n\nalter table public.vehicle_costs\n  add foreign key (supplier_invoice_id, org_id) references public.supplier_invoices(id, org_id);\n\ncreate table public.supplier_payments (\n  id               uuid primary key default gen_random_uuid(),\n  org_id           uuid not null,\n  supplier_id      uuid not null,\n  invoice_id       uuid not null,\n  paid_on          date not null,\n  amount           numeric(18,2) not null check (amount > 0),\n  currency         char(3) not null,\n  cash_account_id  uuid not null,\n  reference        text,\n  status           text not null default 'registrado' check (status in ('registrado','confirmado','revertido','anulado')),\n  cash_movement_id uuid references public.cash_movements(id),\n  created_by       uuid references public.user_profiles(id),\n  created_at       timestamptz not null default now(),\n  confirmed_by     uuid references public.user_profiles(id),\n  confirmed_at     timestamptz,\n  unique (id, org_id),\n  foreign key (supplier_id, org_id) references public.suppliers(id, org_id),\n  foreign key (invoice_id, org_id)  references public.supplier_invoices(id, org_id),\n  foreign key (cash_account_id, currency) references public.cash_accounts(id, currency),\n  check (app.money_ok(amount, currency))\n);\ncreate index supplier_payments_invoice_idx on public.supplier_payments(invoice_id);\n\ncreate trigger supplier_payments_audit after insert or update on public.supplier_payments\n  for each row execute function app.audit_row();\n\n-- -----------------------------------------------------------------------------\n-- Gastos generales (no atribuibles a una unidad)\n-- -----------------------------------------------------------------------------\ncreate table public.expenses (\n  id                uuid primary key default gen_random_uuid(),\n  org_id            uuid not null references public.organizations(id) on delete cascade,\n  number            text not null,\n  expense_date      date not null,\n  category          text not null check (category in ('alquiler','servicios','sueldos','comisiones','marketing',\n                                                       'impuestos','mantenimiento','combustible','oficina','otro')),\n  description       text not null,\n  amount            numeric(18,2) not null check (amount > 0),\n  currency          char(3) not null references public.currencies(code),\n  supplier_id       uuid,\n  status            text not null default 'pendiente_aprobacion'\n                    check (status in ('pendiente_aprobacion','aprobado','rechazado','pagado','anulado')),\n  approval_id       uuid references public.approvals(id),\n  cash_account_id   uuid,\n  cash_movement_id  uuid references public.cash_movements(id),\n  created_by        uuid references public.user_profiles(id),\n  created_at        timestamptz not null default now(),\n  unique (org_id, number),\n  unique (id, org_id),\n  foreign key (supplier_id, org_id) references public.suppliers(id, org_id),\n  check (app.money_ok(amount, currency))\n);\n\ncreate trigger expenses_audit after insert or update on public.expenses\n  for each row execute function app.audit_row();\n"},{"name":"20261022000500_views.sql","sql":"-- =============================================================================\n-- Da Silva OS — Numeración automática y vistas de saldos\n-- Todas las vistas usan security_invoker: respetan el RLS de las tablas base.\n-- Los saldos se calculan siempre desde cuotas y aplicaciones; no se almacenan.\n-- =============================================================================\n\n-- -----------------------------------------------------------------------------\n-- Numeración automática: before insert, si number/stock_code viene vacío.\n-- TG_ARGV[0] = columna, [1] = tipo de secuencia, [2] = prefijo\n-- -----------------------------------------------------------------------------\ncreate or replace function app.assign_number()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_col text := tg_argv[0];\n  v_cur text := to_jsonb(new) ->> v_col;\nbegin\n  if v_cur is null or btrim(v_cur) = '' then\n    new := jsonb_populate_record(new, jsonb_build_object(v_col, app.next_number(new.org_id, tg_argv[1], tg_argv[2])));\n  end if;\n  return new;\nend $$;\n\ncreate trigger vehicles_number            before insert on public.vehicles            for each row execute function app.assign_number('stock_code', 'vehicle', 'U');\ncreate trigger deals_number               before insert on public.deals               for each row execute function app.assign_number('number', 'deal', 'V');\ncreate trigger reservations_number        before insert on public.reservations        for each row execute function app.assign_number('number', 'reservation', 'R');\ncreate trigger contracts_number           before insert on public.contracts           for each row execute function app.assign_number('number', 'contract', 'C');\ncreate trigger customer_payments_number   before insert on public.customer_payments   for each row execute function app.assign_number('number', 'payment', 'P');\ncreate trigger trade_in_number            before insert on public.trade_in_appraisals for each row execute function app.assign_number('number', 'trade_in', 'T');\ncreate trigger proposals_number           before insert on public.proposals           for each row execute function app.assign_number('number', 'proposal', 'PR');\ncreate trigger expenses_number            before insert on public.expenses            for each row execute function app.assign_number('number', 'expense', 'G');\n\n-- Las columnas number son NOT NULL; el trigger las completa. Se admite NULL en\n-- el INSERT quitando el NOT NULL de la verificación inicial: los triggers BEFORE\n-- se ejecutan antes de comprobar NOT NULL, así que no hace falta cambiar nada.\n\n-- -----------------------------------------------------------------------------\n-- Saldos por cuota\n-- -----------------------------------------------------------------------------\ncreate or replace view public.v_installment_balances\nwith (security_invoker = true) as\nselect\n  i.id,\n  i.org_id,\n  i.contract_id,\n  i.plan_id,\n  i.seq,\n  i.kind,\n  i.description,\n  i.due_date,\n  i.currency,\n  i.principal,\n  i.interest,\n  i.fee,\n  i.amount,\n  i.amount_cancelled,\n  i.status,\n  coalesce(a.applied, 0)                                   as amount_applied,\n  i.amount - i.amount_cancelled - coalesce(a.applied, 0)   as outstanding,\n  a.last_applied_at,\n  case\n    when i.amount - i.amount_cancelled - coalesce(a.applied, 0) = 0 then\n      case when i.status = 'reemplazada' then 'reemplazada' else 'pagada' end\n    when coalesce(a.applied, 0) > 0 then 'parcial'\n    else 'pendiente'\n  end                                                      as payment_state,\n  case\n    when i.amount - i.amount_cancelled - coalesce(a.applied, 0) > 0 and i.due_date < app.org_today(i.org_id)\n    then app.org_today(i.org_id) - i.due_date\n    else 0\n  end                                                      as days_overdue\nfrom public.installments i\nleft join lateral (\n  select sum(pa.amount) as applied, max(pa.created_at) as last_applied_at\n  from public.payment_allocations pa\n  where pa.installment_id = i.id\n) a on true;\n\ncomment on view public.v_installment_balances is\n  'Saldo por cuota. outstanding = importe − cancelado por refinanciación − aplicaciones netas de pagos CONFIRMADOS. '\n  'Una cuota con saldo 0 nunca figura como vencida.';\n\n-- -----------------------------------------------------------------------------\n-- Saldos por contrato (base de la cartera y de la mora)\n-- -----------------------------------------------------------------------------\ncreate or replace view public.v_contract_balances\nwith (security_invoker = true) as\nwith inst as (\n  select contract_id,\n         sum(amount - amount_cancelled)                                   as total_due,\n         sum(amount_applied)                                              as total_applied,\n         sum(outstanding)                                                 as outstanding,\n         sum(outstanding) filter (where days_overdue > 0)                 as overdue_amount,\n         max(days_overdue)                                                as max_days_overdue,\n         count(*) filter (where days_overdue > 0)                         as overdue_installments,\n         min(due_date) filter (where outstanding > 0 and days_overdue = 0) as next_due_date,\n         sum(interest) filter (where status = 'vigente')                  as total_interest\n  from public.v_installment_balances\n  group by contract_id\n),\npay as (\n  select p.contract_id,\n         sum(p.amount_contract) filter (where p.status = 'confirmado' and p.method not in ('trade_in','nota_credito')) as cash_collected,\n         sum(p.amount_contract) filter (where p.status = 'confirmado')                                                as credits_confirmed,\n         max(p.received_on)     filter (where p.status = 'confirmado' and p.method not in ('trade_in','nota_credito')) as last_payment_on\n  from public.customer_payments p\n  where p.contract_id is not null\n  group by p.contract_id\n),\nalloc as (\n  select p.contract_id, sum(pa.amount) as applied_from_confirmed\n  from public.payment_allocations pa\n  join public.customer_payments p on p.id = pa.payment_id\n  where p.status = 'confirmado'\n  group by p.contract_id\n),\nled as (\n  select contract_id, sum(debit) - sum(credit) as ledger_balance\n  from public.contract_ledger_entries\n  group by contract_id\n)\nselect\n  c.id                                         as contract_id,\n  c.org_id,\n  c.number,\n  c.customer_id,\n  c.vehicle_id,\n  c.currency,\n  c.status,\n  c.collector_id,\n  c.sale_price,\n  c.financed_amount,\n  coalesce(inst.total_due, 0)                  as total_due,\n  coalesce(inst.total_interest, 0)             as total_interest,\n  coalesce(inst.total_applied, 0)              as total_applied,\n  coalesce(inst.outstanding, 0)                as outstanding,\n  coalesce(inst.overdue_amount, 0)             as overdue_amount,\n  coalesce(inst.max_days_overdue, 0)           as max_days_overdue,\n  coalesce(inst.overdue_installments, 0)       as overdue_installments,\n  inst.next_due_date,\n  (select vb.outstanding from public.v_installment_balances vb\n    where vb.contract_id = c.id and vb.due_date = inst.next_due_date and vb.outstanding > 0\n    order by vb.seq limit 1)                   as next_due_amount,\n  coalesce(pay.cash_collected, 0)              as cash_collected,\n  pay.last_payment_on,\n  coalesce(pay.credits_confirmed, 0) - coalesce(alloc.applied_from_confirmed, 0) as unapplied_credit,\n  coalesce(led.ledger_balance, 0)              as ledger_balance\nfrom public.contracts c\nleft join inst  on inst.contract_id = c.id\nleft join pay   on pay.contract_id = c.id\nleft join alloc on alloc.contract_id = c.id\nleft join led   on led.contract_id = c.id;\n\ncomment on view public.v_contract_balances is\n  'Cartera por contrato. Invariante verificada por pruebas: ledger_balance = outstanding − unapplied_credit.';\n\n-- Tramo de mora configurable para una cantidad de días.\ncreate or replace function app.aging_bucket(p_org uuid, p_days integer)\nreturns text\nlanguage sql stable\nset search_path = public, pg_temp\nas $$\n  select label from public.aging_buckets\n  where org_id = p_org and p_days >= min_days and (max_days is null or p_days <= max_days)\n  order by sort_order limit 1\n$$;\n\n-- -----------------------------------------------------------------------------\n-- Promesas de pago y su cumplimiento (NO son cobros)\n-- -----------------------------------------------------------------------------\ncreate or replace view public.v_payment_promises\nwith (security_invoker = true) as\nselect\n  ca.id,\n  ca.org_id,\n  ca.customer_id,\n  ca.contract_id,\n  ca.user_id,\n  ca.occurred_at,\n  ca.promise_amount,\n  ca.promise_currency,\n  ca.promise_date,\n  coalesce(paid.amount, 0) as paid_since_promise,\n  case\n    when coalesce(paid.amount, 0) >= ca.promise_amount then 'cumplida'\n    when ca.promise_date < app.org_today(ca.org_id) then 'incumplida'\n    else 'pendiente'\n  end as promise_status\nfrom public.collection_actions ca\nleft join lateral (\n  select sum(case when p.currency = ca.promise_currency then p.amount\n                  when p.contract_currency = ca.promise_currency then p.amount_contract\n                  else 0 end) as amount\n  from public.customer_payments p\n  where p.customer_id = ca.customer_id\n    and (ca.contract_id is null or p.contract_id = ca.contract_id)\n    and p.status = 'confirmado'\n    and p.method not in ('trade_in','nota_credito')\n    and p.received_on between ca.occurred_at::date and ca.promise_date\n) paid on true\nwhere ca.result = 'promesa_pago';\n\n-- -----------------------------------------------------------------------------\n-- Economía por unidad. Los costes se ocultan (NULL) a quien no tiene\n-- inventory.costs.view, para no mostrar márgenes falsos con coste cero.\n-- -----------------------------------------------------------------------------\ncreate or replace view public.v_vehicle_economics\nwith (security_invoker = true) as\nselect\n  v.id                          as vehicle_id,\n  v.org_id,\n  v.price_currency,\n  v.list_price,\n  o.base_currency,\n  app.fx_rate(v.org_id, v.price_currency, o.base_currency, app.org_today(v.org_id)) as price_fx_rate,\n  case when app.has_perm(v.org_id, 'inventory.costs.view') then coalesce(c.total_base, 0) end      as total_cost_base,\n  case when app.has_perm(v.org_id, 'inventory.costs.view') then coalesce(c.registered_base, 0) end as registered_cost_base,\n  case when app.has_perm(v.org_id, 'inventory.costs.view') then coalesce(c.estimated_base, 0) end  as estimated_cost_base,\n  case when app.has_perm(v.org_id, 'inventory.costs.view') then coalesce(c.acquisition_base, 0) end as acquisition_cost_base,\n  case when app.has_perm(v.org_id, 'inventory.costs.view') then\n    app.round_money(v.list_price * app.fx_rate(v.org_id, v.price_currency, o.base_currency, app.org_today(v.org_id)), o.base_currency)\n    - coalesce(c.total_base, 0)\n  end                                                                                              as estimated_margin_base,\n  app.org_today(v.org_id) - coalesce(v.acquisition_date, v.created_at::date)                       as days_in_stock\nfrom public.vehicles v\njoin public.organizations o on o.id = v.org_id\nleft join lateral (\n  select sum(vc.amount_base)                                       as total_base,\n         sum(vc.amount_base) filter (where not vc.is_estimate)     as registered_base,\n         sum(vc.amount_base) filter (where vc.is_estimate)         as estimated_base,\n         sum(vc.amount_base) filter (where vc.kind = 'adquisicion') as acquisition_base\n  from public.vehicle_costs vc where vc.vehicle_id = v.id\n) c on true;\n\ncomment on view public.v_vehicle_economics is\n  'estimated_margin_base = precio de lista convertido a moneda base con el último tipo de cambio registrado − costes '\n  '(registrados + estimados). NULL si falta tipo de cambio o permiso.';\n\n-- -----------------------------------------------------------------------------\n-- Cuentas por pagar\n-- -----------------------------------------------------------------------------\ncreate or replace view public.v_supplier_invoice_balances\nwith (security_invoker = true) as\nselect\n  si.id,\n  si.org_id,\n  si.supplier_id,\n  si.invoice_number,\n  si.issue_date,\n  si.due_date,\n  si.currency,\n  si.amount,\n  si.concept,\n  si.category,\n  si.vehicle_id,\n  si.status,\n  coalesce(p.confirmed, 0)                         as paid_confirmed,\n  coalesce(p.registered, 0)                        as paid_registered_pending,\n  coalesce(p.reconciled, 0)                        as paid_reconciled,\n  si.amount - coalesce(p.confirmed, 0)             as outstanding,\n  case when si.status = 'aprobada' and si.amount - coalesce(p.confirmed, 0) > 0 and si.due_date < app.org_today(si.org_id)\n       then app.org_today(si.org_id) - si.due_date else 0 end as days_overdue\nfrom public.supplier_invoices si\nleft join lateral (\n  select sum(sp.amount) filter (where sp.status = 'confirmado') as confirmed,\n         sum(sp.amount) filter (where sp.status = 'registrado') as registered,\n         sum(sp.amount) filter (where sp.status = 'confirmado' and cm.status = 'conciliado') as reconciled\n  from public.supplier_payments sp\n  left join public.cash_movements cm on cm.id = sp.cash_movement_id\n  where sp.invoice_id = si.id\n) p on true;\n\n-- -----------------------------------------------------------------------------\n-- Saldos registrados por cuenta\n-- -----------------------------------------------------------------------------\ncreate or replace view public.v_cash_account_balances\nwith (security_invoker = true) as\nselect\n  a.id as account_id,\n  a.org_id,\n  a.name,\n  a.kind,\n  a.currency,\n  a.is_active,\n  coalesce(sum(case when m.direction = 'ingreso' then m.amount else -m.amount end), 0) as registered_balance,\n  coalesce(sum(case when m.direction = 'ingreso' then m.amount else -m.amount end)\n           filter (where m.status = 'conciliado'), 0)                                   as reconciled_balance,\n  count(m.id) filter (where m.status = 'registrado')                                    as unreconciled_count,\n  (select max(r.period_end) from public.reconciliations r\n    where r.account_id = a.id and r.status = 'cerrada')                                 as last_reconciled_on\nfrom public.cash_accounts a\nleft join public.cash_movements m on m.account_id = a.id\ngroup by a.id;\n\ncomment on view public.v_cash_account_balances is\n  'Saldo REGISTRADO en el sistema (no es saldo bancario verificado). reconciled_balance considera sólo movimientos conciliados.';\n"},{"name":"20261022000600_rpc_sales.sql","sql":"-- =============================================================================\n-- Da Silva OS — Funciones transaccionales: helpers, reservas y ventas\n--\n-- Reglas comunes:\n--   * SECURITY DEFINER + verificación explícita de permisos (app.require_perm).\n--   * Bloqueo de filas (FOR UPDATE) sobre la unidad/operación antes de validar\n--     disponibilidad: dos procesos concurrentes se serializan y el segundo ve\n--     el estado ya actualizado por el primero.\n--   * Los índices únicos parciales (una reserva activa / una venta por unidad)\n--     son la última barrera ante cualquier carrera no prevista.\n--   * Errores de negocio: SQLSTATE P0001 con mensaje en español para el usuario.\n-- =============================================================================\n\nalter table public.org_settings\n  add column require_down_payment_before_delivery boolean not null default true;\n\n-- -----------------------------------------------------------------------------\n-- Helpers internos\n-- -----------------------------------------------------------------------------\ncreate or replace function app.fail(p_message text)\nreturns void language plpgsql as $$\nbegin\n  raise exception using message = p_message, errcode = 'P0001';\nend $$;\n\ncreate or replace function app.ledger(\n  p_org uuid, p_contract uuid, p_date date, p_kind text, p_description text,\n  p_debit numeric, p_credit numeric,\n  p_installment uuid default null, p_payment uuid default null, p_approval uuid default null)\nreturns void\nlanguage sql\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  insert into public.contract_ledger_entries\n    (org_id, contract_id, entry_date, kind, description, debit, credit, installment_id, payment_id, approval_id, created_by)\n  values (p_org, p_contract, p_date, p_kind, p_description, coalesce(p_debit, 0), coalesce(p_credit, 0),\n          p_installment, p_payment, p_approval, auth.uid())\n$$;\n\n-- Fija moneda, tipo de cambio e importe del pago en la moneda del contrato.\ncreate or replace function app.bind_payment_to_contract(p_payment uuid, p_contract uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_pay  public.customer_payments%rowtype;\n  v_ctr  public.contracts%rowtype;\n  v_rate numeric;\nbegin\n  select * into v_pay from public.customer_payments where id = p_payment for update;\n  select * into v_ctr from public.contracts where id = p_contract;\n  if v_pay.customer_id <> v_ctr.customer_id then\n    perform app.fail('El pago pertenece a otro cliente');\n  end if;\n  v_rate := app.fx_rate(v_pay.org_id, v_pay.currency, v_ctr.currency, v_pay.received_on);\n  if v_rate is null then\n    perform app.fail(format('No hay tipo de cambio %s→%s registrado al %s. Regístrelo antes de continuar.',\n                            v_pay.currency, v_ctr.currency, to_char(v_pay.received_on, 'DD/MM/YYYY')));\n  end if;\n  update public.customer_payments\n     set contract_id = p_contract,\n         contract_currency = v_ctr.currency,\n         fx_rate_to_contract = v_rate,\n         amount_contract = app.round_money(v_pay.amount * v_rate, v_ctr.currency)\n   where id = p_payment;\nend $$;\n\n-- Aplica el saldo disponible de un pago confirmado a las cuotas pendientes,\n-- de la más antigua a la más reciente (vencimiento, luego secuencia).\ncreate or replace function app.allocate_payment(p_payment uuid)\nreturns numeric\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_pay       public.customer_payments%rowtype;\n  v_remaining numeric;\n  r           record;\n  v_apply     numeric;\nbegin\n  select * into v_pay from public.customer_payments where id = p_payment for update;\n  if v_pay.contract_id is null or v_pay.status <> 'confirmado' then\n    return 0;\n  end if;\n  select v_pay.amount_contract - coalesce(sum(amount), 0) into v_remaining\n  from public.payment_allocations where payment_id = p_payment;\n\n  for r in\n    select i.id, i.amount - i.amount_cancelled - coalesce((select sum(pa.amount) from public.payment_allocations pa\n                                                           where pa.installment_id = i.id), 0) as outstanding\n    from public.installments i\n    where i.contract_id = v_pay.contract_id and i.status = 'vigente'\n    order by i.due_date, i.seq\n    for update of i\n  loop\n    exit when v_remaining <= 0;\n    continue when r.outstanding <= 0;\n    v_apply := least(v_remaining, r.outstanding);\n    insert into public.payment_allocations (org_id, payment_id, installment_id, amount, created_by)\n    values (v_pay.org_id, p_payment, r.id, v_apply, auth.uid());\n    v_remaining := v_remaining - v_apply;\n  end loop;\n  return v_remaining;   -- saldo a favor no aplicado\nend $$;\n\ncreate or replace function app.refresh_contract_status(p_contract uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_out numeric;\nbegin\n  select coalesce(sum(i.amount - i.amount_cancelled), 0)\n         - coalesce((select sum(pa.amount) from public.payment_allocations pa\n                     join public.installments i2 on i2.id = pa.installment_id\n                     where i2.contract_id = p_contract), 0)\n    into v_out\n  from public.installments i where i.contract_id = p_contract;\n  update public.contracts\n     set status = case when v_out = 0 then 'saldado' else 'vigente' end\n   where id = p_contract and status in ('vigente','saldado');\nend $$;\n\n-- Ingreso de caja por un pago confirmado (no aplica a trade-in ni notas de crédito).\ncreate or replace function app.cash_in_for_payment(p_payment uuid)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_pay  public.customer_payments%rowtype;\n  v_name text;\n  v_id   uuid;\nbegin\n  select * into v_pay from public.customer_payments where id = p_payment;\n  if v_pay.method in ('trade_in','nota_credito') then\n    return null;\n  end if;\n  select full_name into v_name from public.customers where id = v_pay.customer_id;\n  insert into public.cash_movements (org_id, account_id, occurred_on, direction, kind, amount, currency,\n                                     description, reference, counterparty, customer_payment_id, created_by)\n  values (v_pay.org_id, v_pay.cash_account_id, v_pay.received_on, 'ingreso', 'cobro_cliente', v_pay.amount, v_pay.currency,\n          'Cobro ' || v_pay.number, v_pay.reference, v_name, v_pay.id, auth.uid())\n  returning id into v_id;\n  return v_id;\nend $$;\n\n-- Valida e inserta un cronograma (cuotas + asientos de cuenta corriente).\n-- p_schedule: [{kind, due_date, principal, interest, fee?, description?}, ...]\ncreate or replace function app.insert_schedule(\n  p_org uuid, p_contract uuid, p_plan uuid, p_currency text, p_entry_date date, p_schedule jsonb)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_seq  integer;\n  e      jsonb;\n  v_inst uuid;\n  v_amt  numeric;\nbegin\n  if jsonb_typeof(p_schedule) <> 'array' or jsonb_array_length(p_schedule) = 0 then\n    perform app.fail('El cronograma está vacío');\n  end if;\n  select coalesce(max(seq), 0) into v_seq from public.installments where contract_id = p_contract;\n  for e in select value from jsonb_array_elements(p_schedule) loop\n    v_seq := v_seq + 1;\n    if (e ->> 'kind') not in ('entrega_usado','entrega_inicial','cuota','refuerzo','recargo') then\n      perform app.fail('Tipo de cuota inválido: ' || coalesce(e ->> 'kind', 'vacío'));\n    end if;\n    if not app.money_ok((e ->> 'principal')::numeric, p_currency)\n       or not app.money_ok(coalesce((e ->> 'interest')::numeric, 0), p_currency)\n       or not app.money_ok(coalesce((e ->> 'fee')::numeric, 0), p_currency) then\n      perform app.fail(format('Importe con decimales no válidos para %s en la cuota %s', p_currency, v_seq));\n    end if;\n    if (e ->> 'due_date')::date < p_entry_date then\n      perform app.fail(format('La cuota %s vence antes de la fecha del contrato', v_seq));\n    end if;\n    insert into public.installments (org_id, contract_id, plan_id, seq, kind, description, due_date, currency,\n                                     principal, interest, fee)\n    values (p_org, p_contract, p_plan, v_seq, e ->> 'kind', e ->> 'description', (e ->> 'due_date')::date, p_currency,\n            coalesce((e ->> 'principal')::numeric, 0), coalesce((e ->> 'interest')::numeric, 0),\n            coalesce((e ->> 'fee')::numeric, 0))\n    returning id, amount into v_inst, v_amt;\n    perform app.ledger(p_org, p_contract, p_entry_date,\n                       case when e ->> 'kind' = 'recargo' then 'recargo' else 'cuota_generada' end,\n                       coalesce(e ->> 'description', initcap(replace(e ->> 'kind', '_', ' ')) || ' ' || v_seq),\n                       v_amt, 0, v_inst);\n  end loop;\nend $$;\n\n-- Libera reservas vencidas (y la unidad, si seguía reservada por ellas).\ncreate or replace function app.expire_reservations(p_org uuid, p_vehicle uuid default null)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  r record;\n  n integer := 0;\nbegin\n  for r in\n    select id, vehicle_id from public.reservations\n    where org_id = p_org and status = 'activa' and expires_at < now()\n      and (p_vehicle is null or vehicle_id = p_vehicle)\n    for update skip locked\n  loop\n    update public.reservations set status = 'vencida', closed_at = now(), close_reason = 'Vencimiento automático'\n     where id = r.id;\n    perform set_config('app.status_note', 'Reserva vencida', true);\n    update public.vehicles set commercial_status = 'disponible', contract_status = 'sin_contrato'\n     where id = r.vehicle_id and commercial_status = 'reservado';\n    perform set_config('app.status_note', '', true);\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\ncreate or replace function public.rpc_housekeeping(p_org uuid)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  if not app.is_member(p_org) then\n    raise exception 'No pertenece a la organización' using errcode = '42501';\n  end if;\n  return app.expire_reservations(p_org);\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Reservas\n-- -----------------------------------------------------------------------------\n-- p_deposit (opcional): {amount, currency, method, cash_account_id, received_on, reference}\ncreate or replace function public.rpc_reservation_create(\n  p_vehicle_id uuid, p_customer_id uuid, p_expires_at timestamptz,\n  p_notes text default null, p_deposit jsonb default null)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_vehicle public.vehicles%rowtype;\n  v_cust_org uuid;\n  v_res     uuid;\n  v_amount  numeric := coalesce((p_deposit ->> 'amount')::numeric, 0);\n  v_cur     text := coalesce(p_deposit ->> 'currency', 'PYG');\nbegin\n  select * into v_vehicle from public.vehicles where id = p_vehicle_id for update;\n  if not found then perform app.fail('La unidad no existe'); end if;\n  perform app.require_perm(v_vehicle.org_id, 'reservations.manage');\n  select org_id into v_cust_org from public.customers where id = p_customer_id;\n  if v_cust_org is distinct from v_vehicle.org_id then perform app.fail('El cliente no existe'); end if;\n\n  perform app.expire_reservations(v_vehicle.org_id, p_vehicle_id);\n  select * into v_vehicle from public.vehicles where id = p_vehicle_id;\n\n  if v_vehicle.commercial_status <> 'disponible' then\n    perform app.fail(format('La unidad %s no está disponible para reservar (estado actual: %s)',\n                            v_vehicle.stock_code, replace(v_vehicle.commercial_status, '_', ' ')));\n  end if;\n  if p_expires_at <= now() then perform app.fail('El vencimiento de la reserva debe ser futuro'); end if;\n  if p_expires_at > now() + interval '90 days' then perform app.fail('Una reserva no puede superar 90 días'); end if;\n\n  insert into public.reservations (org_id, vehicle_id, customer_id, deposit_amount, currency, expires_at, notes, created_by)\n  values (v_vehicle.org_id, p_vehicle_id, p_customer_id, v_amount, v_cur, p_expires_at, p_notes, auth.uid())\n  returning id into v_res;\n\n  perform set_config('app.status_note', 'Reserva creada', true);\n  update public.vehicles set commercial_status = 'reservado', contract_status = 'reservado' where id = p_vehicle_id;\n  perform set_config('app.status_note', '', true);\n\n  if v_amount > 0 then\n    perform app.require_perm(v_vehicle.org_id, 'payments.register');\n    insert into public.customer_payments (org_id, customer_id, reservation_id, received_on, method, cash_account_id,\n                                          currency, amount, reference, notes, registered_by)\n    values (v_vehicle.org_id, p_customer_id, v_res, coalesce((p_deposit ->> 'received_on')::date, app.org_today(v_vehicle.org_id)),\n            p_deposit ->> 'method', (p_deposit ->> 'cash_account_id')::uuid, v_cur, v_amount,\n            p_deposit ->> 'reference', 'Seña de reserva', auth.uid());\n  end if;\n\n  perform app.audit(v_vehicle.org_id, 'reserva_creada', 'reservations', v_res::text,\n                    format('Reserva de %s hasta %s', v_vehicle.stock_code, to_char(p_expires_at, 'DD/MM/YYYY HH24:MI')));\n  return v_res;\nend $$;\n\ncreate or replace function public.rpc_reservation_cancel(p_reservation_id uuid, p_reason text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_res public.reservations%rowtype;\nbegin\n  select * into v_res from public.reservations where id = p_reservation_id for update;\n  if not found then perform app.fail('La reserva no existe'); end if;\n  perform app.require_perm(v_res.org_id, 'reservations.manage');\n  if v_res.status <> 'activa' then perform app.fail('La reserva no está activa'); end if;\n  if coalesce(length(trim(p_reason)), 0) < 5 then perform app.fail('Indique el motivo de la anulación'); end if;\n  perform 1 from public.vehicles where id = v_res.vehicle_id for update;\n\n  update public.reservations set status = 'anulada', closed_at = now(), close_reason = p_reason where id = p_reservation_id;\n  perform set_config('app.status_note', 'Reserva anulada: ' || p_reason, true);\n  update public.vehicles set commercial_status = 'disponible', contract_status = 'sin_contrato'\n   where id = v_res.vehicle_id and commercial_status = 'reservado';\n  perform set_config('app.status_note', '', true);\n  perform app.audit(v_res.org_id, 'reserva_anulada', 'reservations', p_reservation_id::text, p_reason);\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Ventas\n-- -----------------------------------------------------------------------------\n-- Envía una operación en borrador: queda aprobada o pendiente de aprobación.\ncreate or replace function public.rpc_deal_submit(p_deal_id uuid)\nreturns text\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_deal     public.deals%rowtype;\n  v_vehicle  public.vehicles%rowtype;\n  v_settings public.org_settings%rowtype;\n  v_res      public.reservations%rowtype;\n  v_app      public.trade_in_appraisals%rowtype;\n  v_pct      numeric;\n  v_min      numeric;\n  v_rate     numeric;\n  v_kind     text;\n  v_reason   text;\nbegin\n  select * into v_deal from public.deals where id = p_deal_id for update;\n  if not found then perform app.fail('La operación no existe'); end if;\n  perform app.require_perm(v_deal.org_id, 'deals.create');\n  if not app.can_see_deal(v_deal.org_id, v_deal.seller_id) then\n    raise exception 'No tiene acceso a esta operación' using errcode = '42501';\n  end if;\n  if v_deal.status <> 'borrador' then perform app.fail('Sólo se envían operaciones en borrador'); end if;\n\n  select * into v_vehicle from public.vehicles where id = v_deal.vehicle_id;\n  if v_vehicle.commercial_status not in ('disponible','reservado') then\n    perform app.fail(format('La unidad %s ya no está disponible', v_vehicle.stock_code));\n  end if;\n  select * into v_res from public.reservations where vehicle_id = v_deal.vehicle_id and status = 'activa';\n  if found and v_res.customer_id <> v_deal.customer_id then\n    perform app.fail('La unidad está reservada para otro cliente');\n  end if;\n\n  if v_deal.payment_type = 'contado' and v_deal.trade_in_value + v_deal.down_payment <> v_deal.sale_price then\n    perform app.fail('En una venta de contado, entrega + trade-in deben cubrir el precio de venta');\n  end if;\n  if v_deal.payment_type = 'financiado' and v_deal.trade_in_value + v_deal.down_payment >= v_deal.sale_price then\n    perform app.fail('No queda capital a financiar: registre la operación como contado');\n  end if;\n  if v_deal.payment_type = 'financiado' and v_deal.financing_terms is null then\n    perform app.fail('Defina las condiciones de financiación (plazo, tasa y sistema) antes de enviar la operación');\n  end if;\n\n  if v_deal.trade_in_value > 0 then\n    if v_deal.trade_in_appraisal_id is null then perform app.fail('El valor de trade-in requiere una tasación'); end if;\n    select * into v_app from public.trade_in_appraisals where id = v_deal.trade_in_appraisal_id;\n    if v_app.customer_id <> v_deal.customer_id then perform app.fail('La tasación pertenece a otro cliente'); end if;\n    if v_app.status not in ('aprobada','aceptada_cliente','adquirida') then\n      perform app.fail('La tasación del usado aún no está aprobada');\n    end if;\n    if v_app.currency <> v_deal.currency then\n      perform app.fail('La tasación debe expresarse en la moneda de la operación');\n    end if;\n    if v_deal.trade_in_value > coalesce(v_app.accepted_value, v_app.offered_value) then\n      perform app.fail('El valor de trade-in supera el valor aprobado de la tasación');\n    end if;\n  end if;\n\n  select * into v_settings from public.org_settings where org_id = v_deal.org_id;\n  v_pct := case when v_deal.list_price > 0 then round(v_deal.discount_amount * 100 / v_deal.list_price, 2) else 0 end;\n\n  if v_vehicle.min_price is not null then\n    v_rate := app.fx_rate(v_deal.org_id, v_vehicle.price_currency, v_deal.currency, app.org_today(v_deal.org_id));\n    v_min := case when v_rate is null then null else app.round_money(v_vehicle.min_price * v_rate, v_deal.currency) end;\n    if v_min is null then\n      v_kind := 'precio_bajo_minimo';\n      v_reason := 'No hay tipo de cambio para comparar con el precio mínimo autorizado';\n    elsif v_deal.sale_price < v_min then\n      v_kind := 'precio_bajo_minimo';\n      v_reason := format('Precio de venta %s por debajo del mínimo autorizado %s', app.fmt_money(v_deal.sale_price, v_deal.currency), app.fmt_money(v_min, v_deal.currency));\n    end if;\n  end if;\n  if v_kind is null and v_deal.discount_amount * 100 > v_deal.list_price * v_settings.max_discount_pct_without_approval then\n    v_kind := 'descuento';\n    v_reason := format('Descuento de %s%% supera el límite de %s%%', v_pct, v_settings.max_discount_pct_without_approval);\n  end if;\n\n  if v_kind is not null then\n    insert into public.approvals (org_id, kind, entity_type, entity_id, title, reason, amount, currency, payload, requested_by)\n    values (v_deal.org_id, v_kind, 'deal', v_deal.id,\n            format('Operación %s — %s', v_deal.number, case v_kind when 'descuento' then 'descuento' else 'precio bajo mínimo' end),\n            v_reason, v_deal.discount_amount, v_deal.currency,\n            jsonb_build_object('discount_pct', v_pct, 'list_price', v_deal.list_price, 'sale_price', v_deal.sale_price,\n                               'min_price', v_min),\n            auth.uid());\n    update public.deals set status = 'pendiente_aprobacion', requires_approval = true, approval_reason = v_reason\n     where id = p_deal_id;\n    return 'pendiente_aprobacion';\n  end if;\n\n  update public.deals set status = 'aprobada', requires_approval = false, approval_reason = null where id = p_deal_id;\n  return 'aprobada';\nend $$;\n\n-- Vuelve a borrador para modificar condiciones (anula la aprobación pendiente).\ncreate or replace function public.rpc_deal_reopen(p_deal_id uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_deal public.deals%rowtype;\nbegin\n  select * into v_deal from public.deals where id = p_deal_id for update;\n  if not found then perform app.fail('La operación no existe'); end if;\n  perform app.require_perm(v_deal.org_id, 'deals.create');\n  if not app.can_see_deal(v_deal.org_id, v_deal.seller_id) then\n    raise exception 'No tiene acceso a esta operación' using errcode = '42501';\n  end if;\n  if v_deal.status not in ('pendiente_aprobacion','aprobada') then\n    perform app.fail('Sólo se reabren operaciones no formalizadas');\n  end if;\n  update public.approvals set status = 'anulada', decided_at = now(), decided_by = auth.uid(),\n         decision_note = 'Operación reabierta para modificar condiciones'\n   where entity_id = p_deal_id and status = 'pendiente';\n  update public.deals set status = 'borrador' where id = p_deal_id;\nend $$;\n\n-- Formaliza la venta: contrato, plan, cuotas, cuenta corriente, trade-in,\n-- conversión de reserva y estados de la unidad. Todo o nada.\n--   p_plan: {method, rate_input, rate_convention, monthly_rate, term_months, first_due_date, balloons, total_interest}\n--   p_schedule: cronograma completo generado por el motor de financiación\ncreate or replace function public.rpc_deal_formalize(\n  p_deal_id uuid, p_signed_on date, p_plan jsonb, p_schedule jsonb,\n  p_collector_id uuid default null, p_fx_rate_to_base numeric default null)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_deal     public.deals%rowtype;\n  v_vehicle  public.vehicles%rowtype;\n  v_res      public.reservations%rowtype;\n  v_app      public.trade_in_appraisals%rowtype;\n  v_base     char(3);\n  v_financed numeric;\n  v_contract uuid;\n  v_plan     uuid;\n  v_pay      uuid;\n  v_fx       numeric;\n  v_sum_used numeric; v_sum_down numeric; v_sum_fin numeric; v_sum_int numeric; v_bad integer;\n  r          record;\nbegin\n  select * into v_deal from public.deals where id = p_deal_id for update;\n  if not found then perform app.fail('La operación no existe'); end if;\n  perform app.require_perm(v_deal.org_id, 'deals.formalize');\n  if v_deal.status <> 'aprobada' then\n    perform app.fail('Sólo se formalizan operaciones aprobadas (estado actual: ' || replace(v_deal.status, '_', ' ') || ')');\n  end if;\n\n  -- Bloqueo de la unidad: serializa ventas concurrentes de la misma unidad.\n  select * into v_vehicle from public.vehicles where id = v_deal.vehicle_id for update;\n  perform app.expire_reservations(v_deal.org_id, v_deal.vehicle_id);\n  select * into v_vehicle from public.vehicles where id = v_deal.vehicle_id;\n  if v_vehicle.commercial_status not in ('disponible','reservado') then\n    perform app.fail(format('La unidad %s ya no está disponible (estado: %s)', v_vehicle.stock_code,\n                            replace(v_vehicle.commercial_status, '_', ' ')));\n  end if;\n  select * into v_res from public.reservations where vehicle_id = v_deal.vehicle_id and status = 'activa' for update;\n  if found and v_res.customer_id <> v_deal.customer_id then\n    perform app.fail('La unidad está reservada para otro cliente');\n  end if;\n\n  v_financed := v_deal.sale_price - v_deal.trade_in_value - v_deal.down_payment;\n  if v_deal.payment_type = 'contado' and v_financed <> 0 then\n    perform app.fail('Venta de contado con saldo a financiar');\n  end if;\n\n  -- Trade-in: debe estar aceptado por el cliente al valor de la operación.\n  if v_deal.trade_in_value > 0 then\n    select * into v_app from public.trade_in_appraisals where id = v_deal.trade_in_appraisal_id for update;\n    if v_app.status not in ('aceptada_cliente','adquirida') then\n      perform app.fail('El cliente debe aceptar la tasación antes de formalizar');\n    end if;\n    if v_app.accepted_value <> v_deal.trade_in_value then\n      perform app.fail('El valor de trade-in no coincide con el valor aceptado en la tasación');\n    end if;\n  end if;\n\n  -- Validación estructural del cronograma.\n  select coalesce(sum((e->>'principal')::numeric) filter (where e->>'kind' = 'entrega_usado'), 0),\n         coalesce(sum((e->>'principal')::numeric) filter (where e->>'kind' = 'entrega_inicial'), 0),\n         coalesce(sum((e->>'principal')::numeric) filter (where e->>'kind' in ('cuota','refuerzo')), 0),\n         coalesce(sum(coalesce((e->>'interest')::numeric, 0)), 0),\n         count(*) filter (where e->>'kind' in ('entrega_usado','entrega_inicial') and coalesce((e->>'interest')::numeric, 0) <> 0)\n    into v_sum_used, v_sum_down, v_sum_fin, v_sum_int, v_bad\n  from jsonb_array_elements(p_schedule) e;\n  if v_sum_used <> v_deal.trade_in_value then perform app.fail('El cronograma no refleja el valor del trade-in'); end if;\n  if v_sum_down <> v_deal.down_payment then perform app.fail('El cronograma no refleja la entrega inicial'); end if;\n  if v_sum_fin <> v_financed then\n    perform app.fail(format('El capital de las cuotas (%s) no coincide con el capital financiado (%s)', app.fmt_money(v_sum_fin, v_deal.currency), app.fmt_money(v_financed, v_deal.currency)));\n  end if;\n  if v_bad > 0 then perform app.fail('Las entregas no pueden llevar intereses'); end if;\n  if v_sum_int <> coalesce((p_plan->>'total_interest')::numeric, 0) then\n    perform app.fail('El interés total del plan no coincide con el cronograma');\n  end if;\n\n  select base_currency into v_base from public.organizations where id = v_deal.org_id;\n  v_fx := coalesce(p_fx_rate_to_base, app.fx_rate(v_deal.org_id, v_deal.currency, v_base, p_signed_on));\n  if v_fx is null then\n    perform app.fail(format('Registre el tipo de cambio %s→%s para formalizar', v_deal.currency, v_base));\n  end if;\n\n  insert into public.contracts (org_id, deal_id, customer_id, vehicle_id, currency, sale_price, trade_in_value,\n                                down_payment, financed_amount, signed_on, collector_id, created_by)\n  values (v_deal.org_id, v_deal.id, v_deal.customer_id, v_deal.vehicle_id, v_deal.currency, v_deal.sale_price,\n          v_deal.trade_in_value, v_deal.down_payment, v_financed, p_signed_on, p_collector_id, auth.uid())\n  returning id into v_contract;\n\n  insert into public.financing_plans (org_id, contract_id, version_no, method, principal, rate_input, rate_convention,\n                                      monthly_rate, term_months, first_due_date, balloons, total_interest, total_payable,\n                                      created_by)\n  values (v_deal.org_id, v_contract, 1,\n          case when v_financed = 0 then 'sin_financiacion' else p_plan->>'method' end,\n          v_financed, coalesce((p_plan->>'rate_input')::numeric, 0),\n          coalesce(p_plan->>'rate_convention', 'nominal_annual'), coalesce((p_plan->>'monthly_rate')::numeric, 0),\n          coalesce((p_plan->>'term_months')::integer, 0), (p_plan->>'first_due_date')::date,\n          coalesce(p_plan->'balloons', '[]'::jsonb), v_sum_int, v_financed + v_sum_int, auth.uid())\n  returning id into v_plan;\n\n  insert into public.contract_versions (org_id, contract_id, version_no, reason, terms, financing_plan_id, created_by)\n  values (v_deal.org_id, v_contract, 1, 'Contrato original',\n          jsonb_build_object('sale_price', v_deal.sale_price, 'list_price', v_deal.list_price,\n                             'discount_amount', v_deal.discount_amount, 'trade_in_value', v_deal.trade_in_value,\n                             'down_payment', v_deal.down_payment, 'financed_amount', v_financed,\n                             'currency', v_deal.currency, 'plan', p_plan, 'schedule', p_schedule),\n          v_plan, auth.uid());\n\n  perform app.insert_schedule(v_deal.org_id, v_contract, v_plan, v_deal.currency, p_signed_on, p_schedule);\n\n  -- Trade-in como pago en especie (sin movimiento de caja).\n  if v_deal.trade_in_value > 0 then\n    insert into public.customer_payments (org_id, customer_id, contract_id, received_on, method, currency, amount,\n                                          contract_currency, fx_rate_to_contract, amount_contract, reference, notes,\n                                          status, registered_by, confirmed_by, confirmed_at)\n    values (v_deal.org_id, v_deal.customer_id, v_contract, p_signed_on, 'trade_in', v_deal.currency, v_deal.trade_in_value,\n            v_deal.currency, 1, v_deal.trade_in_value, v_app.number,\n            format('Vehículo usado %s %s %s', v_app.brand_name, v_app.model, v_app.year_model),\n            'confirmado', auth.uid(), auth.uid(), now())\n    returning id into v_pay;\n    perform app.ledger(v_deal.org_id, v_contract, p_signed_on, 'pago', 'Trade-in ' || v_app.number, 0, v_deal.trade_in_value,\n                       null, v_pay);\n    perform app.allocate_payment(v_pay);\n  end if;\n\n  -- Reserva: se convierte y sus señas pasan al contrato.\n  if v_res.id is not null then\n    update public.reservations set status = 'convertida', deal_id = v_deal.id, closed_at = now(),\n           close_reason = 'Convertida en venta ' || v_deal.number\n     where id = v_res.id;\n    for r in select id, status, number from public.customer_payments\n             where reservation_id = v_res.id and status in ('registrado','confirmado') loop\n      perform app.bind_payment_to_contract(r.id, v_contract);\n      if r.status = 'confirmado' then\n        perform app.ledger(v_deal.org_id, v_contract, p_signed_on, 'pago', 'Seña de reserva ' || r.number, 0,\n                           (select amount_contract from public.customer_payments where id = r.id), null, r.id);\n        perform app.allocate_payment(r.id);\n      end if;\n    end loop;\n  end if;\n\n  update public.deals set status = 'formalizada', formalized_at = now(), fx_rate_to_base = v_fx where id = v_deal.id;\n  perform set_config('app.status_note', 'Venta ' || v_deal.number, true);\n  update public.vehicles set commercial_status = 'vendido_pendiente_entrega', contract_status = 'contrato_firmado'\n   where id = v_deal.vehicle_id;\n  perform set_config('app.status_note', '', true);\n\n  if v_deal.opportunity_id is not null then\n    update public.opportunities\n       set status = 'ganada',\n           stage_id = (select id from public.pipeline_stages where org_id = v_deal.org_id and key = 'venta')\n     where id = v_deal.opportunity_id;\n  end if;\n\n  perform app.refresh_contract_status(v_contract);\n  perform app.audit(v_deal.org_id, 'venta_formalizada', 'deals', v_deal.id::text,\n                    format('Venta %s formalizada: %s', v_deal.number, app.fmt_money(v_deal.sale_price, v_deal.currency)));\n  return v_contract;\nend $$;\n\ncreate or replace function public.rpc_deal_deliver(p_deal_id uuid, p_delivered_on date, p_notes text default null)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_deal     public.deals%rowtype;\n  v_required boolean;\n  v_pending  numeric;\nbegin\n  select * into v_deal from public.deals where id = p_deal_id for update;\n  if not found then perform app.fail('La operación no existe'); end if;\n  perform app.require_perm(v_deal.org_id, 'deals.deliver');\n  if v_deal.status <> 'formalizada' then perform app.fail('Sólo se entregan ventas formalizadas'); end if;\n  perform 1 from public.vehicles where id = v_deal.vehicle_id for update;\n\n  select require_down_payment_before_delivery into v_required from public.org_settings where org_id = v_deal.org_id;\n  if v_required then\n    select coalesce(sum(b.outstanding), 0) into v_pending\n    from public.v_installment_balances b\n    join public.contracts c on c.id = b.contract_id\n    where c.deal_id = p_deal_id and b.kind in ('entrega_inicial','entrega_usado');\n    if v_pending > 0 then\n      perform app.fail(format('La entrega inicial tiene un saldo pendiente de %s. Debe estar cobrada y confirmada antes de entregar.',\n                              app.fmt_money(v_pending, v_deal.currency)));\n    end if;\n  end if;\n\n  update public.deals set status = 'entregada', delivered_at = p_delivered_on::timestamptz,\n         notes = coalesce(p_notes, notes) where id = p_deal_id;\n  perform set_config('app.status_note', 'Entrega ' || v_deal.number, true);\n  update public.vehicles set commercial_status = 'entregado' where id = v_deal.vehicle_id;\n  perform set_config('app.status_note', '', true);\n  if v_deal.opportunity_id is not null then\n    update public.opportunities\n       set stage_id = (select id from public.pipeline_stages where org_id = v_deal.org_id and key = 'entrega')\n     where id = v_deal.opportunity_id;\n  end if;\n  perform app.audit(v_deal.org_id, 'venta_entregada', 'deals', p_deal_id::text, 'Entrega física registrada');\nend $$;\n\ncreate or replace function public.rpc_deal_cancel(p_deal_id uuid, p_reason text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_deal     public.deals%rowtype;\n  v_contract public.contracts%rowtype;\n  v_cash     numeric;\n  r          record;\n  v_rev      uuid;\nbegin\n  select * into v_deal from public.deals where id = p_deal_id for update;\n  if not found then perform app.fail('La operación no existe'); end if;\n  if coalesce(length(trim(p_reason)), 0) < 5 then perform app.fail('Indique el motivo de la anulación'); end if;\n\n  if v_deal.status in ('borrador','pendiente_aprobacion','aprobada') then\n    if not (app.has_perm(v_deal.org_id, 'deals.cancel')\n            or (app.has_perm(v_deal.org_id, 'deals.create') and v_deal.seller_id = auth.uid())) then\n      raise exception 'No tiene permiso para anular esta operación' using errcode = '42501';\n    end if;\n    update public.approvals set status = 'anulada', decided_at = now(), decided_by = auth.uid(),\n           decision_note = 'Operación anulada'\n     where entity_id = p_deal_id and status = 'pendiente';\n    update public.deals set status = 'anulada', cancelled_at = now(), cancel_reason = p_reason where id = p_deal_id;\n    return;\n  end if;\n\n  perform app.require_perm(v_deal.org_id, 'deals.cancel');\n  if v_deal.status <> 'formalizada' then\n    perform app.fail('Una venta entregada no se anula; registre una devolución con dirección');\n  end if;\n\n  select * into v_contract from public.contracts where deal_id = p_deal_id for update;\n  select coalesce(sum(pa.amount), 0) into v_cash\n  from public.payment_allocations pa\n  join public.customer_payments p on p.id = pa.payment_id\n  where p.contract_id = v_contract.id and p.method <> 'trade_in';\n  if v_cash > 0 then\n    perform app.fail('El contrato tiene cobros aplicados. Revierta o reintegre los pagos antes de anular la venta.');\n  end if;\n\n  -- Revierte el trade-in en especie.\n  for r in select id, amount_contract, number from public.customer_payments\n           where contract_id = v_contract.id and method = 'trade_in' and status = 'confirmado' loop\n    insert into public.payment_reversals (org_id, payment_id, reason, reversed_by)\n    values (v_deal.org_id, r.id, 'Anulación de venta: ' || p_reason, auth.uid()) returning id into v_rev;\n    insert into public.payment_allocations (org_id, payment_id, installment_id, amount, reversal_id, created_by)\n    select v_deal.org_id, r.id, pa.installment_id, -sum(pa.amount), v_rev, auth.uid()\n    from public.payment_allocations pa where pa.payment_id = r.id\n    group by pa.installment_id having sum(pa.amount) > 0;\n    update public.customer_payments set status = 'revertido' where id = r.id;\n    perform app.ledger(v_deal.org_id, v_contract.id, app.org_today(v_deal.org_id), 'reversion_pago',\n                       'Reversión trade-in ' || r.number, r.amount_contract, 0, null, r.id);\n  end loop;\n\n  -- Da de baja el saldo de las cuotas.\n  for r in select id, outstanding from public.v_installment_balances where contract_id = v_contract.id and outstanding > 0 loop\n    update public.installments set amount_cancelled = amount_cancelled + r.outstanding, status = 'reemplazada' where id = r.id;\n    perform app.ledger(v_deal.org_id, v_contract.id, app.org_today(v_deal.org_id), 'baja_refinanciacion',\n                       'Baja por anulación de venta', 0, r.outstanding, r.id);\n  end loop;\n\n  update public.contracts set status = 'anulado' where id = v_contract.id;\n  update public.deals set status = 'anulada', cancelled_at = now(), cancel_reason = p_reason where id = p_deal_id;\n  perform set_config('app.status_note', 'Venta anulada: ' || p_reason, true);\n  update public.vehicles set commercial_status = 'disponible', contract_status = 'sin_contrato' where id = v_deal.vehicle_id;\n  perform set_config('app.status_note', '', true);\n  perform app.audit(v_deal.org_id, 'venta_anulada', 'deals', p_deal_id::text, p_reason);\nend $$;\n"},{"name":"20261022000700_rpc_finance.sql","sql":"-- =============================================================================\n-- Da Silva OS — Funciones transaccionales: cobros, ajustes, aprobaciones,\n-- tasaciones, proveedores, gastos, caja y conciliación\n-- =============================================================================\n\n-- -----------------------------------------------------------------------------\n-- Pagos de clientes\n-- -----------------------------------------------------------------------------\n-- p: {customer_id, contract_id?, reservation_id?, received_on, method, cash_account_id,\n--     currency, amount, reference?, notes?, evidence_document_id?, allow_duplicate?}\ncreate or replace function public.rpc_payment_register(p jsonb)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_org      uuid;\n  v_ctr      public.contracts%rowtype;\n  v_id       uuid;\n  v_amount   numeric := (p->>'amount')::numeric;\n  v_currency text := p->>'currency';\n  v_date     date := (p->>'received_on')::date;\n  v_dup      text;\nbegin\n  select org_id into v_org from public.customers where id = (p->>'customer_id')::uuid;\n  if v_org is null then perform app.fail('El cliente no existe'); end if;\n  perform app.require_perm(v_org, 'payments.register');\n\n  if (p->>'method') in ('trade_in','nota_credito') then\n    perform app.fail('Este tipo de crédito se registra desde la venta o mediante una aprobación');\n  end if;\n  if v_amount is null or v_amount <= 0 then perform app.fail('El importe debe ser mayor que cero'); end if;\n  if not app.money_ok(v_amount, v_currency) then\n    perform app.fail(format('Importe con decimales no válidos para %s', v_currency));\n  end if;\n  if v_date is null or v_date > app.org_today(v_org) then\n    perform app.fail('La fecha de cobro no puede ser futura');\n  end if;\n  if (p->>'contract_id') is null and (p->>'reservation_id') is null then\n    perform app.fail('Indique el contrato o la reserva a la que corresponde el pago');\n  end if;\n  if (p->>'contract_id') is not null then\n    select * into v_ctr from public.contracts where id = (p->>'contract_id')::uuid;\n    if v_ctr.customer_id is distinct from (p->>'customer_id')::uuid then\n      perform app.fail('El contrato no pertenece al cliente');\n    end if;\n    if v_ctr.status = 'anulado' then perform app.fail('El contrato está anulado'); end if;\n  end if;\n  if not exists (select 1 from public.cash_accounts\n                 where id = (p->>'cash_account_id')::uuid and org_id = v_org and is_active and currency = v_currency) then\n    perform app.fail('Seleccione una cuenta activa en la misma moneda del pago');\n  end if;\n\n  -- Detección de duplicados: misma cuenta, importe, fecha y referencia.\n  select number into v_dup from public.customer_payments\n  where org_id = v_org and amount = v_amount and currency = v_currency and received_on = v_date\n    and cash_account_id = (p->>'cash_account_id')::uuid\n    and coalesce(reference, '') = coalesce(p->>'reference', '')\n    and status in ('registrado','confirmado')\n  limit 1;\n  if v_dup is not null and coalesce((p->>'allow_duplicate')::boolean, false) = false then\n    raise exception using errcode = 'P0001',\n      message = format('Posible pago duplicado: %s tiene la misma cuenta, fecha, importe y referencia.', v_dup),\n      hint = 'duplicate';\n  end if;\n\n  insert into public.customer_payments (org_id, customer_id, contract_id, reservation_id, received_on, method,\n                                        cash_account_id, currency, amount, reference, notes, evidence_document_id,\n                                        registered_by)\n  values (v_org, (p->>'customer_id')::uuid, (p->>'contract_id')::uuid, (p->>'reservation_id')::uuid, v_date,\n          p->>'method', (p->>'cash_account_id')::uuid, v_currency, v_amount, nullif(p->>'reference', ''),\n          nullif(p->>'notes', ''), (p->>'evidence_document_id')::uuid, auth.uid())\n  returning id into v_id;\n\n  if v_ctr.id is not null then\n    perform app.bind_payment_to_contract(v_id, v_ctr.id);\n  end if;\n  return v_id;\nend $$;\n\n-- Confirma un pago: lo aplica a las cuotas, registra la cuenta corriente y\n-- el ingreso de caja. Sólo a partir de aquí cuenta como cobro.\ncreate or replace function public.rpc_payment_confirm(p_payment_id uuid)\nreturns numeric\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_pay       public.customer_payments%rowtype;\n  v_unapplied numeric := 0;\nbegin\n  select * into v_pay from public.customer_payments where id = p_payment_id for update;\n  if not found then perform app.fail('El pago no existe'); end if;\n  perform app.require_perm(v_pay.org_id, 'payments.confirm');\n  if v_pay.status <> 'registrado' then perform app.fail('Sólo se confirman pagos registrados'); end if;\n\n  update public.customer_payments set status = 'confirmado', confirmed_by = auth.uid(), confirmed_at = now()\n   where id = p_payment_id;\n  perform app.cash_in_for_payment(p_payment_id);\n\n  if v_pay.contract_id is not null then\n    perform app.ledger(v_pay.org_id, v_pay.contract_id, v_pay.received_on, 'pago',\n                       format('Pago %s (%s)', v_pay.number, v_pay.method), 0, v_pay.amount_contract, null, p_payment_id);\n    v_unapplied := app.allocate_payment(p_payment_id);\n    perform app.refresh_contract_status(v_pay.contract_id);\n  end if;\n  perform app.audit(v_pay.org_id, 'pago_confirmado', 'customer_payments', p_payment_id::text,\n                    format('Pago %s confirmado: %s', v_pay.number, app.fmt_money(v_pay.amount, v_pay.currency)));\n  return v_unapplied;\nend $$;\n\n-- Anula un pago aún no confirmado (no tuvo efectos contables).\ncreate or replace function public.rpc_payment_void(p_payment_id uuid, p_reason text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_pay public.customer_payments%rowtype;\nbegin\n  select * into v_pay from public.customer_payments where id = p_payment_id for update;\n  if not found then perform app.fail('El pago no existe'); end if;\n  perform app.require_perm(v_pay.org_id, 'payments.register');\n  if v_pay.status <> 'registrado' then\n    perform app.fail('Sólo se anulan pagos no confirmados; para un pago confirmado utilice una reversión');\n  end if;\n  if coalesce(length(trim(p_reason)), 0) < 5 then perform app.fail('Indique el motivo'); end if;\n  update public.customer_payments set status = 'anulado', notes = concat_ws(' · ', notes, 'Anulado: ' || p_reason)\n   where id = p_payment_id;\n  perform app.audit(v_pay.org_id, 'pago_anulado', 'customer_payments', p_payment_id::text, p_reason);\nend $$;\n\n-- Revierte un pago confirmado con trazabilidad completa:\n-- aplicaciones negativas, asiento de cuenta corriente y egreso de caja.\ncreate or replace function public.rpc_payment_reverse(p_payment_id uuid, p_reason text)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_pay public.customer_payments%rowtype;\n  v_rev uuid;\n  v_mov public.cash_movements%rowtype;\n  v_cm  uuid;\nbegin\n  select * into v_pay from public.customer_payments where id = p_payment_id for update;\n  if not found then perform app.fail('El pago no existe'); end if;\n  perform app.require_perm(v_pay.org_id, 'payments.reverse');\n  if v_pay.status <> 'confirmado' then perform app.fail('Sólo se revierten pagos confirmados'); end if;\n  if coalesce(length(trim(p_reason)), 0) < 5 then perform app.fail('Indique el motivo de la reversión'); end if;\n\n  -- 1) Contramovimiento de caja (si el pago generó ingreso).\n  select * into v_mov from public.cash_movements\n   where customer_payment_id = p_payment_id and kind = 'cobro_cliente' and reverses_id is null;\n  if found then\n    insert into public.cash_movements (org_id, account_id, occurred_on, direction, kind, amount, currency, description,\n                                       reference, counterparty, customer_payment_id, reverses_id, created_by)\n    values (v_pay.org_id, v_mov.account_id, app.org_today(v_pay.org_id), 'egreso', 'reversion', v_mov.amount, v_mov.currency,\n            format('Reversión de %s: %s', v_pay.number, p_reason), v_mov.reference, v_mov.counterparty,\n            p_payment_id, v_mov.id, auth.uid())\n    returning id into v_cm;\n  end if;\n\n  -- 2) Registro inmutable de la reversión.\n  insert into public.payment_reversals (org_id, payment_id, reason, cash_movement_id, reversed_by)\n  values (v_pay.org_id, p_payment_id, p_reason, v_cm, auth.uid()) returning id into v_rev;\n\n  -- 3) Aplicaciones compensatorias (negativas) por cuota.\n  perform 1 from public.installments i\n   where i.id in (select installment_id from public.payment_allocations where payment_id = p_payment_id)\n   for update;\n  insert into public.payment_allocations (org_id, payment_id, installment_id, amount, reversal_id, created_by)\n  select v_pay.org_id, p_payment_id, pa.installment_id, -sum(pa.amount), v_rev, auth.uid()\n  from public.payment_allocations pa where pa.payment_id = p_payment_id\n  group by pa.installment_id having sum(pa.amount) > 0;\n\n  -- 4) Cuenta corriente.\n  if v_pay.contract_id is not null then\n    perform app.ledger(v_pay.org_id, v_pay.contract_id, app.org_today(v_pay.org_id), 'reversion_pago',\n                       format('Reversión de %s: %s', v_pay.number, p_reason), v_pay.amount_contract, 0, null, p_payment_id);\n  end if;\n\n  update public.customer_payments set status = 'revertido' where id = p_payment_id;\n  if v_pay.contract_id is not null then\n    perform app.refresh_contract_status(v_pay.contract_id);\n  end if;\n  perform app.audit(v_pay.org_id, 'pago_revertido', 'customer_payments', p_payment_id::text, p_reason);\n  return v_rev;\nend $$;\n\n-- Posibles duplicados antes de registrar (para advertir en la interfaz).\ncreate or replace function public.rpc_payment_possible_duplicates(\n  p_org uuid, p_amount numeric, p_currency text, p_received_on date, p_reference text default null)\nreturns table (id uuid, number text, customer_name text, received_on date, amount numeric, currency char(3),\n               reference text, status text)\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  perform app.require_perm(p_org, 'payments.register');\n  return query\n  select p.id, p.number, c.full_name, p.received_on, p.amount, p.currency, p.reference, p.status\n  from public.customer_payments p\n  join public.customers c on c.id = p.customer_id\n  where p.org_id = p_org and p.amount = p_amount and p.currency = p_currency\n    and p.received_on between p_received_on - 3 and p_received_on + 3\n    and (p_reference is null or p.reference is null or p.reference = p_reference)\n    and p.status in ('registrado','confirmado')\n  order by p.received_on desc\n  limit 10;\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Ajustes de contrato (siempre mediante aprobación)\n-- -----------------------------------------------------------------------------\n-- p_kind: 'recargo' | 'nota_credito'\ncreate or replace function public.rpc_contract_request_adjustment(\n  p_contract_id uuid, p_kind text, p_amount numeric, p_description text, p_reason text, p_due_date date default null)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_ctr public.contracts%rowtype;\n  v_out numeric;\n  v_id  uuid;\nbegin\n  select * into v_ctr from public.contracts where id = p_contract_id;\n  if not found then perform app.fail('El contrato no existe'); end if;\n  perform app.require_perm(v_ctr.org_id, 'contracts.adjust');\n  if v_ctr.status = 'anulado' then perform app.fail('El contrato está anulado'); end if;\n  if p_kind not in ('recargo','nota_credito') then perform app.fail('Tipo de ajuste inválido'); end if;\n  if p_amount is null or p_amount <= 0 or not app.money_ok(p_amount, v_ctr.currency) then\n    perform app.fail('Importe inválido');\n  end if;\n  if coalesce(length(trim(p_reason)), 0) < 5 then perform app.fail('Indique el motivo'); end if;\n  if p_kind = 'recargo' and p_due_date is null then perform app.fail('Indique el vencimiento del recargo'); end if;\n  if p_kind = 'nota_credito' then\n    select outstanding into v_out from public.v_contract_balances where contract_id = p_contract_id;\n    if p_amount > v_out then\n      perform app.fail(format('La nota de crédito (%s) supera el saldo pendiente (%s)', app.fmt_money(p_amount, v_ctr.currency), app.fmt_money(v_out, v_ctr.currency)));\n    end if;\n  end if;\n  insert into public.approvals (org_id, kind, entity_type, entity_id, title, reason, amount, currency, payload, requested_by)\n  values (v_ctr.org_id, p_kind, 'contract', p_contract_id,\n          format('%s en contrato %s', case p_kind when 'recargo' then 'Recargo' else 'Nota de crédito' end, v_ctr.number),\n          p_reason, p_amount, v_ctr.currency,\n          jsonb_build_object('description', p_description, 'due_date', p_due_date), auth.uid())\n  returning id into v_id;\n  return v_id;\nend $$;\n\n-- Refinanciación: reemplaza el saldo vigente por un nuevo cronograma.\ncreate or replace function public.rpc_contract_request_refinance(\n  p_contract_id uuid, p_plan jsonb, p_schedule jsonb, p_reason text)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_ctr public.contracts%rowtype;\n  v_out numeric;\n  v_principal numeric;\n  v_id  uuid;\nbegin\n  select * into v_ctr from public.contracts where id = p_contract_id;\n  if not found then perform app.fail('El contrato no existe'); end if;\n  perform app.require_perm(v_ctr.org_id, 'contracts.adjust');\n  if v_ctr.status <> 'vigente' then perform app.fail('Sólo se refinancian contratos vigentes'); end if;\n  if coalesce(length(trim(p_reason)), 0) < 5 then perform app.fail('Indique el motivo'); end if;\n  select coalesce(sum(outstanding), 0) into v_out from public.v_installment_balances\n   where contract_id = p_contract_id and status = 'vigente';\n  select coalesce(sum((e->>'principal')::numeric), 0) into v_principal\n  from jsonb_array_elements(p_schedule) e where e->>'kind' in ('cuota','refuerzo');\n  if v_principal <> v_out then\n    perform app.fail(format('El capital refinanciado (%s) debe igualar el saldo pendiente (%s)', app.fmt_money(v_principal, v_ctr.currency), app.fmt_money(v_out, v_ctr.currency)));\n  end if;\n  insert into public.approvals (org_id, kind, entity_type, entity_id, title, reason, amount, currency, payload, requested_by)\n  values (v_ctr.org_id, 'refinanciacion', 'contract', p_contract_id,\n          format('Refinanciación del contrato %s', v_ctr.number), p_reason, v_out, v_ctr.currency,\n          jsonb_build_object('plan', p_plan, 'schedule', p_schedule, 'outstanding_at_request', v_out), auth.uid())\n  returning id into v_id;\n  return v_id;\nend $$;\n\ncreate or replace function app.apply_refinance(p_approval public.approvals)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_ctr     public.contracts%rowtype;\n  v_out     numeric;\n  v_version integer;\n  v_plan    uuid;\n  v_int     numeric;\n  r         record;\nbegin\n  select * into v_ctr from public.contracts where id = p_approval.entity_id for update;\n  perform 1 from public.installments where contract_id = v_ctr.id for update;\n  select coalesce(sum(outstanding), 0) into v_out from public.v_installment_balances\n   where contract_id = v_ctr.id and status = 'vigente';\n  if v_out <> (p_approval.payload->>'outstanding_at_request')::numeric then\n    perform app.fail('El saldo del contrato cambió desde la solicitud. Genere una nueva propuesta de refinanciación.');\n  end if;\n  v_version := v_ctr.current_version + 1;\n  select coalesce(sum(coalesce((e->>'interest')::numeric, 0)), 0) into v_int\n  from jsonb_array_elements(p_approval.payload->'schedule') e;\n\n  for r in select id, outstanding from public.v_installment_balances\n           where contract_id = v_ctr.id and status = 'vigente' and outstanding > 0 loop\n    update public.installments set amount_cancelled = amount_cancelled + r.outstanding, status = 'reemplazada'\n     where id = r.id;\n    perform app.ledger(v_ctr.org_id, v_ctr.id, app.org_today(v_ctr.org_id), 'baja_refinanciacion',\n                       format('Baja por refinanciación (versión %s)', v_version), 0, r.outstanding, r.id, null, p_approval.id);\n  end loop;\n  update public.installments set status = 'reemplazada'\n   where contract_id = v_ctr.id and status = 'vigente'\n     and id in (select id from public.v_installment_balances where contract_id = v_ctr.id and outstanding = 0\n                and kind in ('cuota','refuerzo') and amount_applied = 0);\n\n  insert into public.financing_plans (org_id, contract_id, version_no, method, principal, rate_input, rate_convention,\n                                      monthly_rate, term_months, first_due_date, balloons, total_interest, total_payable,\n                                      created_by)\n  values (v_ctr.org_id, v_ctr.id, v_version, p_approval.payload->'plan'->>'method', v_out,\n          coalesce((p_approval.payload->'plan'->>'rate_input')::numeric, 0),\n          coalesce(p_approval.payload->'plan'->>'rate_convention', 'nominal_annual'),\n          coalesce((p_approval.payload->'plan'->>'monthly_rate')::numeric, 0),\n          coalesce((p_approval.payload->'plan'->>'term_months')::integer, 0),\n          (p_approval.payload->'plan'->>'first_due_date')::date,\n          coalesce(p_approval.payload->'plan'->'balloons', '[]'::jsonb), v_int, v_out + v_int, auth.uid())\n  returning id into v_plan;\n\n  insert into public.contract_versions (org_id, contract_id, version_no, reason, terms, financing_plan_id, approval_id, created_by)\n  values (v_ctr.org_id, v_ctr.id, v_version, 'Refinanciación: ' || coalesce(p_approval.reason, ''), p_approval.payload,\n          v_plan, p_approval.id, p_approval.requested_by);\n\n  perform app.insert_schedule(v_ctr.org_id, v_ctr.id, v_plan, v_ctr.currency, app.org_today(v_ctr.org_id),\n                              p_approval.payload->'schedule');\n  update public.contracts set current_version = v_version where id = v_ctr.id;\n\n  -- Saldos a favor existentes se aplican al nuevo cronograma.\n  for r in select id from public.customer_payments where contract_id = v_ctr.id and status = 'confirmado' loop\n    perform app.allocate_payment(r.id);\n  end loop;\n  perform app.refresh_contract_status(v_ctr.id);\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Decisión de aprobaciones (con separación de funciones)\n-- -----------------------------------------------------------------------------\ncreate or replace function public.rpc_approval_decide(p_approval_id uuid, p_approve boolean, p_note text default null)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_app  public.approvals%rowtype;\n  v_ctr  public.contracts%rowtype;\n  v_pay  uuid;\n  v_seq  integer;\n  v_inst uuid;\nbegin\n  select * into v_app from public.approvals where id = p_approval_id for update;\n  if not found then perform app.fail('La solicitud no existe'); end if;\n  if v_app.status <> 'pendiente' then perform app.fail('La solicitud ya fue resuelta'); end if;\n  perform app.require_perm(v_app.org_id, app.approval_permission(v_app.kind));\n  if v_app.requested_by = auth.uid() and app.user_role(v_app.org_id) <> 'director' then\n    perform app.fail('Una solicitud no puede ser aprobada por quien la emitió (separación de funciones)');\n  end if;\n  if not p_approve and coalesce(length(trim(p_note)), 0) < 5 then\n    perform app.fail('Indique el motivo del rechazo');\n  end if;\n\n  update public.approvals\n     set status = case when p_approve then 'aprobada' else 'rechazada' end,\n         decided_by = auth.uid(), decided_at = now(), decision_note = p_note\n   where id = p_approval_id;\n\n  case v_app.kind\n    when 'descuento', 'precio_bajo_minimo' then\n      update public.deals set status = case when p_approve then 'aprobada' else 'borrador' end\n       where id = v_app.entity_id and status = 'pendiente_aprobacion';\n      if not found then perform app.fail('La operación ya no está pendiente de aprobación'); end if;\n\n    when 'recargo' then\n      if p_approve then\n        select * into v_ctr from public.contracts where id = v_app.entity_id for update;\n        perform app.insert_schedule(v_ctr.org_id, v_ctr.id, null, v_ctr.currency, app.org_today(v_ctr.org_id),\n          jsonb_build_array(jsonb_build_object('kind', 'recargo', 'due_date', v_app.payload->>'due_date',\n                                               'principal', 0, 'interest', 0, 'fee', v_app.amount,\n                                               'description', coalesce(v_app.payload->>'description', 'Recargo autorizado'))));\n        select id into v_inst from public.installments where contract_id = v_ctr.id order by seq desc limit 1;\n        update public.installments set approval_id = v_app.id where id = v_inst;\n        for v_pay in select id from public.customer_payments where contract_id = v_ctr.id and status = 'confirmado' loop\n          perform app.allocate_payment(v_pay);\n        end loop;\n        perform app.refresh_contract_status(v_ctr.id);\n      end if;\n\n    when 'nota_credito' then\n      if p_approve then\n        select * into v_ctr from public.contracts where id = v_app.entity_id for update;\n        insert into public.customer_payments (org_id, customer_id, contract_id, received_on, method, currency, amount,\n                                              contract_currency, fx_rate_to_contract, amount_contract, notes, status,\n                                              approval_id, registered_by, confirmed_by, confirmed_at)\n        values (v_ctr.org_id, v_ctr.customer_id, v_ctr.id, app.org_today(v_ctr.org_id), 'nota_credito', v_ctr.currency,\n                v_app.amount, v_ctr.currency, 1, v_app.amount, v_app.payload->>'description', 'confirmado',\n                v_app.id, v_app.requested_by, auth.uid(), now())\n        returning id into v_pay;\n        perform app.ledger(v_ctr.org_id, v_ctr.id, app.org_today(v_ctr.org_id), 'nota_credito',\n                           coalesce(v_app.payload->>'description', 'Nota de crédito autorizada'), 0, v_app.amount,\n                           null, v_pay, v_app.id);\n        perform app.allocate_payment(v_pay);\n        perform app.refresh_contract_status(v_ctr.id);\n      end if;\n\n    when 'refinanciacion' then\n      if p_approve then perform app.apply_refinance(v_app); end if;\n\n    when 'tasacion' then\n      update public.trade_in_appraisals set status = case when p_approve then 'aprobada' else 'rechazada' end\n       where id = v_app.entity_id and status = 'en_revision';\n\n    when 'factura_proveedor' then\n      update public.supplier_invoices set status = case when p_approve then 'aprobada' else 'rechazada' end\n       where id = v_app.entity_id and status = 'pendiente_aprobacion';\n      if p_approve and coalesce((v_app.payload->>'create_vehicle_cost')::boolean, false) then\n        insert into public.vehicle_costs (org_id, vehicle_id, kind, description, amount, currency, fx_rate_to_base,\n                                          incurred_on, supplier_id, supplier_invoice_id, created_by, amount_base)\n        select si.org_id, si.vehicle_id, coalesce(v_app.payload->>'cost_kind', 'otro'), si.concept, si.amount, si.currency,\n               coalesce(app.fx_rate(si.org_id, si.currency, o.base_currency, si.issue_date), 1),\n               si.issue_date, si.supplier_id, si.id, si.created_by, 0\n        from public.supplier_invoices si join public.organizations o on o.id = si.org_id\n        where si.id = v_app.entity_id and si.vehicle_id is not null;\n      end if;\n\n    when 'gasto' then\n      update public.expenses set status = case when p_approve then 'aprobado' else 'rechazado' end\n       where id = v_app.entity_id and status = 'pendiente_aprobacion';\n    else\n      perform app.fail('Tipo de aprobación no soportado');\n  end case;\n\n  perform app.audit(v_app.org_id, case when p_approve then 'aprobacion_aprobada' else 'aprobacion_rechazada' end,\n                    'approvals', p_approval_id::text, v_app.title || coalesce(' — ' || p_note, ''));\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Trade-in\n-- -----------------------------------------------------------------------------\ncreate or replace function public.rpc_tradein_submit(p_appraisal_id uuid)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v public.trade_in_appraisals%rowtype;\n  v_id uuid;\nbegin\n  select * into v from public.trade_in_appraisals where id = p_appraisal_id for update;\n  if not found then perform app.fail('La tasación no existe'); end if;\n  perform app.require_perm(v.org_id, 'tradein.create');\n  if v.status not in ('borrador','rechazada') then perform app.fail('La tasación ya fue enviada'); end if;\n  if v.offered_value is null or v.expected_resale_price is null then\n    perform app.fail('Complete el valor ofrecido y el precio de reventa esperado');\n  end if;\n  if v.market_value_estimate is null then\n    perform app.fail('Registre el valor de mercado estimado con su fuente y fecha');\n  end if;\n  if not exists (select 1 from public.appraisal_inspections where appraisal_id = v.id) then\n    perform app.fail('Registre al menos una inspección (mecánica, carrocería, neumáticos…)');\n  end if;\n  update public.trade_in_appraisals set status = 'en_revision' where id = v.id;\n  insert into public.approvals (org_id, kind, entity_type, entity_id, title, reason, amount, currency, payload, requested_by)\n  values (v.org_id, 'tasacion', 'trade_in', v.id,\n          format('Tasación %s — %s %s %s', v.number, v.brand_name, v.model, v.year_model),\n          'Revisión de tasación de vehículo usado', v.offered_value, v.currency,\n          jsonb_build_object('expected_resale_price', v.expected_resale_price,\n                             'estimated_repair_costs', v.estimated_repair_costs,\n                             'market_value_estimate', v.market_value_estimate,\n                             'market_value_source', v.market_value_source),\n          auth.uid())\n  returning id into v_id;\n  update public.trade_in_appraisals set approval_id = v_id where id = v.id;\n  return v_id;\nend $$;\n\ncreate or replace function public.rpc_tradein_customer_decision(p_appraisal_id uuid, p_accepted boolean, p_accepted_value numeric default null)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v public.trade_in_appraisals%rowtype;\nbegin\n  select * into v from public.trade_in_appraisals where id = p_appraisal_id for update;\n  if not found then perform app.fail('La tasación no existe'); end if;\n  perform app.require_perm(v.org_id, 'tradein.create');\n  if v.status <> 'aprobada' then perform app.fail('La tasación debe estar aprobada'); end if;\n  if p_accepted then\n    if p_accepted_value is null or p_accepted_value <= 0 or p_accepted_value > v.offered_value\n       or not app.money_ok(p_accepted_value, v.currency) then\n      perform app.fail('El valor aceptado debe ser positivo y no superar el valor ofrecido aprobado');\n    end if;\n    update public.trade_in_appraisals set status = 'aceptada_cliente', accepted_value = p_accepted_value where id = v.id;\n  else\n    update public.trade_in_appraisals set status = 'anulada' where id = v.id;\n  end if;\nend $$;\n\n-- Formaliza la adquisición del usado e ingresa la unidad al inventario.\n-- p_vehicle: {brand_id, model, version, year_manufacture, year_model, vin, plate, mileage_km, fuel,\n--             transmission, color, location, list_price, min_price, price_currency, branch_id, category_id}\ncreate or replace function public.rpc_tradein_acquire(p_appraisal_id uuid, p_vehicle jsonb, p_acquired_on date)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v      public.trade_in_appraisals%rowtype;\n  v_veh  uuid;\n  v_base char(3);\n  v_fx   numeric;\nbegin\n  select * into v from public.trade_in_appraisals where id = p_appraisal_id for update;\n  if not found then perform app.fail('La tasación no existe'); end if;\n  perform app.require_perm(v.org_id, 'tradein.acquire');\n  if v.status <> 'aceptada_cliente' then perform app.fail('El cliente debe haber aceptado la tasación'); end if;\n  select base_currency into v_base from public.organizations where id = v.org_id;\n  v_fx := app.fx_rate(v.org_id, v.currency, v_base, p_acquired_on);\n  if v_fx is null then perform app.fail(format('Registre el tipo de cambio %s→%s', v.currency, v_base)); end if;\n\n  insert into public.vehicles (org_id, branch_id, brand_id, category_id, model, version, year_manufacture, year_model, vin,\n                               plate, mileage_km, fuel, transmission, color, condition, origin, location,\n                               acquisition_date, price_currency, list_price, min_price, physical_status,\n                               prep_status, doc_status, created_by, responsible_id)\n  values (v.org_id, (p_vehicle->>'branch_id')::uuid, (p_vehicle->>'brand_id')::uuid, (p_vehicle->>'category_id')::uuid,\n          coalesce(p_vehicle->>'model', v.model), coalesce(p_vehicle->>'version', v.version),\n          coalesce((p_vehicle->>'year_manufacture')::smallint, v.year_model),\n          coalesce((p_vehicle->>'year_model')::smallint, v.year_model),\n          coalesce(p_vehicle->>'vin', v.vin), coalesce(p_vehicle->>'plate', v.plate),\n          coalesce((p_vehicle->>'mileage_km')::integer, v.mileage_km),\n          coalesce(p_vehicle->>'fuel', v.fuel, 'nafta'), coalesce(p_vehicle->>'transmission', v.transmission, 'manual'),\n          coalesce(p_vehicle->>'color', v.color), 'usado', 'trade_in', p_vehicle->>'location', p_acquired_on,\n          coalesce(p_vehicle->>'price_currency', v.currency), (p_vehicle->>'list_price')::numeric,\n          (p_vehicle->>'min_price')::numeric, 'recibido', 'pendiente',\n          case v.doc_status when 'completa' then 'completa' else 'en_tramite' end, auth.uid(), auth.uid())\n  returning id into v_veh;\n\n  insert into public.vehicle_costs (org_id, vehicle_id, kind, description, amount, currency, fx_rate_to_base,\n                                    incurred_on, created_by, amount_base)\n  values (v.org_id, v_veh, 'adquisicion', 'Valor de aceptación trade-in ' || v.number, v.accepted_value, v.currency,\n          v_fx, p_acquired_on, auth.uid(), 0);\n  if v.estimated_repair_costs > 0 then\n    insert into public.vehicle_costs (org_id, vehicle_id, kind, description, amount, currency, fx_rate_to_base,\n                                      incurred_on, is_estimate, created_by, amount_base)\n    values (v.org_id, v_veh, 'reparacion', 'Reparaciones estimadas en tasación ' || v.number, v.estimated_repair_costs,\n            v.currency, v_fx, p_acquired_on, true, auth.uid(), 0);\n  end if;\n\n  update public.trade_in_appraisals set status = 'adquirida', vehicle_id = v_veh where id = v.id;\n  perform app.audit(v.org_id, 'tradein_adquirido', 'trade_in_appraisals', v.id::text,\n                    'Usado ingresado al inventario');\n  return v_veh;\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Proveedores\n-- -----------------------------------------------------------------------------\n-- p: {supplier_id, invoice_number, timbrado?, issue_date, due_date, currency, amount, tax_amount?, concept, category,\n--     vehicle_id?, create_vehicle_cost?, cost_kind?}\ncreate or replace function public.rpc_supplier_invoice_create(p jsonb)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_org uuid;\n  v_id  uuid;\n  v_name text;\nbegin\n  select org_id, name into v_org, v_name from public.suppliers where id = (p->>'supplier_id')::uuid;\n  if v_org is null then perform app.fail('El proveedor no existe'); end if;\n  perform app.require_perm(v_org, 'payables.create');\n  insert into public.supplier_invoices (org_id, supplier_id, invoice_number, timbrado, issue_date, due_date, currency,\n                                        amount, tax_amount, concept, category, vehicle_id, created_by)\n  values (v_org, (p->>'supplier_id')::uuid, p->>'invoice_number', nullif(p->>'timbrado', ''),\n          (p->>'issue_date')::date, (p->>'due_date')::date, p->>'currency', (p->>'amount')::numeric,\n          coalesce((p->>'tax_amount')::numeric, 0), p->>'concept', p->>'category', (p->>'vehicle_id')::uuid, auth.uid())\n  returning id into v_id;\n  insert into public.approvals (org_id, kind, entity_type, entity_id, title, reason, amount, currency, payload, requested_by)\n  values (v_org, 'factura_proveedor', 'supplier_invoice', v_id,\n          format('Factura %s — %s', p->>'invoice_number', v_name), p->>'concept',\n          (p->>'amount')::numeric, p->>'currency',\n          jsonb_build_object('create_vehicle_cost', coalesce((p->>'create_vehicle_cost')::boolean, false),\n                             'cost_kind', p->>'cost_kind'),\n          auth.uid());\n  update public.supplier_invoices set approval_id = (select id from public.approvals where entity_id = v_id and status = 'pendiente')\n   where id = v_id;\n  return v_id;\nend $$;\n\ncreate or replace function public.rpc_supplier_payment_register(p jsonb)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_inv public.v_supplier_invoice_balances%rowtype;\n  v_pending numeric;\n  v_id uuid;\nbegin\n  select * into v_inv from public.v_supplier_invoice_balances where id = (p->>'invoice_id')::uuid;\n  if v_inv.id is null then perform app.fail('La factura no existe'); end if;\n  perform app.require_perm(v_inv.org_id, 'payables.pay');\n  perform 1 from public.supplier_invoices where id = v_inv.id for update;\n  if v_inv.status <> 'aprobada' then perform app.fail('Sólo se pagan facturas aprobadas'); end if;\n  if (p->>'amount')::numeric > v_inv.outstanding - v_inv.paid_registered_pending then\n    perform app.fail(format('El pago supera el saldo pendiente de la factura (%s)', app.fmt_money(v_inv.outstanding - v_inv.paid_registered_pending, v_inv.currency)));\n  end if;\n  if not exists (select 1 from public.cash_accounts where id = (p->>'cash_account_id')::uuid and org_id = v_inv.org_id\n                 and is_active and currency = v_inv.currency) then\n    perform app.fail('Seleccione una cuenta activa en la moneda de la factura');\n  end if;\n  insert into public.supplier_payments (org_id, supplier_id, invoice_id, paid_on, amount, currency, cash_account_id,\n                                        reference, created_by)\n  values (v_inv.org_id, v_inv.supplier_id, v_inv.id, (p->>'paid_on')::date, (p->>'amount')::numeric, v_inv.currency,\n          (p->>'cash_account_id')::uuid, nullif(p->>'reference', ''), auth.uid())\n  returning id into v_id;\n  return v_id;\nend $$;\n\ncreate or replace function public.rpc_supplier_payment_confirm(p_payment_id uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v public.supplier_payments%rowtype;\n  v_name text;\n  v_inv text;\n  v_cm uuid;\nbegin\n  select * into v from public.supplier_payments where id = p_payment_id for update;\n  if not found then perform app.fail('El pago no existe'); end if;\n  perform app.require_perm(v.org_id, 'payables.pay');\n  if v.status <> 'registrado' then perform app.fail('Sólo se confirman pagos registrados'); end if;\n  select s.name, si.invoice_number into v_name, v_inv\n  from public.suppliers s join public.supplier_invoices si on si.id = v.invoice_id where s.id = v.supplier_id;\n  insert into public.cash_movements (org_id, account_id, occurred_on, direction, kind, amount, currency, description,\n                                     reference, counterparty, supplier_payment_id, created_by)\n  values (v.org_id, v.cash_account_id, v.paid_on, 'egreso', 'pago_proveedor', v.amount, v.currency,\n          'Pago factura ' || v_inv, v.reference, v_name, v.id, auth.uid())\n  returning id into v_cm;\n  update public.supplier_payments set status = 'confirmado', confirmed_by = auth.uid(), confirmed_at = now(),\n         cash_movement_id = v_cm where id = p_payment_id;\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Gastos generales\n-- -----------------------------------------------------------------------------\n-- p: {expense_date, category, description, amount, currency, supplier_id?}\ncreate or replace function public.rpc_expense_create(p_org uuid, p jsonb)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_id uuid;\nbegin\n  perform app.require_perm(p_org, 'expenses.create');\n  insert into public.expenses (org_id, expense_date, category, description, amount, currency, supplier_id, created_by)\n  values (p_org, (p->>'expense_date')::date, p->>'category', p->>'description', (p->>'amount')::numeric,\n          p->>'currency', (p->>'supplier_id')::uuid, auth.uid())\n  returning id into v_id;\n  insert into public.approvals (org_id, kind, entity_type, entity_id, title, reason, amount, currency, requested_by)\n  values (p_org, 'gasto', 'expense', v_id, 'Gasto: ' || (p->>'description'), p->>'category',\n          (p->>'amount')::numeric, p->>'currency', auth.uid());\n  update public.expenses set approval_id = (select id from public.approvals where entity_id = v_id and status = 'pendiente')\n   where id = v_id;\n  return v_id;\nend $$;\n\ncreate or replace function public.rpc_expense_pay(p_expense_id uuid, p_cash_account_id uuid, p_paid_on date, p_reference text default null)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v public.expenses%rowtype;\n  v_cm uuid;\nbegin\n  select * into v from public.expenses where id = p_expense_id for update;\n  if not found then perform app.fail('El gasto no existe'); end if;\n  perform app.require_perm(v.org_id, 'cash.register');\n  if v.status <> 'aprobado' then perform app.fail('Sólo se pagan gastos aprobados'); end if;\n  if not exists (select 1 from public.cash_accounts where id = p_cash_account_id and org_id = v.org_id\n                 and is_active and currency = v.currency) then\n    perform app.fail('Seleccione una cuenta activa en la moneda del gasto');\n  end if;\n  insert into public.cash_movements (org_id, account_id, occurred_on, direction, kind, amount, currency, description,\n                                     reference, expense_id, created_by)\n  values (v.org_id, p_cash_account_id, p_paid_on, 'egreso', 'gasto', v.amount, v.currency,\n          'Gasto ' || v.number || ': ' || v.description, p_reference, v.id, auth.uid())\n  returning id into v_cm;\n  update public.expenses set status = 'pagado', cash_account_id = p_cash_account_id, cash_movement_id = v_cm\n   where id = p_expense_id;\n  return v_cm;\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Caja: movimientos manuales, reversión y conciliación\n-- -----------------------------------------------------------------------------\n-- p: {account_id, occurred_on, direction, kind (apertura|ajuste|otro), amount, description, reference?, counterparty?}\ncreate or replace function public.rpc_cash_movement_create(p jsonb)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_acc public.cash_accounts%rowtype;\n  v_id  uuid;\nbegin\n  select * into v_acc from public.cash_accounts where id = (p->>'account_id')::uuid;\n  if not found then perform app.fail('La cuenta no existe'); end if;\n  perform app.require_perm(v_acc.org_id, 'cash.register');\n  if (p->>'kind') not in ('apertura','ajuste','otro') then\n    perform app.fail('Los cobros, pagos y gastos se registran desde su módulo');\n  end if;\n  if coalesce(length(trim(p->>'description')), 0) < 3 then perform app.fail('Describa el movimiento'); end if;\n  insert into public.cash_movements (org_id, account_id, occurred_on, direction, kind, amount, currency, description,\n                                     reference, counterparty, created_by)\n  values (v_acc.org_id, v_acc.id, (p->>'occurred_on')::date, p->>'direction', p->>'kind', (p->>'amount')::numeric,\n          v_acc.currency, p->>'description', nullif(p->>'reference', ''), nullif(p->>'counterparty', ''), auth.uid())\n  returning id into v_id;\n  return v_id;\nend $$;\n\n-- Transferencia entre cuentas de la misma moneda (dos movimientos enlazados por referencia).\ncreate or replace function public.rpc_cash_transfer(p_from uuid, p_to uuid, p_amount numeric, p_date date, p_description text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  a public.cash_accounts%rowtype;\n  b public.cash_accounts%rowtype;\n  v_ref text := 'TRF-' || substr(gen_random_uuid()::text, 1, 8);\nbegin\n  select * into a from public.cash_accounts where id = p_from;\n  select * into b from public.cash_accounts where id = p_to;\n  if a.id is null or b.id is null or a.org_id <> b.org_id then perform app.fail('Cuentas inválidas'); end if;\n  perform app.require_perm(a.org_id, 'cash.register');\n  if a.id = b.id then perform app.fail('Seleccione dos cuentas distintas'); end if;\n  if a.currency <> b.currency then perform app.fail('Las transferencias entre monedas requieren un cambio de divisas registrado como dos movimientos'); end if;\n  insert into public.cash_movements (org_id, account_id, occurred_on, direction, kind, amount, currency, description, reference, created_by)\n  values (a.org_id, a.id, p_date, 'egreso', 'transferencia', p_amount, a.currency, p_description || ' → ' || b.name, v_ref, auth.uid()),\n         (a.org_id, b.id, p_date, 'ingreso', 'transferencia', p_amount, b.currency, p_description || ' ← ' || a.name, v_ref, auth.uid());\nend $$;\n\ncreate or replace function public.rpc_cash_movement_reverse(p_movement_id uuid, p_reason text)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v public.cash_movements%rowtype;\n  v_id uuid;\nbegin\n  select * into v from public.cash_movements where id = p_movement_id for update;\n  if not found then perform app.fail('El movimiento no existe'); end if;\n  perform app.require_perm(v.org_id, 'cash.reverse');\n  if v.kind in ('cobro_cliente','pago_proveedor','gasto') then\n    perform app.fail('Este movimiento se revierte desde su origen (pago de cliente, pago a proveedor o gasto)');\n  end if;\n  if v.reverses_id is not null then perform app.fail('No se revierte una reversión'); end if;\n  if exists (select 1 from public.cash_movements where reverses_id = v.id) then\n    perform app.fail('El movimiento ya fue revertido');\n  end if;\n  if coalesce(length(trim(p_reason)), 0) < 5 then perform app.fail('Indique el motivo'); end if;\n  insert into public.cash_movements (org_id, account_id, occurred_on, direction, kind, amount, currency, description,\n                                     reference, counterparty, reverses_id, created_by)\n  values (v.org_id, v.account_id, app.org_today(v.org_id),\n          case v.direction when 'ingreso' then 'egreso' else 'ingreso' end, 'reversion', v.amount, v.currency,\n          'Reversión: ' || p_reason, v.reference, v.counterparty, v.id, auth.uid())\n  returning id into v_id;\n  perform app.audit(v.org_id, 'movimiento_revertido', 'cash_movements', v.id::text, p_reason);\n  return v_id;\nend $$;\n\n-- Conciliación manual contra un extracto: marca los movimientos verificados y\n-- registra la diferencia entre el saldo del extracto y el saldo del sistema.\ncreate or replace function public.rpc_reconciliation_create(\n  p_account_id uuid, p_period_end date, p_statement_balance numeric, p_movement_ids uuid[], p_notes text default null)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_acc  public.cash_accounts%rowtype;\n  v_sys  numeric;\n  v_id   uuid;\n  v_bad  integer;\nbegin\n  select * into v_acc from public.cash_accounts where id = p_account_id;\n  if not found then perform app.fail('La cuenta no existe'); end if;\n  perform app.require_perm(v_acc.org_id, 'cash.reconcile');\n  select count(*) into v_bad from unnest(coalesce(p_movement_ids, '{}')) mid\n  where not exists (select 1 from public.cash_movements m where m.id = mid and m.account_id = p_account_id\n                    and m.status = 'registrado' and m.occurred_on <= p_period_end);\n  if v_bad > 0 then perform app.fail('Hay movimientos no válidos para esta conciliación'); end if;\n\n  select coalesce(sum(case when direction = 'ingreso' then amount else -amount end), 0) into v_sys\n  from public.cash_movements where account_id = p_account_id and occurred_on <= p_period_end;\n\n  insert into public.reconciliations (org_id, account_id, period_end, statement_balance, system_balance, status,\n                                      notes, created_by, closed_by, closed_at)\n  values (v_acc.org_id, p_account_id, p_period_end, p_statement_balance, v_sys,\n          case when p_statement_balance = v_sys then 'cerrada' else 'abierta' end, p_notes, auth.uid(),\n          case when p_statement_balance = v_sys then auth.uid() end,\n          case when p_statement_balance = v_sys then now() end)\n  returning id into v_id;\n\n  update public.cash_movements set status = 'conciliado', reconciliation_id = v_id\n   where id = any(coalesce(p_movement_ids, '{}'));\n  perform app.audit(v_acc.org_id, 'conciliacion', 'reconciliations', v_id::text,\n                    format('Extracto %s vs sistema %s', app.fmt_money(p_statement_balance, v_acc.currency), app.fmt_money(v_sys, v_acc.currency)));\n  return v_id;\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Clientes: detección de duplicados (devuelve sólo datos mínimos)\n-- -----------------------------------------------------------------------------\ncreate or replace function public.rpc_customer_duplicates(\n  p_org uuid, p_doc_type text, p_doc_number text, p_phone text, p_email text, p_exclude uuid default null)\nreturns table (id uuid, full_name text, match_on text, seller_name text, visible boolean)\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  if not (app.has_perm(p_org, 'customers.create') or app.has_perm(p_org, 'customers.edit')) then\n    raise exception 'Sin permiso' using errcode = '42501';\n  end if;\n  return query\n  select c.id, c.full_name,\n         case\n           when c.doc_type = p_doc_type and c.doc_normalized = app.normalize_doc(p_doc_number) then 'documento'\n           when app.normalize_phone(p_phone) is not null and c.phone_normalized = app.normalize_phone(p_phone) then 'teléfono'\n           else 'correo'\n         end,\n         u.full_name,\n         app.can_see_customer(c.org_id, c.assigned_seller_id, c.created_by)\n  from public.customers c\n  left join public.user_profiles u on u.id = c.assigned_seller_id\n  where c.org_id = p_org\n    and (p_exclude is null or c.id <> p_exclude)\n    and ((c.doc_type = p_doc_type and c.doc_normalized = app.normalize_doc(p_doc_number))\n      or (app.normalize_phone(p_phone) is not null and c.phone_normalized = app.normalize_phone(p_phone))\n      or (nullif(lower(trim(p_email)), '') is not null and c.email_normalized = lower(trim(p_email))))\n  limit 5;\nend $$;\n\n-- -----------------------------------------------------------------------------\n-- Verificación de consistencia de un contrato\n-- -----------------------------------------------------------------------------\ncreate or replace function public.rpc_contract_consistency(p_contract_id uuid)\nreturns table (ledger_balance numeric, installments_outstanding numeric, unapplied_credit numeric, consistent boolean)\nlanguage sql stable\nsecurity invoker\nset search_path = public, pg_temp\nas $$\n  select b.ledger_balance, b.outstanding, b.unapplied_credit,\n         b.ledger_balance = b.outstanding - b.unapplied_credit\n  from public.v_contract_balances b where b.contract_id = p_contract_id\n$$;\n"},{"name":"20261022000800_rls.sql","sql":"-- =============================================================================\n-- Da Silva OS — Row Level Security y privilegios\n--\n-- Defensa en profundidad:\n--   1. El servidor verifica permisos antes de cada acción.\n--   2. Las RPC verifican permisos de nuevo (app.require_perm).\n--   3. RLS impide leer o escribir filas sin permiso aunque se acceda\n--      directamente a la API de datos de Supabase con el JWT del usuario.\n--   4. anon no tiene ningún privilegio.\n-- =============================================================================\n\n-- Privilegios base ------------------------------------------------------------\nrevoke all on all tables in schema public from anon;\nrevoke all on all functions in schema public from anon, public;\nrevoke all on all functions in schema app from public;\n\ngrant usage on schema public to authenticated, service_role;\ngrant usage on schema app to authenticated, service_role;\ngrant select, insert, update, delete on all tables in schema public to authenticated;\ngrant all on all tables in schema public to service_role;\ngrant usage, select on all sequences in schema public to authenticated, service_role;\ngrant execute on all functions in schema app to authenticated, service_role;\ngrant execute on all functions in schema public to authenticated, service_role;\n\n-- Las tablas append-only no admiten UPDATE/DELETE ni siquiera con RLS.\nrevoke update, delete on public.audit_events, public.vehicle_status_events, public.deal_events,\n  public.contract_ledger_entries, public.payment_allocations, public.payment_reversals,\n  public.collection_actions, public.contract_versions, public.proposals,\n  public.opportunity_stage_events from authenticated;\n-- Tablas que sólo escriben las funciones transaccionales.\nrevoke insert, update, delete on public.contracts, public.financing_plans, public.installments,\n  public.customer_payments, public.payment_allocations, public.payment_reversals, public.contract_ledger_entries,\n  public.cash_movements, public.reconciliations, public.reservations, public.approvals,\n  public.supplier_payments, public.contract_versions, public.document_sequences, public.audit_events,\n  public.vehicle_status_events, public.deal_events, public.opportunity_stage_events\n  from authenticated;\nrevoke delete on all tables in schema public from authenticated;\ngrant delete on public.vehicle_photos, public.appraisal_inspections, public.documents to authenticated;\n\n-- Habilitar RLS en todas las tablas ------------------------------------------\ndo $$\ndeclare t text;\nbegin\n  for t in select tablename from pg_tables where schemaname = 'public' loop\n    execute format('alter table public.%I enable row level security', t);\n  end loop;\nend $$;\n\n-- Catálogos globales (lectura para usuarios autenticados) ----------------------\ncreate policy currencies_read on public.currencies for select to authenticated using (true);\ncreate policy roles_read on public.roles for select to authenticated using (true);\ncreate policy permissions_read on public.permissions for select to authenticated using (true);\ncreate policy role_permissions_read on public.role_permissions for select to authenticated using (true);\n\n-- Organización y usuarios ------------------------------------------------------\ncreate policy organizations_read on public.organizations for select to authenticated using (app.is_member(id));\ncreate policy organizations_update on public.organizations for update to authenticated\n  using (app.has_perm(id, 'settings.manage')) with check (app.has_perm(id, 'settings.manage'));\n\ncreate policy branches_read on public.branches for select to authenticated using (app.is_member(org_id));\ncreate policy branches_write on public.branches for insert to authenticated with check (app.has_perm(org_id, 'settings.manage'));\ncreate policy branches_update on public.branches for update to authenticated\n  using (app.has_perm(org_id, 'settings.manage')) with check (app.has_perm(org_id, 'settings.manage'));\n\ncreate or replace function app.shares_org(p_user uuid)\nreturns boolean\nlanguage sql stable security definer\nset search_path = public, pg_temp\nas $$\n  select exists (\n    select 1 from public.memberships a\n    join public.memberships b on b.org_id = a.org_id\n    where a.user_id = auth.uid() and a.is_active and b.user_id = p_user\n  )\n$$;\n\ncreate policy user_profiles_read on public.user_profiles for select to authenticated\n  using (id = auth.uid() or app.shares_org(id));\ncreate policy user_profiles_update_self on public.user_profiles for update to authenticated\n  using (id = auth.uid()) with check (id = auth.uid());\n\ncreate policy memberships_read on public.memberships for select to authenticated using (app.is_member(org_id));\ncreate policy memberships_insert on public.memberships for insert to authenticated with check (app.has_perm(org_id, 'users.manage'));\ncreate policy memberships_update on public.memberships for update to authenticated\n  using (app.has_perm(org_id, 'users.manage')) with check (app.has_perm(org_id, 'users.manage'));\n\n-- Un usuario no puede cambiarse su propio rol ni desactivarse a sí mismo.\ncreate or replace function app.memberships_guard()\nreturns trigger language plpgsql as $$\nbegin\n  if not app.is_trusted() and new.user_id = auth.uid() and\n     (new.role is distinct from old.role or new.is_active is distinct from old.is_active) then\n    raise exception 'No puede modificar su propio rol o estado' using errcode = '42501';\n  end if;\n  return new;\nend $$;\ncreate trigger memberships_guard before update on public.memberships\n  for each row execute function app.memberships_guard();\n\ncreate policy audit_read on public.audit_events for select to authenticated using (app.has_perm(org_id, 'audit.view'));\n\ncreate policy exchange_rates_read on public.exchange_rates for select to authenticated using (app.is_member(org_id));\ncreate policy exchange_rates_insert on public.exchange_rates for insert to authenticated\n  with check (app.has_perm(org_id, 'settings.manage') or app.has_perm(org_id, 'cash.reconcile'));\n\ncreate policy org_settings_read on public.org_settings for select to authenticated using (app.is_member(org_id));\ncreate policy org_settings_update on public.org_settings for update to authenticated\n  using (app.has_perm(org_id, 'settings.manage')) with check (app.has_perm(org_id, 'settings.manage'));\n\ncreate policy aging_buckets_read on public.aging_buckets for select to authenticated using (app.is_member(org_id));\ncreate policy aging_buckets_write on public.aging_buckets for update to authenticated\n  using (app.has_perm(org_id, 'settings.manage')) with check (app.has_perm(org_id, 'settings.manage'));\n\ncreate policy document_sequences_none on public.document_sequences for select to authenticated using (false);\n\n-- Inventario -------------------------------------------------------------------\ncreate policy brands_read on public.brands for select to authenticated using (app.is_member(org_id));\ncreate policy brands_insert on public.brands for insert to authenticated with check (app.has_perm(org_id, 'settings.manage'));\ncreate policy brands_update on public.brands for update to authenticated\n  using (app.has_perm(org_id, 'settings.manage')) with check (app.has_perm(org_id, 'settings.manage'));\n\ncreate policy categories_read on public.vehicle_categories for select to authenticated using (app.is_member(org_id));\ncreate policy categories_insert on public.vehicle_categories for insert to authenticated with check (app.has_perm(org_id, 'settings.manage'));\n\ncreate policy vehicles_read on public.vehicles for select to authenticated using (app.has_perm(org_id, 'inventory.view'));\n-- Cobranzas/finanzas ven las unidades vinculadas a contratos (no todo el inventario).\ncreate policy vehicles_read_contracted on public.vehicles for select to authenticated\n  using ((app.has_perm(org_id, 'contracts.view') or app.has_perm(org_id, 'collections.view'))\n         and exists (select 1 from public.contracts k where k.vehicle_id = vehicles.id));\ncreate policy vehicles_insert on public.vehicles for insert to authenticated\n  with check (app.has_perm(org_id, 'inventory.create') and commercial_status = 'disponible' and contract_status = 'sin_contrato');\ncreate policy vehicles_update on public.vehicles for update to authenticated\n  using (app.has_perm(org_id, 'inventory.edit') or app.has_perm(org_id, 'inventory.pricing.edit'))\n  with check (app.has_perm(org_id, 'inventory.edit') or app.has_perm(org_id, 'inventory.pricing.edit'));\n\ncreate policy vehicle_status_events_read on public.vehicle_status_events for select to authenticated\n  using (app.has_perm(org_id, 'inventory.view'));\n\ncreate policy vehicle_costs_read on public.vehicle_costs for select to authenticated\n  using (app.has_perm(org_id, 'inventory.costs.view'));\ncreate policy vehicle_costs_insert on public.vehicle_costs for insert to authenticated\n  with check (app.has_perm(org_id, 'inventory.costs.create'));\ncreate policy vehicle_costs_update on public.vehicle_costs for update to authenticated\n  using (app.has_perm(org_id, 'inventory.costs.edit_history')) with check (app.has_perm(org_id, 'inventory.costs.edit_history'));\n\ncreate policy document_types_read on public.document_types for select to authenticated using (app.is_member(org_id));\ncreate policy document_types_write on public.document_types for insert to authenticated with check (app.has_perm(org_id, 'settings.manage'));\n\n-- Lectura de documentos: según el módulo de la entidad; restringidos requieren permiso extra.\ncreate or replace function app.can_read_entity(p_org uuid, p_entity_type text)\nreturns boolean language sql stable as $$\n  select case p_entity_type\n    when 'vehicle'          then app.has_perm(p_org, 'inventory.view')\n    when 'customer'         then app.has_perm(p_org, 'customers.view') or app.has_perm(p_org, 'customers.view_all')\n    when 'deal'             then app.has_perm(p_org, 'deals.view') or app.has_perm(p_org, 'deals.view_all')\n    when 'contract'         then app.has_perm(p_org, 'contracts.view')\n    when 'payment'          then app.has_perm(p_org, 'payments.view')\n    when 'supplier_invoice' then app.has_perm(p_org, 'payables.view')\n    when 'trade_in'         then app.has_perm(p_org, 'tradein.view')\n    when 'expense'          then app.has_perm(p_org, 'expenses.view')\n    when 'cash_movement'    then app.has_perm(p_org, 'cash.view')\n    else false end\n$$;\n\ncreate or replace function app.can_write_entity(p_org uuid, p_entity_type text)\nreturns boolean language sql stable as $$\n  select case p_entity_type\n    when 'vehicle'          then app.has_perm(p_org, 'inventory.edit') or app.has_perm(p_org, 'inventory.create')\n    when 'customer'         then app.has_perm(p_org, 'customers.edit')\n    when 'deal'             then app.has_perm(p_org, 'deals.create') or app.has_perm(p_org, 'deals.formalize')\n    when 'contract'         then app.has_perm(p_org, 'deals.formalize') or app.has_perm(p_org, 'contracts.adjust')\n    when 'payment'          then app.has_perm(p_org, 'payments.register')\n    when 'supplier_invoice' then app.has_perm(p_org, 'payables.create')\n    when 'trade_in'         then app.has_perm(p_org, 'tradein.create')\n    when 'expense'          then app.has_perm(p_org, 'expenses.create')\n    when 'cash_movement'    then app.has_perm(p_org, 'cash.register')\n    else false end\n$$;\n\ncreate policy documents_read on public.documents for select to authenticated\n  using (app.can_read_entity(org_id, entity_type)\n         and (not is_restricted or app.has_perm(org_id, 'documents.view_restricted')));\ncreate policy documents_insert on public.documents for insert to authenticated\n  with check (app.can_write_entity(org_id, entity_type) and uploaded_by = auth.uid());\ncreate policy documents_delete on public.documents for delete to authenticated\n  using (uploaded_by = auth.uid() and uploaded_at > now() - interval '1 hour' and app.can_write_entity(org_id, entity_type));\n\ncreate policy vehicle_documents_read on public.vehicle_documents for select to authenticated using (app.has_perm(org_id, 'inventory.view'));\ncreate policy vehicle_documents_insert on public.vehicle_documents for insert to authenticated with check (app.has_perm(org_id, 'inventory.edit'));\ncreate policy vehicle_documents_update on public.vehicle_documents for update to authenticated\n  using (app.has_perm(org_id, 'inventory.edit')) with check (app.has_perm(org_id, 'inventory.edit'));\n\ncreate policy vehicle_photos_read on public.vehicle_photos for select to authenticated using (app.has_perm(org_id, 'inventory.view'));\ncreate policy vehicle_photos_insert on public.vehicle_photos for insert to authenticated with check (app.has_perm(org_id, 'inventory.edit'));\ncreate policy vehicle_photos_update on public.vehicle_photos for update to authenticated\n  using (app.has_perm(org_id, 'inventory.edit')) with check (app.has_perm(org_id, 'inventory.edit'));\ncreate policy vehicle_photos_delete on public.vehicle_photos for delete to authenticated using (app.has_perm(org_id, 'inventory.edit'));\n\ncreate policy suppliers_read on public.suppliers for select to authenticated\n  using (app.has_perm(org_id, 'suppliers.view') or app.has_perm(org_id, 'inventory.costs.view'));\ncreate policy suppliers_insert on public.suppliers for insert to authenticated with check (app.has_perm(org_id, 'suppliers.manage'));\ncreate policy suppliers_update on public.suppliers for update to authenticated\n  using (app.has_perm(org_id, 'suppliers.manage')) with check (app.has_perm(org_id, 'suppliers.manage'));\n\n-- Clientes y CRM ---------------------------------------------------------------\ncreate policy customers_read on public.customers for select to authenticated\n  using (app.can_see_customer(org_id, assigned_seller_id, created_by));\ncreate policy customers_insert on public.customers for insert to authenticated\n  with check (app.has_perm(org_id, 'customers.create') and created_by = auth.uid());\ncreate policy customers_update on public.customers for update to authenticated\n  using (app.has_perm(org_id, 'customers.edit') and app.can_see_customer(org_id, assigned_seller_id, created_by))\n  with check (app.has_perm(org_id, 'customers.edit')\n              and (app.has_perm(org_id, 'customers.view_all') or assigned_seller_id = auth.uid() or assigned_seller_id is null));\n\n-- Sólo quien gestiona cobranzas reasigna el responsable de cobranza.\ncreate or replace function app.customers_guard()\nreturns trigger language plpgsql as $$\nbegin\n  if not app.is_trusted() and new.collector_id is distinct from old.collector_id\n     and not app.has_perm(new.org_id, 'collections.assign') then\n    raise exception 'No tiene permiso para asignar responsables de cobranza' using errcode = '42501';\n  end if;\n  return new;\nend $$;\ncreate trigger customers_guard before update on public.customers\n  for each row execute function app.customers_guard();\n\ncreate policy customer_interactions_read on public.customer_interactions for select to authenticated\n  using (exists (select 1 from public.customers c where c.id = customer_id));\ncreate policy customer_interactions_insert on public.customer_interactions for insert to authenticated\n  with check (user_id = auth.uid() and (app.has_perm(org_id, 'crm.manage') or app.has_perm(org_id, 'collections.manage'))\n              and exists (select 1 from public.customers c where c.id = customer_id));\n\ncreate policy leads_read on public.leads for select to authenticated\n  using (app.has_perm(org_id, 'customers.view_all') or (app.has_perm(org_id, 'crm.manage') and (assigned_to = auth.uid() or created_by = auth.uid() or assigned_to is null)));\ncreate policy leads_insert on public.leads for insert to authenticated with check (app.has_perm(org_id, 'crm.manage'));\ncreate policy leads_update on public.leads for update to authenticated\n  using (app.has_perm(org_id, 'crm.manage')) with check (app.has_perm(org_id, 'crm.manage'));\n\ncreate policy pipeline_stages_read on public.pipeline_stages for select to authenticated using (app.is_member(org_id));\ncreate policy pipeline_stages_update on public.pipeline_stages for update to authenticated\n  using (app.has_perm(org_id, 'settings.manage')) with check (app.has_perm(org_id, 'settings.manage'));\n\ncreate policy opportunities_read on public.opportunities for select to authenticated\n  using (app.has_perm(org_id, 'customers.view_all') or (app.has_perm(org_id, 'crm.manage') and seller_id = auth.uid()));\ncreate policy opportunities_insert on public.opportunities for insert to authenticated with check (app.has_perm(org_id, 'crm.manage'));\ncreate policy opportunities_update on public.opportunities for update to authenticated\n  using (app.has_perm(org_id, 'crm.manage') and (app.has_perm(org_id, 'customers.view_all') or seller_id = auth.uid()))\n  with check (app.has_perm(org_id, 'crm.manage'));\n\ncreate policy opportunity_stage_events_read on public.opportunity_stage_events for select to authenticated\n  using (exists (select 1 from public.opportunities o where o.id = opportunity_id));\n\n-- Aprobaciones: visibles para quien puede decidir su tipo o quien las solicitó.\ncreate policy approvals_read on public.approvals for select to authenticated\n  using (requested_by = auth.uid() or app.has_perm(org_id, app.approval_permission(kind)) or app.has_perm(org_id, 'audit.view'));\n\n-- Tasaciones -------------------------------------------------------------------\ncreate policy trade_in_read on public.trade_in_appraisals for select to authenticated using (app.has_perm(org_id, 'tradein.view'));\ncreate policy trade_in_insert on public.trade_in_appraisals for insert to authenticated\n  with check (app.has_perm(org_id, 'tradein.create') and status = 'borrador' and created_by = auth.uid());\ncreate policy trade_in_update on public.trade_in_appraisals for update to authenticated\n  using (app.has_perm(org_id, 'tradein.create') and status in ('borrador','rechazada'))\n  with check (status in ('borrador','rechazada'));\n\ncreate policy appraisal_inspections_read on public.appraisal_inspections for select to authenticated using (app.has_perm(org_id, 'tradein.view'));\ncreate policy appraisal_inspections_write on public.appraisal_inspections for insert to authenticated\n  with check (app.has_perm(org_id, 'tradein.create')\n              and exists (select 1 from public.trade_in_appraisals t where t.id = appraisal_id and t.status in ('borrador','rechazada')));\ncreate policy appraisal_inspections_update on public.appraisal_inspections for update to authenticated\n  using (app.has_perm(org_id, 'tradein.create')\n         and exists (select 1 from public.trade_in_appraisals t where t.id = appraisal_id and t.status in ('borrador','rechazada')))\n  with check (app.has_perm(org_id, 'tradein.create'));\ncreate policy appraisal_inspections_delete on public.appraisal_inspections for delete to authenticated\n  using (app.has_perm(org_id, 'tradein.create')\n         and exists (select 1 from public.trade_in_appraisals t where t.id = appraisal_id and t.status in ('borrador','rechazada')));\n\n-- Ventas -----------------------------------------------------------------------\ncreate policy deals_read on public.deals for select to authenticated using (app.can_see_deal(org_id, seller_id));\ncreate policy deals_insert on public.deals for insert to authenticated\n  with check (app.has_perm(org_id, 'deals.create') and status = 'borrador'\n              and (seller_id = auth.uid() or app.has_perm(org_id, 'deals.view_all')));\ncreate policy deals_update on public.deals for update to authenticated\n  using (app.has_perm(org_id, 'deals.create') and app.can_see_deal(org_id, seller_id))\n  with check (app.has_perm(org_id, 'deals.create') and (seller_id = auth.uid() or app.has_perm(org_id, 'deals.view_all')));\n\ncreate policy deal_events_read on public.deal_events for select to authenticated\n  using (exists (select 1 from public.deals d where d.id = deal_id));\n\ncreate policy reservations_read on public.reservations for select to authenticated\n  using (app.has_perm(org_id, 'inventory.view'));\n\ncreate policy proposals_read on public.proposals for select to authenticated\n  using (created_by = auth.uid() or app.has_perm(org_id, 'deals.view_all'));\ncreate policy proposals_insert on public.proposals for insert to authenticated\n  with check (app.has_perm(org_id, 'deals.create') and created_by = auth.uid());\ngrant insert on public.proposals to authenticated;\n\n-- Contratos, cuotas y cobros (sólo lectura directa) -----------------------------\ncreate policy contracts_read on public.contracts for select to authenticated\n  using (app.has_perm(org_id, 'contracts.view') or app.has_perm(org_id, 'collections.view'));\ncreate policy contract_versions_read on public.contract_versions for select to authenticated\n  using (app.has_perm(org_id, 'contracts.view'));\ncreate policy financing_plans_read on public.financing_plans for select to authenticated\n  using (app.has_perm(org_id, 'contracts.view'));\ncreate policy installments_read on public.installments for select to authenticated\n  using (app.has_perm(org_id, 'contracts.view') or app.has_perm(org_id, 'collections.view'));\ncreate policy customer_payments_read on public.customer_payments for select to authenticated\n  using (app.has_perm(org_id, 'payments.view'));\ncreate policy payment_allocations_read on public.payment_allocations for select to authenticated\n  using (app.has_perm(org_id, 'payments.view') or app.has_perm(org_id, 'collections.view'));\ncreate policy payment_reversals_read on public.payment_reversals for select to authenticated\n  using (app.has_perm(org_id, 'payments.view'));\ncreate policy contract_ledger_read on public.contract_ledger_entries for select to authenticated\n  using (app.has_perm(org_id, 'contracts.view') or app.has_perm(org_id, 'collections.view'));\n\ncreate policy collection_actions_read on public.collection_actions for select to authenticated\n  using (app.has_perm(org_id, 'collections.view'));\ncreate policy collection_actions_insert on public.collection_actions for insert to authenticated\n  with check (app.has_perm(org_id, 'collections.manage') and user_id = auth.uid());\ngrant insert on public.collection_actions to authenticated;\n\n-- Proveedores, gastos y caja ----------------------------------------------------\ncreate policy supplier_invoices_read on public.supplier_invoices for select to authenticated\n  using (app.has_perm(org_id, 'payables.view'));\ncreate policy supplier_payments_read on public.supplier_payments for select to authenticated\n  using (app.has_perm(org_id, 'payables.view'));\nrevoke insert, update on public.supplier_invoices from authenticated;\n\ncreate policy expenses_read on public.expenses for select to authenticated using (app.has_perm(org_id, 'expenses.view'));\nrevoke insert, update on public.expenses from authenticated;\n\ncreate policy cash_accounts_read on public.cash_accounts for select to authenticated\n  using (app.has_perm(org_id, 'cash.view') or app.has_perm(org_id, 'payments.register') or app.has_perm(org_id, 'payables.pay'));\ncreate policy cash_accounts_insert on public.cash_accounts for insert to authenticated\n  with check (app.has_perm(org_id, 'settings.manage') or app.has_perm(org_id, 'cash.reconcile'));\ncreate policy cash_accounts_update on public.cash_accounts for update to authenticated\n  using (app.has_perm(org_id, 'settings.manage') or app.has_perm(org_id, 'cash.reconcile'))\n  with check (app.has_perm(org_id, 'settings.manage') or app.has_perm(org_id, 'cash.reconcile'));\n\ncreate policy cash_movements_read on public.cash_movements for select to authenticated using (app.has_perm(org_id, 'cash.view'));\ncreate policy reconciliations_read on public.reconciliations for select to authenticated using (app.has_perm(org_id, 'cash.view'));\n\n-- Vistas: lectura (aplican el RLS de las tablas base por security_invoker) -------\ngrant select on public.v_installment_balances, public.v_contract_balances, public.v_payment_promises,\n  public.v_vehicle_economics, public.v_supplier_invoice_balances, public.v_cash_account_balances to authenticated;\nrevoke all on public.v_installment_balances, public.v_contract_balances, public.v_payment_promises,\n  public.v_vehicle_economics, public.v_supplier_invoice_balances, public.v_cash_account_balances from anon;\n"},{"name":"20261022000900_storage.sql","sql":"-- =============================================================================\n-- Da Silva OS — Supabase Storage privado\n--\n-- Buckets privados (sin URL pública). Convención de rutas:\n--   documents:       {org_id}/{entity_type}/{entity_id}/{uuid}-{archivo}\n--   vehicle-photos:  {org_id}/{vehicle_id}/{uuid}.{ext}\n-- La descarga se hace con URL firmadas de corta duración que genera el\n-- servidor tras verificar el acceso al registro en public.documents.\n-- En entornos sin Supabase Storage (desarrollo local) este bloque no hace nada.\n-- =============================================================================\ndo $$\nbegin\n  if not exists (select 1 from pg_namespace where nspname = 'storage') then\n    raise notice 'Esquema storage inexistente: se omite la configuración de buckets';\n    return;\n  end if;\n\n  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\n  values ('documents', 'documents', false, 26214400,\n          array['application/pdf','image/jpeg','image/png','image/webp'])\n  on conflict (id) do nothing;\n\n  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\n  values ('vehicle-photos', 'vehicle-photos', false, 10485760, array['image/jpeg','image/png','image/webp'])\n  on conflict (id) do nothing;\n\n  execute $p$\n    create policy dasilva_documents_read on storage.objects for select to authenticated\n    using (bucket_id = 'documents'\n           and exists (select 1 from public.documents d where d.storage_bucket = bucket_id and d.storage_path = name))\n  $p$;\n  execute $p$\n    create policy dasilva_documents_insert on storage.objects for insert to authenticated\n    with check (bucket_id = 'documents'\n                and app.can_write_entity(((storage.foldername(name))[1])::uuid, (storage.foldername(name))[2]))\n  $p$;\n  execute $p$\n    create policy dasilva_photos_read on storage.objects for select to authenticated\n    using (bucket_id = 'vehicle-photos'\n           and app.has_perm(((storage.foldername(name))[1])::uuid, 'inventory.view'))\n  $p$;\n  execute $p$\n    create policy dasilva_photos_insert on storage.objects for insert to authenticated\n    with check (bucket_id = 'vehicle-photos'\n                and app.has_perm(((storage.foldername(name))[1])::uuid, 'inventory.edit'))\n  $p$;\n  execute $p$\n    create policy dasilva_photos_delete on storage.objects for delete to authenticated\n    using (bucket_id = 'vehicle-photos'\n           and app.has_perm(((storage.foldername(name))[1])::uuid, 'inventory.edit'))\n  $p$;\nend $$;\n"},{"name":"20261022001000_admin.sql","sql":"-- =============================================================================\n-- Da Silva OS — Administración: usuarios, configuración, exportaciones\n-- =============================================================================\n\n-- Auditoría de catálogos y parámetros sensibles -------------------------------\ncreate trigger aging_buckets_audit after insert or update or delete on public.aging_buckets\n  for each row execute function app.audit_row();\ncreate trigger exchange_rates_audit after insert or update or delete on public.exchange_rates\n  for each row execute function app.audit_row();\ncreate trigger cash_accounts_audit after insert or update on public.cash_accounts\n  for each row execute function app.audit_row();\ncreate trigger brands_audit after insert or update on public.brands\n  for each row execute function app.audit_row();\ncreate trigger branches_audit after insert or update on public.branches\n  for each row execute function app.audit_row();\ncreate trigger organizations_audit after update on public.organizations\n  for each row execute function app.audit_row();\n\n-- Moneda base: no se cambia una vez que existen importes convertidos a ella.\ncreate or replace function app.organizations_guard()\nreturns trigger language plpgsql as $$\nbegin\n  if new.base_currency is distinct from old.base_currency and not app.is_trusted()\n     and (exists (select 1 from public.vehicle_costs where org_id = new.id)\n          or exists (select 1 from public.deals where org_id = new.id)) then\n    raise exception 'La moneda base no puede cambiarse: ya existen importes registrados en %', old.base_currency\n      using errcode = '23514';\n  end if;\n  if new.is_demo is distinct from old.is_demo and not app.is_trusted() then\n    raise exception 'El indicador de demostración no puede modificarse' using errcode = '42501';\n  end if;\n  return new;\nend $$;\ncreate trigger organizations_guard before update on public.organizations\n  for each row execute function app.organizations_guard();\n\n-- Rol de director y último director ------------------------------------------\n-- Sólo un director asigna o retira el rol de director, y la organización no\n-- puede quedarse sin un director activo.\ncreate or replace function app.memberships_role_guard()\nreturns trigger language plpgsql as $$\ndeclare\n  v_remaining integer;\nbegin\n  if app.is_trusted() then\n    return coalesce(new, old);\n  end if;\n  if (new.role = 'director' or (tg_op = 'UPDATE' and old.role = 'director'))\n     and coalesce(app.user_role(new.org_id), '') <> 'director' then\n    raise exception 'Sólo un director puede asignar o retirar el rol de director' using errcode = '42501';\n  end if;\n  if tg_op = 'UPDATE' and old.role = 'director' and old.is_active\n     and (new.role <> 'director' or not new.is_active) then\n    select count(*) into v_remaining from public.memberships\n    where org_id = old.org_id and role = 'director' and is_active and id <> old.id;\n    if v_remaining = 0 then\n      raise exception 'La organización debe conservar al menos un director activo' using errcode = '23514';\n    end if;\n  end if;\n  return new;\nend $$;\ncreate trigger memberships_role_guard before insert or update on public.memberships\n  for each row execute function app.memberships_role_guard();\n\n-- Alta de miembro ---------------------------------------------------------------\n-- La cuenta de acceso se crea en Supabase Auth desde el servidor (service role).\n-- Esta función crea el perfil y la membresía, verificando el permiso.\ncreate or replace function public.rpc_member_add(p_org uuid, p_user uuid, p_full_name text, p_role text)\nreturns uuid\nlanguage plpgsql security definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_id uuid;\nbegin\n  perform app.require_perm(p_org, 'users.manage');\n  if p_role = 'director' and coalesce(app.user_role(p_org), '') <> 'director' then\n    perform app.fail('Sólo un director puede asignar el rol de director');\n  end if;\n  if not exists (select 1 from auth.users where id = p_user) then\n    perform app.fail('La cuenta de acceso no existe');\n  end if;\n  if length(trim(coalesce(p_full_name, ''))) < 3 then\n    perform app.fail('Indique el nombre completo');\n  end if;\n  insert into public.user_profiles (id, full_name) values (p_user, trim(p_full_name))\n  on conflict (id) do nothing;\n  insert into public.memberships (org_id, user_id, role) values (p_org, p_user, p_role)\n  on conflict (org_id, user_id) do update set role = excluded.role, is_active = true\n  returning id into v_id;\n  perform app.audit(p_org, 'usuario_alta', 'membership', v_id::text,\n                    'Alta de ' || trim(p_full_name) || ' con rol ' || p_role, null, null);\n  return v_id;\nend $$;\n\n-- Registro de exportaciones ---------------------------------------------------\ncreate or replace function public.rpc_report_export_log(p_org uuid, p_report text, p_filters jsonb, p_rows integer)\nreturns void\nlanguage plpgsql security definer\nset search_path = public, pg_temp\nas $$\nbegin\n  perform app.require_perm(p_org, 'reports.export');\n  perform app.audit(p_org, 'reporte_exportado', 'report', p_report,\n                    'Exportación de «' || p_report || '» (' || p_rows || ' filas)', null, p_filters);\nend $$;\n\n-- Configuración de la organización: actualización atómica de tramos ----------\ncreate or replace function public.rpc_aging_buckets_set(p_org uuid, p_limits integer[])\nreturns void\nlanguage plpgsql security definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  i integer;\n  v_prev integer := 0;\n  v_n integer := coalesce(array_length(p_limits, 1), 0);\nbegin\n  perform app.require_perm(p_org, 'settings.manage');\n  if v_n < 1 or v_n > 8 then\n    perform app.fail('Defina entre 1 y 8 límites de tramo');\n  end if;\n  for i in 1 .. v_n loop\n    if p_limits[i] is null or p_limits[i] <= v_prev then\n      perform app.fail('Los límites deben ser crecientes y mayores que cero');\n    end if;\n    v_prev := p_limits[i];\n  end loop;\n  delete from public.aging_buckets where org_id = p_org;\n  insert into public.aging_buckets (org_id, label, min_days, max_days, sort_order) values (p_org, 'Al día', 0, 0, 1);\n  v_prev := 0;\n  for i in 1 .. v_n loop\n    insert into public.aging_buckets (org_id, label, min_days, max_days, sort_order)\n    values (p_org, (v_prev + 1) || '–' || p_limits[i] || ' días', v_prev + 1, p_limits[i], i + 1);\n    v_prev := p_limits[i];\n  end loop;\n  insert into public.aging_buckets (org_id, label, min_days, max_days, sort_order)\n  values (p_org, 'Más de ' || v_prev || ' días', v_prev + 1, null, v_n + 2);\nend $$;\n\nrevoke all on function public.rpc_member_add(uuid, uuid, text, text) from public, anon;\nrevoke all on function public.rpc_report_export_log(uuid, text, jsonb, integer) from public, anon;\nrevoke all on function public.rpc_aging_buckets_set(uuid, integer[]) from public, anon;\ngrant execute on function public.rpc_member_add(uuid, uuid, text, text) to authenticated;\ngrant execute on function public.rpc_report_export_log(uuid, text, jsonb, integer) to authenticated;\ngrant execute on function public.rpc_aging_buckets_set(uuid, integer[]) to authenticated;\n\n-- Tipos de documento: marcar o desmarcar como obligatorio.\ncreate policy document_types_update on public.document_types for update to authenticated\n  using (app.has_perm(org_id, 'settings.manage')) with check (app.has_perm(org_id, 'settings.manage'));\ncreate trigger document_types_audit after insert or update on public.document_types\n  for each row execute function app.audit_row();\n\n-- Correos de los miembros (auth.users no es legible por usuarios autenticados).\ncreate or replace function public.rpc_member_emails(p_org uuid)\nreturns table (user_id uuid, email text)\nlanguage plpgsql stable security definer\nset search_path = public, pg_temp\nas $$\nbegin\n  perform app.require_perm(p_org, 'users.manage');\n  return query select m.user_id, u.email::text from public.memberships m join auth.users u on u.id = m.user_id where m.org_id = p_org;\nend $$;\nrevoke all on function public.rpc_member_emails(uuid) from public, anon;\ngrant execute on function public.rpc_member_emails(uuid) to authenticated;\n"}];
